/* store-core.js — extracted from Store.html (was the inline
   <script> block at line 6809).
   Loaded as a CLASSIC script, in this order, un-deferred: these blocks
   share one global lexical scope and later ones read const/let declared
   by earlier ones. Do not add type="module" or defer. */
/* Combined original UI: Supabase data layer only. The legacy screens and fields are intentionally unchanged. */
/* Supabase connection details, kept out of plain View-Source.
   ────────────────────────────────────────────────────────────────
   READ THIS BEFORE TREATING IT AS SECURITY. This is obfuscation, not
   encryption. The browser has to hand Supabase the real values to make any
   request, so anyone with DevTools open can read them from the Network tab in
   seconds. Nothing shipped to a browser can be kept secret from its user.

   What it DOES buy: the key no longer appears as plain text in the page
   source, so it is not picked up by the automated scanners that crawl for
   leaked credentials (they match on the "eyJ" JWT prefix — reversing the
   string before base64 is what breaks that signature), and it is not there to
   be copy-pasted by someone idly reading the source.

   What actually protects the data is Row Level Security on every table in the
   Supabase project. The anon key is designed to be public; RLS is the thing
   that decides what a holder of it may read or write. If RLS is off anywhere,
   this code change buys nothing real. */
function sbDecode_(parts){
  return atob(parts.join('')).split('').reverse().join('');
}
const SUPABASE_URL = sbDecode_(['b2MuZXNhYmFwdXMuamlk','dmhramVqa2p4eGdqZ3ps','ZGovLzpzcHR0aA==']);
const SUPABASE_ANON_KEY = sbDecode_(['a1dBeHBISk1DZ0RRUkYyZjdFUUU2WEY0Ti0yaEpKb0dkLWk4N2U2aTR3by4w','M053QVRNMllUTndFak02SUNjNFZtSXNjRE13VURPd0FUTzNFak9pUVhZcEpD','TGk0MmJ1Rm1JNklTWnM5bWNpd2lJcWxHWjJoMmFxVm1hcnBHZTRkbWFucEhi','a3BtSTZJaVpsSm5Jc0lTWnpGbVloQlhkekppT2lNM2NwSnllLjlKQ1ZYcGtJ','NklDYzVSbklzSWlOMUl6VUlKaU9pY0diaEp5ZQ==']);
const SB_READY = !SUPABASE_URL.includes('YOUR_PROJECT') && !SUPABASE_ANON_KEY.includes('YOUR_SUPABASE');
const SB = SB_READY ? window.supabase.createClient(SUPABASE_URL, SUPABASE_ANON_KEY) : null;
const byId = id => document.getElementById(id);
const escText = v => String(v ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));
/* Searchable <select>: a text box sits over the (hidden) select, typing
   filters its options, and only an option from the list can be taken — free
   text is thrown away and the box goes back to the current choice. The select
   stays the single source of truth: a pick sets its value and fires 'change',
   and code that sets .value, rebuilds the options or toggles disabled is
   mirrored straight back into the box, so no caller has to know about it. */
const ssList_=(()=>{let el=null;return()=>{if(!el){el=document.createElement('div');el.className='ss-list';el.hidden=true;document.body.appendChild(el);}return el;};})();
function makeSearchableSelect(sel){
  if(!sel||sel.dataset.ssDone)return;
  sel.dataset.ssDone='1';
  const inp=document.createElement('input');
  inp.type='text';inp.autocomplete='off';inp.className='ss-input'+(sel.classList.contains('table-input')?' table-input':'');
  sel.insertAdjacentElement('afterend',inp);
  sel.style.display='none';
  const native=Object.getOwnPropertyDescriptor(HTMLSelectElement.prototype,'value');
  const sync=()=>{
    const o=sel.selectedOptions[0];
    inp.value=(o&&o.value!=='')?o.textContent.trim():'';
    inp.placeholder=(sel.options[0]&&sel.options[0].value==='')?sel.options[0].textContent.trim():'Search...';
    inp.disabled=sel.disabled;inp.title=sel.title||inp.value;
  };
  Object.defineProperty(sel,'value',{configurable:true,get(){return native.get.call(sel);},set(v){native.set.call(sel,v);sync();}});
  new MutationObserver(sync).observe(sel,{childList:true,subtree:true,attributes:true,attributeFilter:['disabled','title']});
  sync();
  let open=false,hl=0,shown=[];
  const list=ssList_();
  const place=()=>{
    const r=inp.getBoundingClientRect(),w=Math.min(Math.max(r.width,240),innerWidth-8);
    list.style.width=w+'px';
    list.style.left=Math.max(4,Math.min(r.left,innerWidth-w-4))+'px';
    const below=innerHeight-r.bottom;
    list.style.top=(below<200&&r.top>below)?Math.max(4,r.top-2-Math.min(list.scrollHeight,240))+'px':(r.bottom+2)+'px';
  };
  const render=()=>{
    const q=inp.value.trim().toLowerCase();
    shown=[...sel.options].filter(o=>!q||o.textContent.toLowerCase().includes(q)||o.value.toLowerCase().includes(q));
    hl=Math.min(hl,Math.max(0,shown.length-1));
    list.innerHTML=shown.length?shown.map((o,i)=>'<div class="ss-opt'+(i===hl?' hl':'')+'" data-i="'+i+'">'+escText(o.textContent.trim())+'</div>').join(''):'<div class="ss-empty">List me nahi mila</div>';
    place();
    list.querySelector('.ss-opt.hl')?.scrollIntoView({block:'nearest'});
  };
  const close=()=>{
    if(!open)return;open=false;list.hidden=true;
    document.removeEventListener('pointerdown',outside,true);
    removeEventListener('scroll',place,true);removeEventListener('resize',place);
    sync(); // whatever was typed but not picked is discarded
  };
  const pick=o=>{
    if(o&&o.value!==native.get.call(sel)){native.set.call(sel,o.value);sel.dispatchEvent(new Event('change',{bubbles:true}));}
    close();
  };
  const outside=e=>{if(e.target!==inp&&!list.contains(e.target))close();};
  const openList=()=>{
    if(open||inp.disabled)return;open=true;
    list.onmousedown=e=>e.preventDefault(); // keep focus in the box
    list.onclick=e=>{const d=e.target.closest('.ss-opt');if(d)pick(shown[+d.dataset.i]);};
    hl=Math.max(0,[...sel.options].indexOf(sel.selectedOptions[0]));
    inp.select();list.hidden=false;render();
    document.addEventListener('pointerdown',outside,true);
    addEventListener('scroll',place,true);addEventListener('resize',place);
  };
  inp.addEventListener('focus',openList);
  inp.addEventListener('click',openList);
  inp.addEventListener('input',()=>{if(!open)openList();hl=0;render();});
  inp.addEventListener('keydown',e=>{
    if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();if(!open)return openList();if(shown.length){hl=(hl+(e.key==='ArrowDown'?1:-1)+shown.length)%shown.length;render();}}
    else if(e.key==='Enter'){e.preventDefault();if(open&&shown[hl])pick(shown[hl]);}
    else if(e.key==='Escape'){if(open){e.preventDefault();close();}}
    else if(e.key==='Tab')close();
  });
}
/* Clicking into an editable box that only holds a zero ("0", "0.00") empties
   it, so a figure can be typed straight in without deleting the 0 first. Left
   empty, the original zero goes back on blur, so every total/save path still
   reads 0 exactly as before. Delegated on document, so rows added later are
   covered too. */
(function zeroClearOnFocus(){
  const isZero=v=>/^\s*0+(\.0+)?\s*$/.test(v);
  document.addEventListener('focusin',e=>{
    const el=e.target;
    if(!(el instanceof HTMLInputElement)||(el.type!=='number'&&el.type!=='text'))return;
    if(el.readOnly||el.disabled||!isZero(el.value))return;
    el.dataset.zeroCleared=el.value;
    el.value='';
  });
  document.addEventListener('focusout',e=>{
    const el=e.target;
    if(!(el instanceof HTMLInputElement)||el.dataset.zeroCleared==null)return;
    if(el.value==='')el.value=el.dataset.zeroCleared;
    delete el.dataset.zeroCleared;
  });
})();
function showToast(message, type='success'){
  // #storeInterface and #fullPurchasePanel are toggled with display:none on
  // whichever one isn't active (see activatePanel()) — #toastStack lives
  // inside #storeInterface, so any toast raised while the Purchase
  // Requirement / PO Generation panel (#fullPurchasePanel) is open was
  // silently appended into a display:none container and never seen. Route
  // to whichever panel's own toast container is actually visible.
  const fullActive=byId('fullPurchasePanel')&&byId('fullPurchasePanel').style.display!=='none';
  const stack=byId(fullActive?'p_toastContainer':'toastStack')||byId('toastStack')||byId('p_toastContainer');
  if(stack){const el=document.createElement('div');el.className='toast '+type;el.innerHTML=message;stack.appendChild(el);setTimeout(()=>el.remove(),4500)}else alert(String(message).replace(/<[^>]+>/g,''));
}
function dbError(error){console.error(error);showToast('Supabase error: '+(error?.message||error),'error');}
/* ================================================================
   CSV EXPORT HELPERS — used by Print History/Reports (Admin-only),
   Master Data Management and Repair Items Tracker (anyone).
================================================================ */
function downloadCSV(filename,rows2d){
  const esc=v=>{
    const s=v==null?'':String(v);
    return /[",\n\r]/.test(s)?'"'+s.replace(/"/g,'""')+'"':s;
  };
  const csv=rows2d.map(row=>row.map(esc).join(',')).join('\r\n');
  const blob=new Blob(['﻿'+csv],{type:'text/csv;charset=utf-8;'});
  const url=URL.createObjectURL(blob);
  const a=document.createElement('a');
  a.href=url;a.download=filename;
  document.body.appendChild(a);a.click();document.body.removeChild(a);
  setTimeout(()=>URL.revokeObjectURL(url),1000);
}
// Exports a table's currently-visible rows exactly as shown on screen
// (respects any active search/filter that hides rows via style.display).
// Placeholder/subtotal rows whose cell count doesn't match the header are
// skipped automatically; skipTrailing drops non-data action columns
// (edit/delete buttons) from the right edge.
function exportTableCSV(tbodyId,filename,skipTrailing=1){
  const tb=byId(tbodyId);if(!tb)return false;
  const table=tb.closest('table');if(!table)return false;
  const theadCells=[...table.querySelectorAll('thead th')];
  const total=theadCells.length;
  const keepCount=Math.max(0,total-skipTrailing);
  const headers=theadCells.slice(0,keepCount).map(th=>th.textContent.replace(/\s+/g,' ').trim());
  const rows=[...tb.querySelectorAll('tr')].filter(tr=>tr.style.display!=='none'&&tr.children.length===total);
  if(!rows.length){showToast('⚠️ Export ke liye koi data nahi hai — pehle filter/search check karein','warn');return false;}
  const data=rows.map(tr=>[...tr.children].slice(0,keepCount).map(td=>td.textContent.replace(/\s+/g,' ').trim()));
  downloadCSV(filename,[headers,...data]);
  showToast('📥 CSV downloaded — '+rows.length+' rows');
  return true;
}
function today(){return new Date().toISOString().slice(0,10)}
// India financial year (Apr–Mar), e.g. sarvFinancialYear() -> "2026-27",
// sarvFinancialYear(true) -> "26-27". Rolls over automatically with the date.
function sarvFinancialYear(shortStart){
  const d=new Date(),y=d.getFullYear(),startY=d.getMonth()>=3?y:y-1,endY=startY+1;
  return (shortStart?String(startY).slice(-2):String(startY))+'-'+String(endY).slice(-2);
}
const SARV_DOC_NO_CFG={
  INWARD:{table:'inward_entries',col:'document_no',prefix:()=>'SIHF-II/'+sarvFinancialYear()+'/'},
  NB:{table:'inward_entries',col:'document_no',prefix:()=>'NB/2/'+sarvFinancialYear()+'/'},
  OUTWARD:{table:'outward_entries',col:'document_no',prefix:()=>'SIHF-II/OUT/'+sarvFinancialYear()+'/'},
  ISSUE:{table:'outward_entries',col:'document_no',prefix:()=>'SIHF-II/ISSUE/'+sarvFinancialYear()+'/'},
  REQ:{table:'purchase_requirements',col:'req_no',prefix:()=>'PR/'+sarvFinancialYear(true)+'/'},
  PO:{table:'purchase_orders',col:'po_no',prefix:()=>'PO/U-2/'},
};
// Document numbers follow a fixed prefix (financial year baked in for most
// kinds) + a per-FY running sequence, computed client-side by scanning
// existing numbers under that same prefix — so each FY's sequence starts
// fresh at 001 the moment the prefix itself changes.
async function nextNo(kind){
  const cfg=SARV_DOC_NO_CFG[kind];
  if(!SB_READY||!cfg) return kind+'-'+new Date().getFullYear()+'-'+String(Date.now()).slice(-5);
  const prefix=cfg.prefix();
  try{
    const {data,error}=await SB.from(cfg.table).select(cfg.col).ilike(cfg.col,prefix+'%').limit(5000);
    if(error)throw error;
    let maxSeq=0;
    (data||[]).forEach(row=>{
      const val=String(row[cfg.col]||'');
      if(!val.startsWith(prefix))return;
      const m=val.slice(prefix.length).match(/^(\d+)/);
      if(m){const n=parseInt(m[1],10);if(n>maxSeq)maxSeq=n;}
    });
    return prefix+String(maxSeq+1).padStart(3,'0');
  }catch(e){
    console.warn('[SARV] nextNo lookup failed, falling back to 001:',e.message||e);
    return prefix+'001';
  }
}
let sarvPoCatalog=[],sarvPendingRequirements=[],sarvEditingRequirementId=null,sarvGeneratedPos=[];
// PO id -> {lines:[]}, cached alongside sarvGeneratedPos so the Generated POs
// search/status filter can re-render without refetching the line items.
let sarvPoLineMap={};
// Admin-only view toggle for fully-received / short-closed POs.
let sarvShowReceivedPos=false;
let sarvItemCatalog=[];     // Global item master cache for auto-fill
let sarvEmployeeCatalog=[]; // Global employee cache for PR form auto-fill
let sarvSupplierCatalog=[]; // Global supplier master cache for auto-fill

/* Resolves whatever is sitting in an Item Name box to ONE Item Master row.

   The dropdown gives same-named rows an "NAME [ITEM_CODE]" value (see
   itemDropdownValue) because that is the only way a <datalist> can say WHICH
   of them was picked — so that tagged form is tried first, and it is what
   stops a duplicate name from always resolving to the first row.
   A bare name still works (unique names, a hand-typed name, a saved PR/PO
   line being reloaded), and so does a bare item_code. */
function lookupItem(name){
  const raw=String(name||'').trim();
  if(!raw)return null;
  const n=raw.toLowerCase();
  const eq=(a,b)=>String(a||'').trim().toLowerCase()===b;
  // "NAME [CODE]" — the exact row the user picked out of the popup.
  const tagged=raw.match(/^(.*)\s*\[([^\[\]]+)\]$/);
  if(tagged){
    const tName=tagged[1].trim().toLowerCase(),tCode=tagged[2].trim().toLowerCase();
    const exact=sarvItemCatalog.find(it=>eq(it.item_code,tCode)&&eq(it.name,tName));
    if(exact)return exact;
    const byTaggedCode=sarvItemCatalog.find(it=>eq(it.item_code,tCode));
    if(byTaggedCode)return byTaggedCode;
  }
  return sarvItemCatalog.find(it=>eq(it.name,n))
      ||sarvItemCatalog.find(it=>eq(it.item_code,n))
      ||null;
}
function lookupEmployee(code){
  const c=(code||'').trim().toUpperCase();
  if(!c)return null;
  return sarvEmployeeCatalog.find(e=>(e.emp_code||'').toUpperCase()===c)||null;
}
/* Fallback for records that stored only the receiver's NAME (Designation /
   Department had no column on outward_entries until now, and no Emp Code was
   kept either) — used when reopening such an entry for edit. */
function lookupEmployeeByName(name){
  const n=(name||'').trim().toLowerCase();
  if(!n)return null;
  return sarvEmployeeCatalog.find(e=>(e.person_name||'').trim().toLowerCase()===n)||null;
}
function lookupSupplier(name){
  const n=(name||'').trim().toLowerCase();
  return sarvSupplierCatalog.find(s=>(s.supplier_name||'').toLowerCase()===n)||null;
}
/* Our own manufacturing units, as they appear in the Supplier Master. Material
   coming in from these is an internal stock transfer, not a purchase, so the
   GST rules on an INWARD entry are inverted for them (see saveInwardWithPdf).
   Matching is case-insensitive and ignores spacing around the unit suffix, so
   "Sarv India Home Furnishing Unit - I" and "UNIT-I" both hit. */
const SARV_OWN_UNIT_SUPPLIERS=[
  'SARV INDIA HOME FURNISHING UNIT-I',
  'SARV INDIA HOME FURNISHING UNIT-II'
];
function normSupplierName_(name){
  return String(name||'').toUpperCase().replace(/[\s-]+/g,' ').trim();
}
function isSarvOwnUnitSupplier(name){
  const n=normSupplierName_(name);
  return !!n&&SARV_OWN_UNIT_SUPPLIERS.some(u=>normSupplierName_(u)===n);
}
// Master Data lock: outside the Master Data tab itself, any field tied to an
// Item / Supplier / Employee master dropdown may only hold a value that
// already exists in that master list — anything else is cleared on blur so
// stray/typo values can't sneak into transactions. New values must be added
// via the Master Data tab first.
function lockToMasterList(el,getValidValues){
  if(!el||el.dataset.masterLock)return;
  el.dataset.masterLock='1';
  el.addEventListener('blur',function(){
    // A field the form itself has locked (a fixed ISSUE value) holds a value
    // nobody typed, so it is exempt — the check is here to stop typos.
    if(this.readOnly||this.disabled)return;
    const val=(this.value||'').trim();
    if(!val)return;
    const ok=getValidValues().some(v=>(v||'').trim().toLowerCase()===val.toLowerCase());
    if(!ok){
      this.value='';
      showToast(`❌ "${val}" Master Data mein nahi mila — pehle Master Data tab se add karein`,'warn');
    }
  });
}
function renderReqEmpDetails(){
  const box=byId('p_reqEmpDetails');if(!box)return;
  const name=(byId('p_reqPersonName')?.value||'').trim();
  const desig=(byId('p_reqDesignation')?.value||'').trim();
  const dept=(byId('p_reqDepartment')?.value||'').trim();
  const contact=(byId('p_reqContact')?.value||'').trim();
  if(!name&&!desig&&!dept&&!contact){
    box.innerHTML='<span style="color:#94a3b8;font-weight:400;">Employee Code enter karein — Name / Designation / Department / Contact yahan auto-fill honge</span>';
    return;
  }
  const parts=[];
  if(name)parts.push('&#128100; <b>'+escText(name)+'</b>');
  if(desig)parts.push(escText(desig));
  if(dept)parts.push(escText(dept));
  if(contact)parts.push('&#128222; '+escText(contact));
  box.innerHTML=parts.join(' &nbsp;&middot;&nbsp; ');
}
function onEmpCodeInput(val){
  const emp=lookupEmployee(val);
  if(!emp){
    if(!(val||'').trim()){
      ['p_reqPersonName','p_reqDesignation','p_reqContact'].forEach(id=>{const e=byId(id);if(e)e.value='';});
      if(byId('p_reqDepartment'))byId('p_reqDepartment').value='';
      renderReqEmpDetails();
    }
    return;
  }
  const s=(id,v)=>{const e=byId(id);if(e&&v!=null)e.value=v;};
  s('p_reqPersonName', emp.person_name||'');
  s('p_reqDesignation', emp.designation||'');
  // Department select
  const dept=byId('p_reqDepartment');
  if(dept){
    const want=String(emp.department||'').trim();
    const opts=[...dept.options].map(o=>o.value.trim().toLowerCase());
    let idx=want?opts.indexOf(want.toLowerCase()):0;
    // A department Employee Master has but this fixed list doesn't used to be
    // dropped silently — the PR (and its PDF) then printed no Department.
    // Add it as an option instead, so whatever the master says is kept.
    if(want&&idx<0){dept.add(new Option(want,want));idx=dept.options.length-1;}
    dept.selectedIndex=idx<0?0:idx;
  }
  s('p_reqContact', emp.contact_no||'');
  renderReqEmpDetails();
  showToast(`✅ ${emp.person_name} — ${emp.designation||''} (${emp.department||''})`, 'success');
}

/* The three Receiver fields are read-only, so this is the ONLY thing that
   fills them on a fresh entry (loadOutwardForEdit() fills them on an edit).
   Because they are set programmatically, no 'input' event fires, so a required
   highlight left on them by validateRequiredFields() is cleared by hand here —
   and the locked grey look is restored with it. */
const OUT_RECEIVER_FIELDS=['outReceiverName','outDesignation','outDepartment'];
function setOutReceiverField(id,v){
  const e=byId(id);if(!e)return;
  e.value=v==null?'':v;
  e.style.border='';e.style.background='#f1f5f9';
}
function onOutEmpCodeInput(val){
  const emp=lookupEmployee(val);
  if(!emp){
    // Code box emptied — drop the stale employee with it, since nothing else
    // can correct these fields now that they can't be typed in.
    if(!(val||'').trim())OUT_RECEIVER_FIELDS.forEach(id=>setOutReceiverField(id,''));
    return;
  }
  setOutReceiverField('outReceiverName', emp.person_name||'');
  setOutReceiverField('outDesignation',  emp.designation||'');
  setOutReceiverField('outDepartment',   emp.department||'');
  showToast(`✅ ${emp.person_name} — ${emp.designation||''} (${emp.department||''})`, 'success');
}
/* lockName: only true once the user has actually COMMITTED a pick (the
   'change' event — Enter on a dropdown option, clicking one, or leaving the
   field). It must never be set from the 'input' event: while the Item Name
   dropdown is open, the browser fires 'input' for every option the user
   arrows onto, so locking there froze the row on the FIRST option in the list
   and the real pick (and any further typing) could no longer land. */
function applyItemAutofill(nameVal,tr,prefix,lockName=false){
  const item=lookupItem(nameVal);
  const g=(cls)=>tr.querySelector(cls);
  const s=(cls,val)=>{const e=g(cls);if(e&&val!=null)e.value=val;};
  if(!item){
    // Typed value doesn't match any Item Master entry — clear the
    // disabled auto-fill-only fields instead of leaving a stale
    // Description/Category from whatever was previously selected.
    if(prefix==='inward'){s('.item-desc','');s('.item-cat','');}
    else if(prefix==='outward'){s('.out-item-desc','');s('.out-item-cat','');}
    // Same for a PR row: the name is no longer locked the instant a match is
    // seen, so a row CAN now end up with a name that matches nothing (typed
    // past an option, or cleared by the Master Data check on blur). Its
    // Description/Category/UOM must not keep the last matched item's values.
    else if(prefix==='purchase'){s('.col-desc','');s('.col-cat','');s('.col-uom','');}
    if(tr&&tr.dataset)delete tr.dataset.itemId;
    return;
  }
  // Pin the row to the exact Item Master row that was resolved. Two rows can
  // share a name, so the save path must not re-resolve by name later — it
  // would bind the line back to the first of the duplicates (see ensureItem).
  if(tr&&tr.dataset)tr.dataset.itemId=item.id||'';
  if(prefix==='inward'){
    s('.item-desc', item.description||'');
    if(!g('.item-make')?.value) s('.item-make', item.make||'');
    s('.item-cat',  item.category||'');
    s('.item-uom',  item.uom||'');
    const pe=g('.list-price-field'); if(pe&&(pe.value===''||pe.value==='0'))pe.value=item.rate||0;
    const re=g('.rate-field');       if(re&&(re.value===''||re.value==='0'))re.value=item.rate||0;
    // GST now comes off the Item Master rather than being picked per line —
    // the rate belongs to the part, so the row follows whatever the master
    // says for it. ensureSelectOption_ covers a rate not in the fixed list.
    // INWARD NB is the exception: its GST stays pinned at 0 (applyInwardNbGstLock).
    const ge=g('.item-gst-field');
    const isNb=(byId('entryTypeSelect')?.value||'')==='INWARD NB';
    if(ge&&!isNb){const gv=String(itemGst_(item));
      if(![...ge.options].some(o=>o.value===gv))ge.add(new Option(gv,gv));
      ge.value=gv;}
    updateStoreTotals();
  } else if(prefix==='outward'){
    s('.out-item-desc', item.description||'');
    if(!g('.out-item-make')?.value) s('.out-item-make', item.make||'');
    s('.out-item-cat',  item.category||'');
    s('.out-qty-uom',   item.uom||'');
    updateOutTotals();
  } else if(prefix==='purchase'){
    s('.col-desc', item.description||'');
    if(!g('.col-make')?.value) s('.col-make', item.make||'');
    s('.col-cat', item.category||'');
    s('.col-uom', item.uom||'');
    // Once a real master item is PICKED (committed, not merely highlighted in
    // the open dropdown), lock the name so it can't be hand-edited into
    // something else — delete the row and re-add to pick again.
    const nameEl=g('.col-name');
    if(lockName&&nameEl){nameEl.readOnly=true;nameEl.style.background='#f1f5f9';nameEl.style.cursor='not-allowed';nameEl.title='Item locked — delete this row and add a new one to pick a different item';}
    applyCategoryPurchaser(item.category);
    refreshPurchaseTotals();
  }
  // A duplicated name arrives here as "NAME [ITEM_CODE]" (that tag is how the
  // dropdown identifies which of the same-named rows was picked). Now that it
  // has been resolved, put the plain name back: that is what gets saved and
  // printed, and the Master Data check on blur only recognises plain names.
  // Only on a committed pick — rewriting the box mid-typing would fight the
  // user, and dataset.itemId already holds the identity.
  if(lockName){
    const nameSel=prefix==='inward'?'.item-name':(prefix==='outward'?'.out-item-name':'.col-name');
    const el=g(nameSel);
    if(el&&item.name&&el.value!==item.name)el.value=item.name;
  }
}

/* ── Category → Purchaser auto-select ─────────────────────────────
   Purchaser Name is a header field but the category comes off an item row, so
   the two only line up when every row belongs to the same buyer. The rule:
   fill it from the first mapped category, then leave it alone. A later row
   mapping to a DIFFERENT purchaser is flagged rather than silently
   overwritten — one PR cannot belong to two buyers, and quietly changing a
   field the user already saw is how a requirement reaches the wrong person.
   Manual selection always wins; this never overwrites a hand-picked name. */
let sarvCategoryPurchasers={};          // UPPER(TRIM(category)) -> purchaser name
let sarvPurchaserAutoFilled=false;      // did WE set the field, or did a person?
let sarvCatPurLoaded=false;             // has the map been fetched at all yet?
const sarvCatPurWarned=new Set();       // so the same complaint isn't repeated

async function loadCategoryPurchasers(){
  if(!SB_READY)return;
  try{
    const q=await SB.from('category_purchasers').select('category,purchaser_name');
    if(q.error)throw q.error;
    const map={};
    (q.data||[]).forEach(r=>{
      const c=String(r.category||'').trim().toUpperCase();
      const p=String(r.purchaser_name||'').trim();
      if(c&&p)map[c]=p;              // blank purchaser_name = not mapped yet
    });
    sarvCategoryPurchasers=map;
    sarvCatPurLoaded=true;
    const n=Object.keys(map).length;
    console.log('[SARV] category_purchasers loaded: '+n+' of '+((q.data||[]).length)+' categories have a purchaser');
  }catch(e){
    // Missing table or blocked read must not break the PR form — the field
    // simply stays manual.
    console.warn('[SARV] category_purchasers load skipped:',e.message||e);
  }
}
// Inspect from the browser console when a mapping seems not to apply.
window.sarvShowCategoryPurchasers=function(){
  console.table(Object.keys(sarvCategoryPurchasers).map(c=>({category:c,purchaser:sarvCategoryPurchasers[c]})));
  return sarvCategoryPurchasers;
};

// Said once per distinct problem — a toast on every keystroke would be noise,
// but staying silent is what made this look broken rather than unconfigured.
function catPurWarnOnce_(key,msg,kind){
  if(sarvCatPurWarned.has(key))return;
  sarvCatPurWarned.add(key);
  showToast(msg,kind||'warn');
}

function applyCategoryPurchaser(category){
  const sel=byId('p_reqGeneratedBy');if(!sel)return;
  const cat=String(category||'').trim();
  if(!cat)return;
  if(!sarvCatPurLoaded){
    catPurWarnOnce_('notloaded','⚠️ Category-wise Purchaser list load nahi hui — page refresh karein','warn');
    return;
  }
  // Nothing mapped at all almost always means the table was seeded but never
  // filled in. Saying so beats leaving the field mysteriously blank.
  if(!Object.keys(sarvCategoryPurchasers).length){
    catPurWarnOnce_('empty','⚠️ Kisi bhi category ka Purchaser set nahi hai — Supabase ke category_purchasers table me purchaser_name bharein','warn');
    return;
  }
  const want=sarvCategoryPurchasers[cat.toUpperCase()];
  if(!want){
    catPurWarnOnce_('nocat:'+cat.toUpperCase(),'ℹ️ "'+cat+'" category ka Purchaser set nahi hai — category_purchasers table me add karein','warn');
    return;
  }
  // Matched case- and space-insensitively, and the dropdown's OWN spelling is
  // used. An exact compare meant "VISHAL JI" in the table silently matched
  // nothing against "Vishal ji" in the list — which looked like a dead feature.
  const norm=s=>String(s||'').trim().toUpperCase().replace(/\s+/g,' ');
  const opt=[...sel.options].find(o=>o.value&&norm(o.value)===norm(want));
  if(!opt){
    catPurWarnOnce_('noopt:'+norm(want),'⚠️ "'+want+'" Purchaser dropdown me nahi hai — category_purchasers me spelling theek karein','warn');
    return;
  }
  if(!sel.value){
    sel.value=opt.value;sarvPurchaserAutoFilled=true;
    showToast('👤 Purchaser auto-select: '+opt.value+' ('+cat+')');
    return;
  }
  if(norm(sel.value)===norm(opt.value))return;   // already right
  if(sarvPurchaserAutoFilled){
    // We filled it from an earlier row and this row disagrees. Keep the first
    // one and say so — the user decides which is right.
    showToast('⚠️ "'+cat+'" ka Purchaser "'+opt.value+'" hai, par PR par "'+sel.value+'" laga hai. Zaroorat ho to khud badlein.','warn');
  }
}
/* ── PO Number picker ────────────────────────────────────────────
   A checkbox dropdown rather than a <select multiple>: several POs can be
   ticked without Ctrl/Cmd-clicking, and the list is narrowed to whatever
   Supplier Name holds. The chosen PO numbers live here, not in the DOM. */
let sarvSelectedPoNos=[];
function getSelectedPoNos(){return [...sarvSelectedPoNos]}
// POs on offer: open ones, narrowed to the typed supplier. A blank supplier
// applies no filter, so the full open list is still reachable.
function poOptionsForSupplier(){
  const sup=(byId('supplierName')?.value||'').trim().toUpperCase();
  if(!sup)return sarvPoCatalog;
  return sarvPoCatalog.filter(po=>String(po.vendor_name||'').trim().toUpperCase()===sup);
}
function renderPoNumberPanel(){
  const panel=byId('poNumberPanel');if(!panel)return;
  const opts=poOptionsForSupplier();
  const sup=(byId('supplierName')?.value||'').trim();
  if(!opts.length){
    panel.innerHTML='<div style="padding:10px;color:#94a3b8;font-size:11px;">'
      +(sup?'"'+escText(sup)+'" ke liye koi open PO nahi mila.':'Koi open PO nahi hai.')
      +'</div>';
  }else{
    panel.innerHTML=opts.map(po=>{
      const checked=sarvSelectedPoNos.includes(po.po_no)?' checked':'';
      return '<label style="display:flex;align-items:center;gap:8px;padding:5px 6px;border-radius:5px;cursor:pointer;font-size:11px;font-weight:600;">'
        +'<input type="checkbox" class="sarv-po-opt" value="'+escText(po.po_no)+'"'+checked+'>'
        +'<span>'+escText(po.po_no)+' <span style="color:#64748b;font-weight:500;">— '+escText(po.vendor_name||'Vendor')+' — '+escText(po.status||'Generated')+'</span></span>'
        +'</label>';
    }).join('');
  }
  panel.querySelectorAll('.sarv-po-opt').forEach(cb=>{
    cb.addEventListener('change',()=>{
      sarvSelectedPoNos=[...panel.querySelectorAll('.sarv-po-opt:checked')].map(x=>x.value);
      updatePoNumberBtnText();
      loadPoIntoInward().catch(dbError);
    });
  });
  updatePoNumberBtnText();
}
function updatePoNumberBtnText(){
  const el=byId('poNumberBtnText');if(!el)return;
  el.textContent=!sarvSelectedPoNos.length?'Without PO'
    :(sarvSelectedPoNos.length===1?sarvSelectedPoNos[0]:sarvSelectedPoNos.length+' POs selected');
  // The one place that knows whether a PO is ticked — so the PR box follows it.
  syncInwPrField();
}
/* ══ WITHOUT PO → RECEIVE AGAINST A PR ═══════════════════════════════
   A PR raised against Purchaser "FIELD BOY" never becomes a purchase order:
   the items are bought over the counter and handed straight in. Such a receipt
   used to be booked with PO Number "Without PO" and nothing at all tying it to
   the requirement it satisfied, so the PR stayed open for ever and nobody could
   tell which entry had met it.

   So: while PO Number reads "Without PO", a PR Number box appears and picking a
   PR fills the item rows exactly as a PO does.

   REQUIRED, not merely offered — but only on a Purchase. A repair Return links
   to its Outward and a Transfer comes from another unit; neither has a PR, and
   demanding one would block both. If you want it compulsory on every nature,
   change inwPrRequired_() to drop the nature test. */
/* Only FIELD BOY requirements are offered here. Every other Purchaser's PR goes
   through the normal quote → approve → PO route, so receiving one "without PO"
   would be a way around the order it is supposed to have. Matched on
   purchase_requirements.purchaser_name, the same column the mobile Purchaser
   login filters on. */
const INW_PR_PURCHASER='FIELD BOY';
let sarvPrCatalog=[];
let sarvSelectedPrNos=[];
/* Pending qty per PR, keyed by req_no: {qty, items, unknown?}. `qty` is the sum
   of each LINE's own shortfall and `items` how many lines still have one — a PR
   is offered in the picker only while qty > 0. Filled by prPendingByReq_. */
let sarvPrPending={};
function getSelectedPrNos(){ return [...sarvSelectedPrNos]; }
// What goes into the saved record's req_no — comma-joined, like po_number.
function inwPrSelected_(){
  if(sarvEditingInwardId)return inwardEditPrNumber_()||'';
  return sarvSelectedPrNos.join(', ');
}
// An edit never re-ticks the picker, so the record's own PR numbers are read
// back off the widget label — exactly how inwardEditPoNumber_ does it for POs.
function inwardEditPrNumber_(){
  const txt=(byId('prNumberBtnText')?.textContent||'').trim();
  return (!txt||txt==='Select PR')?null:txt;
}
function inwPrFieldOn_(){
  /* On an edit the PO picker is deliberately never re-ticked, so
     sarvSelectedPoNos is empty whatever the record actually carries — reading it
     there would demand a PR for every PO-based entry being corrected. The saved
     record's own PO number, off the widget label, is the answer in that case. */
  if(sarvEditingInwardId)return !inwardEditPoNumber_();
  return !sarvSelectedPoNos.length;
}
function inwPrRequired_(){
  return inwPrFieldOn_() && (byId('inwNatureOfInward')?.value||'Purchase')==='Purchase';
}
function lookupPr_(no){
  const n=String(no||'').trim().toUpperCase();
  if(!n)return null;
  return sarvPrCatalog.find(p=>String(p.req_no||'').trim().toUpperCase()===n)||null;
}
// Shows / hides the widget and keeps the ★ honest about whether it is compulsory.
function syncInwPrField(){
  const grp=byId('inwPrNoFieldGroup'),btn=byId('prNumberBtn');
  if(!grp||!btn)return;
  const on=inwPrFieldOn_();
  grp.style.display=on?'':'none';
  // A PO was ticked after PRs had been picked — the PO's rows now own the form,
  // so the stale PR link goes with them.
  if(!on&&sarvSelectedPrNos.length){
    sarvSelectedPrNos=[];
    updatePrNumberBtnText();
    togglePrNumberPanel(false);
    renderInwPrDetails_([]);
  }
  const star=byId('inwPrNoStar');
  if(star)star.style.display=inwPrRequired_()?'':'none';
  btn.title=inwPrRequired_()
    ?'Without PO par receive karne ke liye kam se kam ek PR select karna zaroori hai'
    :'Optional — is receipt ko kisi PR se jodna ho to tick karein';
}
async function loadPrDropdown_(){
  if(!SB_READY)return;
  const q=await SB.from('purchase_requirements').select('*').order('req_no',{ascending:false}).limit(400);
  if(q.error){console.warn('[SARV] PR dropdown unavailable:',q.error.message);return}
  const want=INW_PR_PURCHASER.toUpperCase();
  const candidates=(q.data||[]).filter(p=>
    // FIELD BOY's own requirements only — see INW_PR_PURCHASER above.
    String(p.purchaser_name||'').trim().toUpperCase()===want
    // A Cancelled or Rejected requirement is settled; nothing is received on it.
    && !['Cancelled','Rejected'].includes(String(p.status||''))
  );
  /* A PR whose every item has already come in full has nothing left to
     receive, so it is dropped from the list rather than offered and then
     rejected at Submit. Pending is counted PER ITEM and only shortfalls add up
     — one item received in excess must not cancel out another that is still
     owed, or a PR with real pending work would disappear.

     The entry being edited is excluded from the "already received" history, so
     reopening a receipt never makes its own PR vanish from under it. */
  let pending={};
  try{ pending=await prPendingByReq_(candidates,sarvEditingInwardId); }
  catch(e){
    // A lookup that cannot run must not empty the list — hiding a PR that has
    // real work left is far worse than listing one that is finished. `unknown`
    // says so, and the picker prints the PR without a pending count.
    console.warn('[SARV] PR pending lookup skipped — showing all open PRs:',e.message||e);
    candidates.forEach(p=>{pending[p.req_no]={unknown:true,qty:0,items:0}});
  }
  sarvPrPending=pending;
  sarvPrCatalog=candidates.filter(p=>{
    const v=pending[p.req_no];
    return !v||v.unknown||pNum(v.qty)>0;
  });
  // Drop any ticked PR that is no longer on offer.
  sarvSelectedPrNos=sarvSelectedPrNos.filter(no=>sarvPrCatalog.some(p=>p.req_no===no));
  renderPrNumberPanel();
}
async function prPendingByReq_(prs,excludeInwardId){
  const out={};
  const list=(prs||[]).filter(p=>p&&p.id);
  list.forEach(p=>{out[p.req_no]={qty:0,items:0}});
  if(!list.length)return out;
  const lq=await SB.from('purchase_requirement_lines')
    .select('requirement_id,item_id,requested_qty').in('requirement_id',list.map(p=>p.id));
  if(lq.error)throw lq.error;
  const already=await prReceivedQtys_(list.map(p=>p.req_no),excludeInwardId);
  const noById={};list.forEach(p=>{noById[String(p.id)]=p.req_no});
  (lq.data||[]).forEach(l=>{
    const no=noById[String(l.requirement_id)];if(!no)return;
    const got=(already[String(no).toUpperCase()+'|'+String(l.item_id||'')]||{}).qty||0;
    const short=Math.max(0,pNum(l.requested_qty)-pNum(got));
    if(short>0){out[no].qty+=short;out[no].items++;}
  });
  return out;
}
/* Checkbox list, same shape and behaviour as the PO Number picker — one receipt
   can cover several FIELD BOY requirements, so this is a multi-pick. */
function renderPrNumberPanel(){
  const panel=byId('prNumberPanel');if(!panel)return;
  if(!sarvPrCatalog.length){
    // Said precisely: there may well be PRs, all of them fully received. That
    // reads very differently from "no PRs exist" when somebody is hunting for
    // one they raised yesterday.
    panel.innerHTML='<div style="padding:10px;color:#94a3b8;font-size:11px;">'
      +escText(INW_PR_PURCHASER)+' ki koi aisi PR nahi hai jiska maal abhi aana baaki ho.<br>'
      +'<span style="color:#64748b;">Jo PR poori receive ho chuki hain wo yahan nahi dikhtin.</span></div>';
  }else{
    panel.innerHTML=sarvPrCatalog.map(p=>{
      const checked=sarvSelectedPrNos.includes(p.req_no)?' checked':'';
      const sub=[p.department||'',p.status||'Pending',p.request_date||''].filter(Boolean).join(' — ');
      /* How much is still owed on this PR. Shown because the list now hides
         finished PRs: without it a short list looks like missing data, and with
         it the reason is on the row itself. */
      const pend=sarvPrPending[p.req_no];
      const pendTxt=(pend&&!pend.unknown&&pend.items)
        ? '<span style="margin-left:auto;background:#fef3c7;color:#92400e;border-radius:9px;padding:1px 7px;font-size:10px;font-weight:800;white-space:nowrap;">'
          +pend.items+' item · '+nNum_(pend.qty)+' pending</span>'
        : '';
      return '<label style="display:flex;align-items:center;gap:8px;padding:5px 6px;border-radius:5px;cursor:pointer;font-size:11px;font-weight:600;">'
        +'<input type="checkbox" class="sarv-pr-opt" value="'+escText(p.req_no)+'"'+checked+'>'
        +'<span>'+escText(p.req_no)+' <span style="color:#64748b;font-weight:500;">— '+escText(sub)+'</span></span>'
        +pendTxt
        +'</label>';
    }).join('');
  }
  panel.querySelectorAll('.sarv-pr-opt').forEach(cb=>{
    cb.addEventListener('change',()=>{
      sarvSelectedPrNos=[...panel.querySelectorAll('.sarv-pr-opt:checked')].map(x=>x.value);
      // highlightRequiredField() paints the button red and clears itself on an
      // input/change event the button never fires — so a tick clears it here.
      const b=byId('prNumberBtn');
      if(b&&sarvSelectedPrNos.length){b.style.border='';b.style.background='';}
      updatePrNumberBtnText();
      loadPrsIntoInward().catch(dbError);
    });
  });
  updatePrNumberBtnText();
}
function updatePrNumberBtnText(){
  const el=byId('prNumberBtnText');if(!el)return;
  el.textContent=!sarvSelectedPrNos.length?'Select PR'
    :(sarvSelectedPrNos.length===1?sarvSelectedPrNos[0]:sarvSelectedPrNos.length+' PRs selected');
}
function setSelectedPrNos(list){
  sarvSelectedPrNos=[...new Set((list||[]).filter(Boolean))];
  renderPrNumberPanel();
}
function togglePrNumberPanel(show){
  const panel=byId('prNumberPanel');if(!panel)return;
  const open=(show==null)?panel.style.display==='none':show;
  if(open)renderPrNumberPanel();
  panel.style.display=open?'block':'none';
}
function renderInwPrDetails_(prs,lineCount){
  const box=byId('inwardPoDetails');
  if(!box)return;
  const list=(prs||[]).filter(Boolean);
  if(!list.length){box.style.display='none';box.innerHTML='';return}
  const depts=[...new Set(list.map(p=>String(p.department||'').trim()).filter(Boolean))];
  box.innerHTML='PR <b>'+escText(list.map(p=>p.req_no).join(', '))+'</b>'
    +' · Purchaser: <b>'+escText(INW_PR_PURCHASER)+'</b>'
    +' · Dept: <b>'+escText(depts.join(', ')||'-')+'</b>'
    +' · Items: <b>'+pNum(lineCount)+'</b>'
    +' · Rate aur GST bill se bharein — PR me rate nahi hota.';
  box.style.display='block';
}
/* How much of each PR item has ALREADY been booked in, before this entry.
   The PO side gets this for free from purchase_order_lines.received_qty; a
   requirement has no such counter, so it is summed off the receipts themselves.

   Exactness, and its one limit:
     • inward_lines.req_no, when the database has that column, says which PR a
       LINE belongs to — that is exact, and it is what gets used.
     • Without it the receipt's header req_no is the only link. On a receipt
       covering ONE PR that is still exact. On a receipt covering several, a
       line cannot be attributed to one of them, so it is counted against each —
       which can overstate "already received". Running
       INWARD_PR_LINE_LINK_MIGRATION.sql removes that case entirely.
   Cancelled receipts are skipped: their lines are deleted on cancel anyway,
   this is the same belt-and-braces the stock views use. */
async function prReceivedQtys_(prNos,excludeInwardId){
  const want=new Set((prNos||[]).map(n=>String(n||'').trim().toUpperCase()).filter(Boolean));
  const out={};
  if(!want.size||!SB_READY)return out;
  const add=(prNo,itemId,qty,weight)=>{
    if(!prNo||!itemId)return;
    const k=prNo+'|'+itemId;
    const o=out[k]=out[k]||{qty:0,weight:0};
    o.qty+=pNum(qty);o.weight+=pNum(weight);
  };
  try{
    // Only receipts that name a PR at all — on a store running mostly on POs
    // that is a small slice of the table.
    const run=cols=>SB.from('inward_entries').select('id,req_no,notes,inward_lines('+cols+')').not('req_no','is',null);
    let q=await run('item_id,qty,weight,req_no');
    // A database without inward_lines.req_no rejects the whole select, not just
    // that column, so the narrower shape is tried before giving up.
    if(q.error&&/req_no|column/i.test(q.error.message||''))q=await run('item_id,qty,weight');
    if(q.error)throw q.error;
    (q.data||[]).forEach(e=>{
      // The entry being edited must not count itself as history.
      if(excludeInwardId&&String(e.id)===String(excludeInwardId))return;
      if(isStoreRecordCancelled_(e.notes))return;
      const onEntry=String(e.req_no||'').split(',').map(s=>s.trim().toUpperCase()).filter(n=>want.has(n));
      if(!onEntry.length)return;
      (e.inward_lines||[]).forEach(l=>{
        const own=String(l.req_no||'').trim().toUpperCase();
        if(own&&want.has(own)){add(own,l.item_id,l.qty,l.weight);return;}   // exact
        onEntry.forEach(pr=>add(pr,l.item_id,l.qty,l.weight));              // header-level
      });
    });
  }catch(e){
    // A lookup that cannot run means the strip shows 0 already-received, which
    // is visibly "no history" rather than a wrong number.
    console.warn('[SARV] PR received-qty lookup skipped:',e.message||e);
  }
  return out;
}
/* ══ HOW MUCH OF A PR LINE HAS ACTUALLY COME IN ══════════════════════
   Pooled per item NAME, because one requirement can carry the SAME item name
   on two lines — two sizes typed the same way, or a line split across machines
   — and the receipt totals are keyed by name, not by line. Handing each line
   the whole total would mark both Completed on half the material, so the total
   is pooled once per name and handed out in line order: each line takes up to
   what it asked for, and the last line sharing the name takes whatever is left
   (so an over-receipt still reads as an over-receipt instead of being quietly
   trimmed).

   The pool is both routes a receipt can credit a requirement:
     • poRecvByKey  — through a PO (purchase_order_lines.received_qty, keyed
                      PR no. + item name, the same key the ordered qty uses)
     • prDirectRecv — straight off the PR, a "without PO" receipt booked
                      against the requirement itself (prReceivedQtys_, keyed
                      PR no. + item id, so it is added once per distinct item
                      even when several lines share a name)

   Lifted out of refreshPendingRequirements so that the ✔ Completed badge on
   the Pending Items table and the status prApplyCompletion_ writes onto
   purchase_requirements come from ONE rule — the table and the database can
   never disagree about whether a requirement is finished. */
function prLineReceipts_(req,reqLines,itemMap,poRecvByKey,prDirectRecv){
  const names=itemMap||new Map();
  const poRecv=poRecvByKey||{};
  const direct=prDirectRecv||{};
  const lineRecvKey=line=>String(req.req_no||'')+'|'
    +String(line.item_name||line.name||(names.get(line.item_id)||{}).name||'Item').toLowerCase().trim();
  const poolQty=new Map(),poolLines=new Map(),poolTaken=new Map(),poolSeen=new Map();
  {
    const idsPerKey=new Map();
    (reqLines||[]).forEach(line=>{
      const k=lineRecvKey(line);
      poolLines.set(k,(poolLines.get(k)||0)+1);
      if(!poolQty.has(k)){poolQty.set(k,poRecv[k]||0);idsPerKey.set(k,new Set());}
      const idk=String(req.req_no||'').trim().toUpperCase()+'|'+String(line.item_id||'');
      const seen=idsPerKey.get(k);
      if(line.item_id&&!seen.has(idk)){
        seen.add(idk);
        poolQty.set(k,poolQty.get(k)+pNum((direct[idk]||{}).qty));
      }
    });
  }
  return (reqLines||[]).map(line=>{
    const requested=pNum(line.requested_qty);
    const poolKey=lineRecvKey(line);
    const poolLeft=Math.max(0,pNum(poolQty.get(poolKey))-pNum(poolTaken.get(poolKey)));
    const nthOfKey=(poolSeen.get(poolKey)||0)+1;
    poolSeen.set(poolKey,nthOfKey);
    const lastOfKey=nthOfKey>=pNum(poolLines.get(poolKey));
    const received=lastOfKey?poolLeft:Math.min(poolLeft,requested);
    poolTaken.set(poolKey,pNum(poolTaken.get(poolKey))+Math.min(poolLeft,requested));
    return {line:line,requested:requested,received:received,completed:requested>0&&received>=requested};
  });
}
/* A PR is finished only when EVERY line carrying a quantity has fully come in.
   A requirement with no quantity-bearing line at all is NOT finished: `every`
   on an empty list is true, and that would quietly complete a blank PR. */
function prCompletionDone_(recv){
  const real=(recv||[]).filter(r=>r&&r.requested>0);
  return real.length>0&&real.every(r=>r.completed);
}
/* ══ PR STATUS AFTER A RECEIPT ════════════════════════════════════════
   purchase_requirements.status used to have no writer at all on the receipt
   side: the Pending Items table worked "Completed" out on the fly from the
   quantities (prLineReceipts_ above), but the column itself was only ever set
   at PR creation, on a PR edit, on Hold, and by the mobile approval stages. So
   a fully received requirement read "Pending" for ever in the database and in
   anything built straight off that table — and a FIELD BOY requirement, which
   never reaches an approval stage at all (mobile.html gives that Purchaser the
   Vendor Info tab only), had no writer whatsoever beyond Hold.

   Written here instead, from the same verdict the table shows.

   Recomputed, never incremented: the verdict is read back off the lines every
   time, so an edit that lowers a quantity, or a cancel that removes a receipt,
   puts the requirement back. "Back" is remembered in
   pdf_snapshot.completion.prevStatus when Completed is set — the same trick
   the mobile Hold uses for its own prevStatus — so an MD-approved PR does not
   come back as Pending.

   Cancelled and Rejected are left alone: those are decisions somebody made,
   and a stray receipt must not reopen them.

   Best-effort by design. Every caller has already committed its receipt, so a
   failure here is logged and the next list refresh re-grades the PR anyway. */
const PR_STATUS_SETTLED=['Cancelled','Rejected'];
async function prApplyCompletion_(verdicts){
  if(!SB_READY)return 0;
  let changed=0;
  for(const v of (verdicts||[])){
    const pr=v&&v.req;
    if(!pr||!pr.id)continue;
    const cur=String(pr.status||'');
    if(PR_STATUS_SETTLED.includes(cur))continue;
    // Already says the right thing — no write, so this costs nothing on the
    // list refreshes where every PR is already graded correctly.
    if(!!v.done===(cur==='Completed'))continue;
    const snap={...(pr.pdf_snapshot||{})};
    let next;
    if(v.done){
      next='Completed';
      snap.completion={prevStatus:cur||'Pending',at:pStamp(),
        by:(sarvCurrentUser&&sarvCurrentUser.name)||SARV_ROLE_LABEL[sarvCurrentRole]||''};
    }else{
      const prev=(snap.completion||{}).prevStatus;
      next=(prev&&prev!=='Completed')?prev:'Pending';
      snap.completion=null;
    }
    // pdf_snapshot.status is kept level with the column, exactly as the Hold
    // and PR-edit writers do — the printed PR reads its status off the
    // snapshot, not off the column.
    snap.status=next;
    try{
      const u=await SB.from('purchase_requirements').update({status:next,pdf_snapshot:snap}).eq('id',pr.id);
      if(u.error)throw u.error;
      // The loaded row stays level with the database, so a table rendered
      // right after this shows the new status without a refetch.
      pr.status=next;pr.pdf_snapshot=snap;
      changed++;
      console.log('[SARV] PR '+(pr.req_no||pr.id)+' status → '+next);
    }catch(e){
      console.warn('[SARV] PR '+(pr.req_no||pr.id)+' status write failed:',e.message||e);
    }
  }
  return changed;
}
/* PO ke through aaya maal, PR no. + item NAME par keyed — bilkul wahi key jo
   Pending Items list banati hai. Rejected / Cancelled PO ki quantity nahi
   ginti: us order ka maal aaya hi nahi maana jaata, aur usi PR par naya PO
   ban sakta hai. */
async function prPoReceivedByKey_(reqNos){
  const out={};
  if(!SB_READY||!reqNos||!reqNos.length)return out;
  try{
    const pq=await SB.from('purchase_order_lines')
      .select('req_no,item_name,received_qty,purchase_order_id').in('req_no',reqNos);
    if(pq.error)throw pq.error;
    const dead=new Set();
    const sq=await SB.from('purchase_orders').select('id,status');
    if(!sq.error)(sq.data||[]).forEach(p=>{if(['Rejected','Cancelled'].includes(p.status||''))dead.add(p.id)});
    (pq.data||[]).forEach(x=>{
      if(dead.has(x.purchase_order_id))return;
      const k=String(x.req_no||'')+'|'+String(x.item_name||'').toLowerCase().trim();
      out[k]=(out[k]||0)+pNum(x.received_qty);
    });
  }catch(e){console.warn('[SARV] PR status: PO receipts skipped:',e.message||e);}
  return out;
}
// Item names for the pooled key — a PR line may not carry item_name itself.
async function prItemNameMap_(itemIds){
  const map=new Map();
  const ids=[...new Set((itemIds||[]).filter(Boolean))];
  if(!SB_READY||!ids.length)return map;
  try{
    const iq=await SB.from('items').select('id,name').in('id',ids);
    if(!iq.error)(iq.data||[]).forEach(x=>map.set(x.id,x));
  }catch(e){console.warn('[SARV] PR status: item names skipped:',e.message||e);}
  return map;
}
/* Which requirements a receipt actually credits: the ones named on the receipt
   itself (a FIELD BOY "without PO" entry) plus the ones the POs on it were
   raised from — read off purchase_orders.linked_req_nos and, for POs saved
   before that column was filled, off each PO line's own req_no. So the PR is
   re-graded whichever route its material took. */
async function inwardTouchedReqNos_(poNos,prNos){
  const out=[];
  const add=v=>String(v||'').split(',').map(s=>s.trim()).filter(Boolean)
    .forEach(n=>{if(!out.some(x=>x.toUpperCase()===n.toUpperCase()))out.push(n)});
  (prNos||[]).forEach(add);
  const pos=[...new Set((poNos||[]).map(n=>String(n||'').trim()).filter(Boolean))];
  if(SB_READY&&pos.length){
    try{
      const pq=await SB.from('purchase_orders').select('id,po_no,linked_req_nos').in('po_no',pos);
      if(pq.error)throw pq.error;
      (pq.data||[]).forEach(p=>add(p.linked_req_nos));
      const ids=(pq.data||[]).map(p=>p.id).filter(Boolean);
      if(ids.length){
        const lq=await SB.from('purchase_order_lines').select('req_no').in('purchase_order_id',ids);
        if(!lq.error)(lq.data||[]).forEach(l=>add(l.req_no));
      }
    }catch(e){console.warn('[SARV] PR nos behind the POs skipped:',e.message||e);}
  }
  return out;
}
/* Re-grades the named requirements and writes any status that changed. This is
   the entry point for the receipt side — inward save, inward edit and inward
   cancel all come through here. */
async function prSyncStatusForNos_(prNos){
  if(!SB_READY)return 0;
  const want=[];
  (prNos||[]).forEach(n=>{
    const v=String(n||'').trim();
    if(v&&!want.some(x=>x.toUpperCase()===v.toUpperCase()))want.push(v);
  });
  if(!want.length)return 0;
  try{
    const rq=await SB.from('purchase_requirements').select('id,req_no,status,pdf_snapshot').in('req_no',want);
    if(rq.error)throw rq.error;
    const prs=(rq.data||[]).filter(p=>!PR_STATUS_SETTLED.includes(String(p.status||'')));
    if(!prs.length)return 0;
    // .order('id') matches what refreshPendingRequirements uses — the pooled
    // hand-out above is line-order dependent, so both must read them the same way.
    const lq=await SB.from('purchase_requirement_lines').select('*').in('requirement_id',prs.map(p=>p.id)).order('id');
    if(lq.error)throw lq.error;
    const lines=lq.data||[];
    const nos=prs.map(p=>p.req_no);
    const poRecv=await prPoReceivedByKey_(nos);
    let direct={};
    try{direct=await prReceivedQtys_(nos);}
    catch(e){console.warn('[SARV] PR status: without-PO receipts skipped:',e.message||e);}
    const itemMap=await prItemNameMap_(lines.map(l=>l.item_id));
    const verdicts=prs.map(pr=>({
      req:pr,
      done:prCompletionDone_(prLineReceipts_(pr,lines.filter(l=>l.requirement_id===pr.id),itemMap,poRecv,direct))
    }));
    return await prApplyCompletion_(verdicts);
  }catch(e){
    console.warn('[SARV] PR status sync skipped:',e.message||e);
    return 0;
  }
}
/* Fills the item rows from a PR, the PO loader's counterpart. Three deliberate
   differences:
   • Supplier Name is NOT locked and NOT filled — a counter purchase can be from
     any shop, and the PR names no vendor.
   • Rate comes from the approved vendor's quote when the PR carries one, else 0
     for the bill to be typed in. A PR has no price of its own.
   • setInwardPoLock(true) is NOT applied — there is no ordered ledger to post
     back against, so item names stay editable.
   What it DOES share with the PO loader is the per-row status strip: Required /
   Pending / Received / Excess against the requirement line. */
async function loadPrsIntoInward(){
  const prs=getSelectedPrNos().map(n=>lookupPr_(n)).filter(Boolean);
  const tb=byId('itemTableBody');
  // Everything unticked — put the form back to a blank single row, the same way
  // loadPoIntoInward does when the last PO comes off.
  if(!prs.length){
    renderInwPrDetails_([]);
    if(tb){tb.innerHTML='';addNewRow();}
    setInwardPoLock(false);
    updateStoreTotals();
    return;
  }
  // One query for every ticked PR, then the lines are laid out PR by PR so the
  // rows read in the same order as the picker.
  const q=await SB.from('purchase_requirement_lines').select('*').in('requirement_id',prs.map(p=>p.id)).order('id');
  if(q.error){showToast('PR lines load nahi ho paaye: '+q.error.message,'error');return}
  const allLines=q.data||[];
  const byReq=new Map(prs.map(p=>[String(p.id),[]]));
  allLines.forEach(l=>{const k=String(l.requirement_id);if(byReq.has(k))byReq.get(k).push(l);});
  const empty=prs.filter(p=>!(byReq.get(String(p.id))||[]).length).map(p=>p.req_no);
  if(empty.length)showToast('⚠️ In PR me koi item nahi hai: '+empty.join(', '),'warn');
  if(tb)tb.innerHTML='';
  // Same Item-Master-only resolve the PO loader uses, so Description and
  // Category are the Master's word rather than a frozen copy on the line.
  const itemOf=await poLineItemResolver_(allLines);
  // What has already come in against these PRs — the "Received" figure on each
  // row's strip. Fetched once for all ticked PRs rather than per line.
  const already=await prReceivedQtys_(prs.map(p=>p.req_no),sarvEditingInwardId);
  const unresolved=[];
  let total=0;
  prs.forEach(pr=>{
    const lines=byReq.get(String(pr.id))||[];
    const snap=pr.pdf_snapshot||{};
    lines.forEach((line,i)=>{
      addNewRow();const tr=tb?.lastElementChild;if(!tr)return;
      total++;
      const it=itemOf(line);
      if(!it.id)unresolved.push(line.item_name||'(no name)');
      if(it.id||line.item_id)tr.dataset.itemId=it.id||line.item_id;
      // Which requirement this row came from. Drives the per-row PR strip, goes
      // into the printed PR Reference, and is saved onto the inward line.
      tr.dataset.reqNo=pr.req_no||'';
      /* The three figures the strip needs beyond the qty being typed:
         what the PR asked for, and what has already been received against it.
         Mirrors the poOrderedQty / poReceivedQty datasets on a PO row. */
      tr.dataset.prRequiredQty=pNum(line.requested_qty);
      tr.dataset.prRequiredWeight=pNum(line.gross_weight);
      { const k=String(pr.req_no||'').toUpperCase()+'|'+(it.id||line.item_id||'');
        const a=already[k]||{qty:0,weight:0};
        tr.dataset.prReceivedQty=a.qty;
        tr.dataset.prReceivedWeight=a.weight; }
      const set=(s,v)=>{const e=tr.querySelector(s);if(e)e.value=v??''};
      // The approved vendor's quote, if this PR was ever quoted. A FIELD BOY PR
      // never is, so this lands on 0 and the bill's rate is typed in.
      const si=(snap.items||[])[i]||{};
      const idx=(si.approvedVendorIndex!=null)?pNum(si.approvedVendorIndex):-1;
      const rate=idx>=0?pNum((si.rates||{})['V'+(idx+1)]):0;
      set('.item-name',line.item_name||it.name||'');
      set('.item-desc',it.description||'');
      set('.item-make',it.make||'');
      set('.item-cat',it.category||'');
      set('.qty-field',pNum(line.requested_qty));
      set('.item-uom',line.uom||it.uom||'');
      set('.list-price-field',rate);
      set('.rate-field',rate);
      set('.item-gst-field',pNum(it.gst_pct));
      if(line.gross_weight!=null&&line.gross_weight!=='')set('.weight-field',pNum(line.gross_weight));
      // The PR status strip, directly under its item row — the same sub-row a
      // PO receipt gets. Added last, once the datasets and the qty are in, so
      // its first render already has real figures.
      if(tb&&pNum(line.requested_qty)>0)appendPoInfoRow(tr,tb);
    });
  });
  if(!total&&tb)addNewRow();   // every ticked PR was empty — leave a usable row
  // Supplier stays hand-entered, so the PO lock must be OFF — a previous PO
  // receipt on this form may have left it on.
  setInwardPoLock(false);
  applyInwardNbGstLock();
  updateStoreTotals();
  if(unresolved.length){
    const names=[...new Set(unresolved)];
    console.warn('[SARV] PR lines not found in Item Master:',names.join(', '));
    showToast('⚠️ '+names.length+' item Item Master me nahi mile — Description / Category blank hain: '+names.slice(0,3).join(', ')+(names.length>3?' …':''),'warn');
  }
  renderInwPrDetails_(prs,total);
  if(total)showToast('✅ '+prs.length+' PR ke '+total+' item load ho gaye — Qty aur Rate check karke Submit karein');
}
function setSelectedPoNos(list){
  sarvSelectedPoNos=[...new Set((list||[]).filter(Boolean))];
  renderPoNumberPanel();
}
function togglePoNumberPanel(show){
  const panel=byId('poNumberPanel');if(!panel)return;
  const open=(show==null)?panel.style.display==='none':show;
  if(open)renderPoNumberPanel();
  panel.style.display=open?'block':'none';
}
async function loadOpenPoDropdown(){
  if(!SB_READY)return;
  const q=await SB.from('purchase_orders').select('*').order('po_date',{ascending:false});
  if(q.error){console.warn('[SARV] PO dropdown unavailable:',q.error.message);return}
  sarvPoCatalog=(q.data||[]).filter(x=>['MD Approved','Partially Received','Vendor Verified'].includes(String(x.status||'')));
  // Drop any previously-ticked PO that is no longer open.
  sarvSelectedPoNos=sarvSelectedPoNos.filter(no=>sarvPoCatalog.some(p=>p.po_no===no));
  renderPoNumberPanel();
}
/* Returns fn(poLine) -> the Item Master row behind that line, or {}.
   Resolved by item_id first (as a string, so a uuid and a numeric id both look
   up the same way), then by item name.
   A plain read on `items` is used rather than a PostgREST embed, so this works
   whether or not purchase_order_lines declares its item_id foreign key — an
   undeclared relationship makes an embedded select fail outright and would take
   the whole PO load down with it. Anything the read misses falls back to the
   in-memory Item Master cache. */
async function poLineItemResolver_(lines){
  const byId=new Map();
  const ids=[...new Set((lines||[]).map(l=>l&&l.item_id).filter(Boolean).map(String))];
  if(ids.length){
    try{
      const q=await SB.from('items').select('*').in('id',ids);
      if(q.error)throw q.error;
      (q.data||[]).forEach(it=>byId.set(String(it.id),it));
    }catch(e){console.warn('[SARV] PO line item lookup failed, using cached Item Master:',e.message||e);}
  }
  // The NAME fallback is not optional: every PO generated before item_id started
  // being written carries NULL there, so an id-only resolve finds nothing for
  // them and the row would fall back to the PO line's own stale copies — the
  // exact wrong text this is meant to stop showing. lookupItem() is the same
  // name resolver the entry forms use (case-insensitive, handles item_code and
  // the "NAME [CODE]" form), and it reads sarvItemCatalog — so make sure that
  // cache is actually loaded before leaning on it.
  if(!(sarvItemCatalog||[]).length){
    try{
      const rows=await fetchAllRows('items','*','name');
      if(rows&&rows.length)refreshItemDatalist(rows);
    }catch(e){console.warn('[SARV] Item Master load for PO resolve failed:',e.message||e);}
  }
  ids.forEach(id=>{
    if(byId.has(id))return;
    const c=(sarvItemCatalog||[]).find(it=>String(it.id)===id);
    if(c)byId.set(id,c);
  });
  return line=>byId.get(String(line&&line.item_id||''))||lookupItem(line&&line.item_name)||{};
}
async function loadPoIntoInward(poNo){
  const box=byId('inwardPoDetails');
  // Every ticked PO is loaded, each item row tagged with the PO it belongs to
  // so receipts post back against the right one.
  const poNos=sarvSelectedPoNos.length?getSelectedPoNos():(poNo?[poNo]:[]);
  const pos=poNos.map(n=>sarvPoCatalog.find(x=>x.po_no===n)).filter(Boolean);
  if(!pos.length){
    if(box)box.style.display='none';
    setInwardPoLock(false);
    const tb0=byId('itemTableBody');
    if(tb0){tb0.innerHTML='';addNewRow();}
    return;
  }
  // All selected POs must belong to one supplier — a single Inward entry
  // records one supplier's material.
  const vendors=[...new Set(pos.map(p=>String(p.vendor_name||'').trim().toUpperCase()))];
  if(vendors.length>1){
    showToast('⛔ Alag-alag Supplier ke POs ek saath select nahi ho sakte','error');
    setSelectedPoNos([pos[0].po_no]);
    return loadPoIntoInward();
  }
  const po=pos[0];
  if(byId('supplierName'))byId('supplierName').value=po.vendor_name||'';
  /* Invoice Date is deliberately NOT pre-filled from the PO. It is the date on
     the SUPPLIER'S BILL, which has nothing to do with when the order was
     raised — pre-filling it made the PO date look like a checked answer and it
     was getting saved unread. The field stays blank and mandatory, so whoever
     books the receipt reads it off the invoice in front of them. */
  // Against a PO the inward is always a Purchase receipt, and the vendor /
  // item names come from the PO itself — neither may be hand-edited.
  const nat=byId('inwNatureOfInward');
  if(nat&&nat.value!=='Purchase'){nat.value='Purchase';nat.dispatchEvent(new Event('change'));}
  const q=await SB.from('purchase_order_lines').select('*').in('purchase_order_id',pos.map(p=>p.id)).order('line_no');
  if(q.error){showToast('PO lines load nahi ho paaye: '+q.error.message,'error');return}
  const poById={};pos.forEach(p=>{poById[p.id]=p});
  const lines=q.data||[],tb=byId('itemTableBody');if(tb)tb.innerHTML='';
  // Item Description and Category come from the Item Master and NOWHERE else.
  // Both boxes are disabled and read "Auto from Master", so whatever they show
  // is taken as the master's word. The PO line's own item_description is a copy
  // frozen when the order was raised — on existing orders it holds the PR's
  // remark text, and `department` was never populated at all, which is why
  // Category read "General" on every PO receipt. Falling back to either one
  // re-displays exactly that wrong data, so there is no fallback: an item the
  // Master cannot resolve leaves both boxes blank and is reported below, which
  // is honest, whereas stale text silently passes itself off as master data.
  const itemOf=await poLineItemResolver_(lines);
  // Weight already received against these lines — the PO line has no counter
  // for it, so it is summed off the earlier inwards. Needed for the Weight
  // figures on each row's PO strip (see poStripParts_).
  const poRecWt=await poReceivedWeights_(lines.map(l=>l.id));
  const unresolved=[];
  lines.forEach(line=>{
    addNewRow();const tr=tb?.lastElementChild;if(!tr)return;
    const pending=Math.max(0,Number(line.ordered_qty||0)-Number(line.received_qty||0));
    tr.dataset.poLineId=line.id;tr.dataset.poOrderedQty=line.ordered_qty||0;tr.dataset.poReceivedQty=line.received_qty||0;
    tr.dataset.poOrderedWeight=pNum(line.gross_weight);
    tr.dataset.poReceivedWeight=pNum(poRecWt[line.id]);
    tr.dataset.poNo=poById[line.purchase_order_id]?.po_no||'';
    /* The PO's agreed price is its NET rate — unit price AFTER the line's own
       discount. That is what the receipt's rate (also net: List Price − Disc%)
       is matched against, for the Inward Approval check, the row strip and the
       printed "PO Actual Rate". Comparing against the gross unit price flagged
       every discounted PO line as a rate change. */
    const poDisc=pNum(line.discount_pct);
    tr.dataset.poUnitPrice=pNum(line.unit_price)-pNum(line.unit_price)*poDisc/100;
    const it=itemOf(line);
    if(!it.id)unresolved.push(line.item_name||'(no name)');
    // Pin the row to the Item Master row this line resolved to, so the receipt
    // posts to that same item instead of being re-resolved by name at save time
    // (which would pick the first of any same-named duplicates — see
    // ensureItem). rowDataInward reads this back as `itemId`. Taken from the
    // resolved item, not line.item_id, so a legacy line that carries no item_id
    // still gets pinned once the name resolves it.
    if(it.id||line.item_id)tr.dataset.itemId=it.id||line.item_id;
    const set=(s,v)=>{const e=tr.querySelector(s);if(e)e.value=v??''};
    set('.item-name',line.item_name||it.name||'');set('.item-desc',it.description||'');set('.item-make',it.make||line.make||'');set('.item-cat',it.category||'');set('.qty-field',pending);set('.item-uom',line.uom||it.uom||'');set('.list-price-field',line.unit_price||0);set('.discount-field',poDisc||0);set('.rate-field',pNum(tr.dataset.poUnitPrice));set('.item-gst-field',line.tax_pct||0);
    // Weight is prefilled from the PO line's Gross Wt (kg) so a WEIGHT-billed
    // receipt totals correctly out of the box; it stays editable because the
    // actually-received weight can differ from what was ordered.
    if(line.gross_weight!=null&&line.gross_weight!=='')set('.weight-field',pNum(line.gross_weight));
    // Bill Basis follows the PO line as well: a WEIGHT-billed order arriving
    // as a QTY receipt would re-cost itself the moment it was received.
    if(line.bill_basis)set('.bill-basis-field',line.bill_basis);
    appendPoInfoRow(tr,tb);
  });
  applyInwardNbGstLock();
  updateStoreTotals();
  setInwardPoLock(true);
  // Say which items the Master could not resolve, rather than leaving someone
  // to wonder why Description / Category came up blank. These are the rows to
  // fix in Item Master (or whose PO line names a deleted / renamed item).
  if(unresolved.length){
    const names=[...new Set(unresolved)];
    console.warn('[SARV] PO lines not found in Item Master:',names.join(', '));
    showToast('⚠️ '+names.length+' item Item Master me nahi mile — Description / Category blank hain: '+names.slice(0,3).join(', ')+(names.length>3?' …':''),'warn');
  }
  if(box){
    const ordered=pos.reduce((s,p)=>s+pNum(p.total_qty),0),received=pos.reduce((s,p)=>s+pNum(p.received_qty),0);
    box.innerHTML='PO <b>'+escText(pos.map(p=>p.po_no).join(', '))+'</b> · Vendor: <b>'+escText(po.vendor_name||'-')+'</b> · Ordered: <b>'+ordered+'</b> · Already received: <b>'+received+'</b> · Enter received quantity in the item rows.';
    box.style.display='block';
  }
}
/* ── Per-item PO status strip ────────────────────────────────────
   Inserted directly under each PO-loaded item row in Item Configurations.
   Order    = the PO line's ordered qty
   Received = what has ALREADY been received against that line before today
   Pending  = Order − Received
   Excess   = how far (Received + the qty being entered now) goes past Order
   Excess is the only live figure, so refreshPoInfoRows() recomputes it from
   updateStoreTotals(), which already runs on every item-row keystroke.
   These rows carry .po-info-row and MUST be excluded anywhere item rows are
   iterated — see updateStoreTotals / rowDataInward / saveStoreInward. */
function appendPoInfoRow(tr,tb){
  if(!tr||!tb)return;
  const cols=tr.children.length||15;
  const info=document.createElement('tr');
  info.className='po-info-row';
  info.innerHTML='<td colspan="'+cols+'" style="background:#f8fafc;border-top:none;padding:3px 8px 6px 8px;"></td>';
  tb.appendChild(info);
  // Deleting the item row must take its status strip with it.
  const del=tr.querySelector('.delete-btn');
  if(del)del.onclick=()=>{info.remove();tr.remove();updateStoreTotals()};
  renderPoInfoRow(tr,info);
}
/* What an item row hands poStripParts_ — gathered in one place so the live
   on-screen strip is fed exactly the same figures the printed sub-row is. */
function poStripInputFromRow_(tr){
  return {
    poNo:tr.dataset.poNo||'',
    poOrderedQty:tr.dataset.poOrderedQty, poReceivedQty:tr.dataset.poReceivedQty,
    poOrderedWeight:tr.dataset.poOrderedWeight, poReceivedWeight:tr.dataset.poReceivedWeight,
    // The PR side of the same row. Only one of the two is ever filled — the PR
    // picker is hidden the moment a PO is ticked — so docStripParts_ can simply
    // try PO first and fall through to PR.
    prNo:tr.dataset.reqNo||'',
    prRequiredQty:tr.dataset.prRequiredQty, prReceivedQty:tr.dataset.prReceivedQty,
    prRequiredWeight:tr.dataset.prRequiredWeight, prReceivedWeight:tr.dataset.prReceivedWeight,
    // The Repair-Return side: which outward this item went out on, how much
    // went out ON THIS LINE, and how much of it has already come back. Set by
    // loadRepairOutwardIntoInward / loadInwardForEdit.
    repairOutNo:tr.dataset.repairOutNo||'',
    repairOutQty:tr.dataset.repairOutQty, repairReceivedQty:tr.dataset.repairReceivedQty,
    repairOutWeight:tr.dataset.repairOutWeight, repairReceivedWeight:tr.dataset.repairReceivedWeight,
    // The PO's agreed price and the rate being entered — docStripRateNote_
    // compares the two, so the live strip can warn about an over-rate before
    // Submit instead of only the printed copy recording it afterwards.
    poUnitPrice:tr.dataset.poUnitPrice,
    rate:pNum(tr.querySelector('.rate-field')?.value),
    qty:pNum(tr.querySelector('.qty-field')?.value),
    weight:pNum(tr.querySelector('.weight-field')?.value)
  };
}
function renderPoInfoRow(tr,info){
  const cell=info.querySelector('td');if(!cell)return;
  // Built through poStripParts_, the same function both PDF builders call, so
  // the strip on screen and the sub-row on the print can never disagree. Qty
  // and Weight both count what is being typed right now, so Pending / Excess
  // move as the row is filled in.
  const p=docStripParts_(poStripInputFromRow_(tr));
  // Nothing measurable to report (no PO / PR number, or an ordered qty of 0):
  // the strip is hidden rather than left as an empty grey band.
  if(!p){cell.innerHTML='';info.style.display='none';return;}
  info.style.display='';
  /* Rang docStripLines_ tay karta hai — wahi function jo HTML print aur
     native PDF ko feed karta hai. Yahan sirf pill ki shakl di jaati hai, to
     screen par jo rang dikhta hai bilkul wahi chhapta bhi hai. */
  const pill=s=>'<span style="display:inline-flex;align-items:center;gap:4px;background:#fff;border:1px solid #e2e8f0;border-radius:5px;padding:2px 7px;">'
    +'<span style="color:'+STRIP_COLOR.muted+';font-size:9px;font-weight:700;text-transform:uppercase;letter-spacing:.3px;">'+escText(s.lbl)+'</span>'
    +'<b style="color:'+s.c+';font-size:11px;'+(s.bg?('background:'+s.bg+';padding:0 4px;border-radius:3px;'):'')+'">'+escText(s.t)+'</b></span>';
  // Blue PO / green PR / amber Return, so the kind of document this row is
  // measured against reads at a glance without the number being read.
  const tag=s=>'<span style="color:'+s.c+';font-weight:800;font-size:10px;">'+escText(s.t)+'</span>';
  const line=(mt,inner)=>'<div style="display:flex;flex-wrap:wrap;gap:6px;align-items:center;font-size:10px;'
    +(mt?'margin-top:4px;':'')+'">'+inner+'</div>';
  const rateNote=docStripRateNote_(p);
  // Pehli line Qty ki, doosri (jab PO par weight ho) Weight ki — usi chaar
  // headings ke kram me.
  cell.innerHTML=docStripLines_(p).map((segs,i)=>
      line(i>0,segs.map(s=>s.lbl?pill(s):tag(s)).join(''))).join('')
    /* Third line, same as the printed copy — the rate the PO agreed, shown the
       moment the entry goes past it. On screen it is a warning before Submit;
       on the PDF it is the record. Same function builds both, so they cannot
       say different things. */
    +(rateNote?'<div style="margin-top:3px;font-size:10px;font-weight:800;color:'
      +(docStripRateAlert_(p)?STRIP_COLOR.alert:STRIP_COLOR.info)+';">'+escText(rateNote)+'</div>':'');
}
/* Weight already booked in against each of these PO lines.
   purchase_order_lines keeps a received_qty counter but has no received-weight
   column, so the only record of received weight is the inward lines themselves
   — the same source the PO Details report sums. Best-effort: a database whose
   inward_lines has no po_line_id yields zeros, and the weight figures are then
   simply not printed rather than the PO load failing. */
async function poReceivedWeights_(lineIds){
  const ids=[...new Set((lineIds||[]).filter(Boolean))];
  const out={};ids.forEach(i=>{out[i]=0});
  if(!ids.length)return out;
  try{
    const q=await SB.from('inward_lines').select('po_line_id,weight').in('po_line_id',ids);
    if(q.error)throw q.error;
    (q.data||[]).forEach(r=>{
      if(Object.prototype.hasOwnProperty.call(out,r.po_line_id))out[r.po_line_id]+=pNum(r.weight);
    });
  }catch(e){console.warn('[SARV] PO received-weight lookup skipped:',e.message||e);}
  return out;
}
// Re-renders the live figures (Received / Pending / Excess) as qty is typed.
function refreshPoInfoRows(){
  document.querySelectorAll('#itemTableBody tr.po-info-row').forEach(info=>{
    const tr=info.previousElementSibling;
    if(tr&&!tr.classList.contains('po-info-row'))renderPoInfoRow(tr,info);
  });
}
// Locks Supplier Name + every Item Name while the Inward is tied to a PO,
// and also pins Nature of Inward to Purchase.
function setInwardPoLock(locked){
  const lock=(el,title)=>{
    if(!el)return;
    el.readOnly=locked;
    el.style.background=locked?'#f1f5f9':'';
    el.style.cursor=locked?'not-allowed':'';
    el.title=locked?title:'';
  };
  lock(byId('supplierName'),'PO ke against Supplier Name PO se aata hai — change nahi kar sakte');
  document.querySelectorAll('#itemTableBody .item-name').forEach(el=>lock(el,'PO ke against Item Name PO se aata hai — change nahi kar sakte'));
  const nat=byId('inwNatureOfInward');
  if(nat){nat.disabled=locked;nat.style.background=locked?'#f1f5f9':'';nat.title=locked?'PO ke against Nature of Inward hamesha Purchase hota hai':'';}
  // Unlocking above hands the Nature dropdown back; a Nature pinned from the
  // Home chooser outranks that, so it is re-asserted here.
  if(!locked)applyHomeNatureLocks();
}
let sarvRepairOutwardCatalog=[];
/* ── Repair Outward picker ────────────────────────────────────────
   A checkbox dropdown (same shape as the PO Number picker) so one repair
   return can cover several outwards at once.

   Multi-select is only SAFE when inward_lines carries repair_outward_no.
   The original link is header-level — inward_entries.gate_pass_no matched
   exactly against outward_entries.document_no — which can only ever name one
   outward. Writing several doc numbers into that one field would match
   nothing, so every selected outward would keep showing Received 0 and the
   Repair Tracker would under-report receipts.
   So: if the column exists we record the outward per LINE and multi-select is
   allowed; if it doesn't, the picker stays single-pick and says why. */
let sarvSelectedRepairOutNos=[];
let sarvRepairLineLinkSupported=null;   // null = not probed yet
async function probeRepairLineLink(){
  if(sarvRepairLineLinkSupported!==null)return sarvRepairLineLinkSupported;
  try{
    const {error}=await SB.from('inward_lines').select('repair_outward_no').limit(1);
    sarvRepairLineLinkSupported=!error;
    if(error)console.warn('[SARV] inward_lines.repair_outward_no missing — repair multi-select disabled:',error.message);
  }catch(e){ sarvRepairLineLinkSupported=false; }
  return sarvRepairLineLinkSupported;
}
function getSelectedRepairOutNos(){return [...sarvSelectedRepairOutNos]}
function updateRepairOutwardBtnText(){
  const el=byId('repairOutwardBtnText');if(!el)return;
  el.textContent=!sarvSelectedRepairOutNos.length?'— Select Outward No. (Repair) —'
    :(sarvSelectedRepairOutNos.length===1?sarvSelectedRepairOutNos[0]:sarvSelectedRepairOutNos.length+' outwards selected');
}
function renderRepairOutwardPanel(){
  const panel=byId('repairOutwardPanel');if(!panel)return;
  const multi=sarvRepairLineLinkSupported===true;
  const hint=byId('repairMultiHint');
  if(hint)hint.textContent=multi?'(tick one or more, same party only)':'(single selection — run the repair_outward_no migration for multi)';
  const opts=sarvRepairOutwardCatalog||[];
  if(!opts.length){
    panel.innerHTML='<div style="padding:10px;color:#94a3b8;font-size:11px;">Koi pending / partial repair outward nahi hai.</div>';
  }else{
    panel.innerHTML=opts.map(o=>{
      const checked=sarvSelectedRepairOutNos.includes(o.document_no)?' checked':'';
      return '<label style="display:flex;align-items:center;gap:8px;padding:5px 6px;border-radius:5px;cursor:pointer;font-size:11px;font-weight:600;">'
        +'<input type="'+(multi?'checkbox':'radio')+'" name="sarvRepairOpt" class="sarv-repair-opt" value="'+escText(o.document_no)+'"'+checked+'>'
        +'<span>'+escText(o.document_no)+' <span style="color:#64748b;font-weight:500;">— '+escText(o.party_name||'Party')
        +' — Balance: '+pNum(o.balance)+(pNum(o.received)>0?' (Partial)':'')+'</span></span>'
        +'</label>';
    }).join('');
  }
  panel.querySelectorAll('.sarv-repair-opt').forEach(cb=>{
    cb.addEventListener('change',()=>{
      sarvSelectedRepairOutNos=[...panel.querySelectorAll('.sarv-repair-opt:checked')].map(x=>x.value);
      updateRepairOutwardBtnText();
      loadRepairOutwardIntoInward().catch(dbError);
    });
  });
  updateRepairOutwardBtnText();
}
function setSelectedRepairOutNos(list){
  sarvSelectedRepairOutNos=[...new Set((list||[]).filter(Boolean))];
  renderRepairOutwardPanel();
}
function toggleRepairOutwardPanel(show){
  const panel=byId('repairOutwardPanel');if(!panel)return;
  const open=(show==null)?panel.style.display==='none':show;
  if(open)renderRepairOutwardPanel();
  panel.style.display=open?'block':'none';
}
async function loadRepairOutwardDropdown(){
  if(!SB_READY)return;
  await probeRepairLineLink();
  const oq=await SB.from('outward_entries').select('*').eq('nature_of_dispatch','Repair').order('outward_date',{ascending:false});
  if(oq.error){console.warn('[SARV] Repair outward dropdown unavailable:',oq.error.message);return}
  const outwards=oq.data||[];sarvRepairOutwardCatalog=[];
  if(!outwards.length)return;
  const outIds=outwards.map(o=>o.id);
  const olq=await SB.from('outward_lines').select('*').in('outward_id',outIds);
  const sentByOut={};
  (olq.data||[]).forEach(l=>{sentByOut[l.outward_id]=(sentByOut[l.outward_id]||0)+pNum(l.qty)});
  const docNos=outwards.map(o=>o.document_no);
  const iq=await SB.from('inward_entries').select('id,document_no,gate_pass_no').eq('nature_of_inward','Repaired').in('gate_pass_no',docNos);
  const inwardEntriesByDoc={};
  (iq.data||[]).forEach(e=>{(inwardEntriesByDoc[e.gate_pass_no]=inwardEntriesByDoc[e.gate_pass_no]||[]).push(e)});
  const allInwardIds=(iq.data||[]).map(e=>e.id);
  const recv=await repairReceivedByDoc_(allInwardIds,inwardEntriesByDoc,docNos);
  sarvRepairOutwardCatalog=outwards.map(o=>{
    const sent=sentByOut[o.id]||0;
    const received=recv.byDoc[o.document_no]||0;
    return {...o,sent,received,balance:Math.max(0,sent-received),receivedDocs:recv.docsByOut[o.document_no]||[]};
  }).filter(o=>o.balance>0);
  // Drop any tick whose outward is no longer open.
  sarvSelectedRepairOutNos=sarvSelectedRepairOutNos.filter(no=>sarvRepairOutwardCatalog.some(x=>x.document_no===no));
  renderRepairOutwardPanel();
}

/* Received-qty per repair outward document number.
   Two linkage generations have to be honoured at once:
     • line-level  — inward_lines.repair_outward_no names the outward per line,
       which is what makes a multi-outward repair return possible;
     • header-level — the original scheme, where the whole inward belongs to
       inward_entries.gate_pass_no.
   An inward is attributed line-by-line if ANY of its lines carry the column,
   otherwise it falls back to its header. That keeps historic entries counted
   and makes sure nothing is counted twice. */
async function repairReceivedByDoc_(inwardIds,inwardEntriesByDoc,docNos){
  const byDoc={},docsByOut={};
  const addDoc=(outNo,inwNo)=>{
    if(!outNo||!inwNo)return;
    (docsByOut[outNo]=docsByOut[outNo]||[]);
    if(!docsByOut[outNo].includes(inwNo))docsByOut[outNo].push(inwNo);
  };
  // Header-level inwards that we already know about, keyed by id.
  const headerDocById={},inwardNoById={};
  Object.entries(inwardEntriesByDoc||{}).forEach(([doc,list])=>{
    (list||[]).forEach(e=>{headerDocById[e.id]=doc;inwardNoById[e.id]=e.document_no;});
  });
  const linked=sarvRepairLineLinkSupported===true;
  // With line-level support, other inwards (whose gate_pass_no names a
  // different outward, or none) may still carry lines for these outwards.
  let lineRows=[];
  if(linked&&(docNos||[]).length){
    const lq=await SB.from('inward_lines')
      .select('inward_id,qty,repair_outward_no,inward_entries(document_no)')
      .in('repair_outward_no',docNos);
    if(!lq.error)lineRows=lq.data||[];
  }
  const inwardsWithLineLink=new Set(lineRows.map(l=>l.inward_id));
  lineRows.forEach(l=>{
    const outNo=l.repair_outward_no;
    byDoc[outNo]=(byDoc[outNo]||0)+pNum(l.qty);
    addDoc(outNo,(l.inward_entries&&l.inward_entries.document_no)||inwardNoById[l.inward_id]);
  });
  // Header-level fallback for every inward that has no line-level link.
  const legacyIds=(inwardIds||[]).filter(id=>!inwardsWithLineLink.has(id));
  if(legacyIds.length){
    const ilq=await SB.from('inward_lines').select('inward_id,qty').in('inward_id',legacyIds);
    (ilq.data||[]).forEach(l=>{
      const outNo=headerDocById[l.inward_id];
      if(!outNo)return;
      byDoc[outNo]=(byDoc[outNo]||0)+pNum(l.qty);
      addDoc(outNo,inwardNoById[l.inward_id]);
    });
  }
  return {byDoc,docsByOut};
}
/* How much of each ITEM has already come back against each repair outward,
   keyed OUTWARD_NO|item_id. repairReceivedByDoc_ above answers the same
   question per DOCUMENT, which is all the dropdown's Balance needs; the item
   row's sub-row needs it per part, or a three-item gate pass shows the gate
   pass's total on all three lines.

   Both linkage generations are honoured, exactly as repairReceivedByDoc_ does:
     • line-level  — inward_lines.repair_outward_no names the outward per line,
       which is what makes one receipt cover several outwards;
     • header-level — the original scheme, inward_entries.gate_pass_no for the
       whole entry.
   An inward with ANY line-level link is attributed line by line; everything
   else falls back to its header, so nothing is counted twice and nothing
   historic is dropped.

   excludeInwardId leaves the entry being edited out, so reopening a saved
   repair return never counts its own quantities as history — the same rule
   prReceivedQtys_ follows for a PR receipt. */
async function repairReceivedByDocItem_(docNos,excludeInwardId){
  const nos=[...new Set((docNos||[]).map(n=>String(n||'').trim()).filter(Boolean))];
  const out={};
  if(!nos.length||!SB_READY)return out;
  const mine=id=>excludeInwardId&&String(id)===String(excludeInwardId);
  const add=(outNo,itemId,qty,weight)=>{
    if(!outNo||!itemId)return;
    const k=String(outNo).trim().toUpperCase()+'|'+String(itemId);
    const o=out[k]=out[k]||{qty:0,weight:0};
    o.qty+=pNum(qty);o.weight+=pNum(weight);
  };
  try{
    // Line-level first — it is the exact answer where the column exists.
    let lineRows=[];
    if(await probeRepairLineLink()){
      const lq=await SB.from('inward_lines')
        .select('inward_id,item_id,qty,weight,repair_outward_no').in('repair_outward_no',nos);
      if(lq.error)throw lq.error;
      lineRows=lq.data||[];
    }
    const linked=new Set();
    lineRows.forEach(l=>{
      if(mine(l.inward_id))return;
      linked.add(String(l.inward_id));
      add(l.repair_outward_no,l.item_id,l.qty,l.weight);
    });
    // Header fallback for every repair inward that carries no line-level link.
    const eq=await SB.from('inward_entries').select('id,gate_pass_no')
      .eq('nature_of_inward','Repaired').in('gate_pass_no',nos);
    if(eq.error)throw eq.error;
    const headerDocById={};
    (eq.data||[]).forEach(e=>{
      if(mine(e.id)||linked.has(String(e.id)))return;
      headerDocById[String(e.id)]=e.gate_pass_no;
    });
    const legacyIds=Object.keys(headerDocById);
    if(legacyIds.length){
      const ilq=await SB.from('inward_lines').select('inward_id,item_id,qty,weight').in('inward_id',legacyIds);
      if(ilq.error)throw ilq.error;
      (ilq.data||[]).forEach(l=>add(headerDocById[String(l.inward_id)],l.item_id,l.qty,l.weight));
    }
  }catch(e){
    // A lookup that cannot run means the strip reports 0 already-received,
    // which reads as "no history" rather than as a wrong number.
    console.warn('[SARV] Repair received-per-item lookup skipped:',e.message||e);
  }
  return out;
}
async function loadRepairOutwardIntoInward(){
  const statusEl=byId('repairAutoFillStatus'),stripEl=byId('repairReceivedInwardStrip'),stripNos=byId('repairReceivedInwardNos');
  const sel=getSelectedRepairOutNos()
    .map(no=>sarvRepairOutwardCatalog.find(x=>x.document_no===no)).filter(Boolean);
  const tb=byId('itemTableBody');
  if(!sel.length){
    if(statusEl)statusEl.textContent='';
    if(stripEl)stripEl.style.display='none';
    if(byId('gatePassNo'))byId('gatePassNo').value='';
    if(tb){tb.innerHTML='';addNewRow();}
    return;
  }
  // One inward records one party's material, so every ticked outward must
  // belong to the same party - same rule the PO picker enforces.
  const parties=[...new Set(sel.map(o=>String(o.party_name||'').trim().toUpperCase()))];
  if(parties.length>1){
    showToast('&#9940; Alag-alag Party ke Repair Outwards ek saath select nahi ho sakte','error');
    setSelectedRepairOutNos([sel[0].document_no]);
    return loadRepairOutwardIntoInward();
  }
  if(byId('supplierName'))byId('supplierName').value=sel[0].party_name||'';
  // gate_pass_no can only name ONE outward (the Repair Tracker matches it
  // exactly), so it holds the first. The per-line repair_outward_no written on
  // save is what actually credits each outward - see repairReceivedByDoc_.
  if(byId('gatePassNo'))byId('gatePassNo').value=sel[0].document_no;
  const lot=sel.find(o=>o.lot_no);
  if(byId('lotNo')&&lot)byId('lotNo').value=lot.lot_no;
  const totSent=sel.reduce((s,o)=>s+pNum(o.sent),0);
  const totRecd=sel.reduce((s,o)=>s+pNum(o.received),0);
  const totBal=sel.reduce((s,o)=>s+pNum(o.balance),0);
  if(statusEl)statusEl.textContent=sel.length+' outward(s) - Sent: '+totSent+' - Received so far: '+totRecd+' - Balance: '+totBal;
  const allRecdDocs=[...new Set(sel.flatMap(o=>o.receivedDocs||[]))];
  if(allRecdDocs.length){
    if(stripNos)stripNos.textContent=allRecdDocs.join(', ');
    if(stripEl)stripEl.style.display='block';
  }else if(stripEl)stripEl.style.display='none';
  const lq=await SB.from('outward_lines').select('*, items(name,description,make,category,uom)')
    .in('outward_id',sel.map(o=>o.id)).order('id');
  if(lq.error){showToast('Outward lines load nahi ho paaye: '+lq.error.message,'error');return}
  const outById={};sel.forEach(o=>{outById[o.id]=o});
  const lines=lq.data||[];
  /* What has already come back, PER ITEM per outward. The outward's own
     `received` / `balance` are gate-pass totals — right for the picker, wrong
     on an item row, where they made every line of a three-item gate pass show
     the same two numbers. The entry being edited is left out, so reopening a
     saved return does not count its own quantities as history. */
  const alreadyByItem=await repairReceivedByDocItem_(sel.map(o=>o.document_no),sarvEditingInwardId);
  if(tb)tb.innerHTML='';
  lines.forEach(line=>{
    const o=outById[line.outward_id];if(!o)return;
    addNewRow();const tr=tb?.lastElementChild;if(!tr)return;
    const it=line.items||{};
    const prior=alreadyByItem[String(o.document_no).trim().toUpperCase()+'|'+String(line.item_id||'')]||{qty:0,weight:0};
    const outQty=pNum(line.qty), pending=Math.max(0,outQty-pNum(prior.qty));
    // Tagged so the save path can write repair_outward_no per line, and so the
    // sub-row knows what this item is being measured against. These are the
    // same four names poStripInputFromRow_ reads and returnStripParts_ turns
    // into Out Qty / Received / Pending / Excess — on screen and on the PDF.
    tr.dataset.repairOutNo=o.document_no;
    tr.dataset.repairOutQty=outQty;
    tr.dataset.repairReceivedQty=pNum(prior.qty);
    tr.dataset.repairOutWeight=pNum(line.weight);
    tr.dataset.repairReceivedWeight=pNum(prior.weight);
    const set=(s,v)=>{const e=tr.querySelector(s);if(e)e.value=v??''};
    set('.item-name',it.name||'');set('.item-desc',it.description||'');set('.item-make',it.make||'');set('.item-cat',it.category||'General');set('.item-uom',line.uom||it.uom||'PCS');
    /* Prefilled with what THIS item still owes, not with the gate pass's
       balance capped by the line — on a partly-returned gate pass those are
       different numbers, and the old one could prefill an item that had
       already come back in full. Editable, as before. */
    set('.qty-field',pending);
    // Weight likewise: what went out on this line, less what has come back.
    if(pNum(line.weight)>0)set('.weight-field',Math.max(0,pNum(line.weight)-pNum(prior.weight)));
    appendPoInfoRow(tr,tb);
  });
  applyInwardNbGstLock();
  updateStoreTotals();
}

/* ================================================================
   REPAIR ITEMS TRACKER — every Outward saved with Nature of Dispatch
   = "Repair" shows up here, matched against Repair-Return Inward
   entries (nature_of_inward='Repaired', gate_pass_no = outward doc no)
   the same way the Material Inward "Repair Return" dropdown matches
   them (see loadRepairOutwardDropdown above).
================================================================ */
let sarvRepairTrackerRows=[];
window.loadRepairTracker=async function(){
  const tb=byId('repairTrackerBody');
  if(!tb)return;
  if(!SB_READY){tb.innerHTML='<tr><td colspan="12" style="text-align:center;padding:24px;color:#f59e0b;">⚠️ Supabase not configured</td></tr>';return;}
  const statusText=byId('repairStatusText');
  tb.innerHTML='<tr><td colspan="12" style="text-align:center;padding:24px;color:#94a3b8;">⏳ Loading repair tracker...</td></tr>';
  if(statusText)statusText.textContent='Loading...';
  try{
    const outwards=await fetchAllRows('outward_entries','*','outward_date',q=>q.eq('nature_of_dispatch','Repair'));
    if(!outwards.length){
      sarvRepairTrackerRows=[];
      renderRepairTrackerTable();
      return;
    }
    const outIds=outwards.map(o=>o.id);
    const lines=await fetchAllRows('outward_lines','*, items(name)','id',q=>q.in('outward_id',outIds));
    const linesByOut={};
    lines.forEach(l=>{(linesByOut[l.outward_id]=linesByOut[l.outward_id]||[]).push(l);});
    const docNos=outwards.map(o=>o.document_no);
    const inwards=docNos.length?await fetchAllRows('inward_entries','*','id',q=>q.eq('nature_of_inward','Repaired').in('gate_pass_no',docNos)):[];
    const inwardsByDoc={};
    inwards.forEach(e=>{(inwardsByDoc[e.gate_pass_no]=inwardsByDoc[e.gate_pass_no]||[]).push(e);});
    const inwardIds=inwards.map(e=>e.id);
    await probeRepairLineLink();
    const trackerRecv=await repairReceivedByDoc_(inwardIds,inwardsByDoc,docNos);
    // Best-effort PDF links for the outward itself + any linked repair-return inward(s)
    const allDocNos=[...docNos,...inwards.map(e=>e.document_no)];
    const pdfMap={};
    if(allDocNos.length){
      try{
        const pdfq=await SB.from('pdf_documents').select('document_no,public_url').in('document_no',allDocNos);
        (pdfq.data||[]).forEach(p=>{if(p.public_url)pdfMap[p.document_no]=p.public_url;});
      }catch(e){/* pdf lookup is best-effort — tracker still works without links */}
    }
    sarvRepairTrackerRows=outwards.map(o=>{
      const oLines=linesByOut[o.id]||[];
      const sent=oLines.reduce((s,l)=>s+pNum(l.qty),0);
      const itemNames=[...new Set(oLines.map(l=>l.items?.name).filter(Boolean))];
      // Linked inwards come from the same dual-generation resolver, so a
      // return whose header names a different outward still lists here.
      const recvEntries=(trackerRecv.docsByOut[o.document_no]||[]).map(dn=>({document_no:dn}));
      // Same dual-generation rule as the picker: a repair return covering
      // several outwards is credited per LINE via repair_outward_no, so a
      // header-only sum here would under-report every outward but the first.
      const received=trackerRecv.byDoc[o.document_no]||0;
      const balance=Math.max(0,sent-received);
      const status=(sent>0&&balance<=0)?'COMPLETE':(received>0?'PARTIAL':'PENDING');
      return {o,itemNames,sent,received,balance,status,recvEntries,pdfMap};
    });
    renderRepairTrackerTable();
  }catch(e){
    dbError(e);
    tb.innerHTML='<tr><td colspan="12" style="text-align:center;padding:16px;color:#ef4444;">❌ Error loading repair tracker</td></tr>';
  }
};
window.renderRepairTrackerTable=function(){
  const tb=byId('repairTrackerBody'),statusText=byId('repairStatusText');
  if(!tb)return;
  const q=(byId('repairSearchQuery')?.value||'').toLowerCase().trim();
  const statusFilter=byId('repairStatusFilter')?.value||'ALL';
  const rows=sarvRepairTrackerRows.filter(r=>{
    if(statusFilter!=='ALL'&&r.status!==statusFilter)return false;
    if(q){
      const hay=[r.o.document_no,r.o.party_name,...r.itemNames].map(x=>String(x||'').toLowerCase()).join(' ');
      if(!hay.includes(q))return false;
    }
    return true;
  });
  const total=sarvRepairTrackerRows.length;
  const set=(id,v)=>{const e=byId(id);if(e)e.textContent=v};
  set('rtTotalEntries',total);
  set('rtPending',sarvRepairTrackerRows.filter(r=>r.status==='PENDING').length);
  set('rtPartial',sarvRepairTrackerRows.filter(r=>r.status==='PARTIAL').length);
  set('rtComplete',sarvRepairTrackerRows.filter(r=>r.status==='COMPLETE').length);
  set('rtTotalSent',sarvRepairTrackerRows.reduce((s,r)=>s+r.sent,0));
  set('rtTotalReceived',sarvRepairTrackerRows.reduce((s,r)=>s+r.received,0));
  set('rtTotalBalance',sarvRepairTrackerRows.reduce((s,r)=>s+r.balance,0));
  if(statusText)statusText.textContent=(total?`${rows.length} of ${total} shown`:'');
  if(!total){
    tb.innerHTML='<tr><td colspan="12" style="text-align:center;padding:30px;color:#94a3b8;">No repair outward entries yet — items sent with Nature of Dispatch = Repair will show up here.</td></tr>';
    return;
  }
  if(!rows.length){
    tb.innerHTML='<tr><td colspan="12" style="text-align:center;padding:24px;color:#94a3b8;">No entries match this search / status filter.</td></tr>';
    return;
  }
  const statusBadge=s=>{
    if(s==='COMPLETE')return '<span style="background:#f0fdf4;color:#16a34a;border:1px solid #bbf7d0;border-radius:4px;padding:2px 8px;font-size:10px;font-weight:800;white-space:nowrap;">✅ Complete</span>';
    if(s==='PARTIAL')return '<span style="background:#fff7ed;color:#ea580c;border:1px solid #fed7aa;border-radius:4px;padding:2px 8px;font-size:10px;font-weight:800;white-space:nowrap;">◔ Partial</span>';
    return '<span style="background:#fef3c7;color:#d97706;border:1px solid #fde68a;border-radius:4px;padding:2px 8px;font-size:10px;font-weight:800;white-space:nowrap;">⬤ Pending</span>';
  };
  tb.innerHTML=rows.map((r,i)=>{
    const o=r.o;
    const outPdf=r.pdfMap[o.document_no]?`<a href="${escText(r.pdfMap[o.document_no])}" target="_blank" rel="noopener" style="color:#1d4ed8;font-weight:700;text-decoration:none;">📄 View PDF</a>`:'<span style="color:#cbd5e1;">—</span>';
    const inwardLinks=r.recvEntries.length?r.recvEntries.map(e=>r.pdfMap[e.document_no]?`<a href="${escText(r.pdfMap[e.document_no])}" target="_blank" rel="noopener" style="color:#16a34a;font-weight:700;text-decoration:none;">${escText(e.document_no)}</a>`:escText(e.document_no)).join(', '):'<span style="color:#cbd5e1;">—</span>';
    return `<tr style="border-bottom:1px solid #f1f5f9;font-size:11px;">
        <td style="padding:5px 6px;text-align:center;color:#94a3b8;">${i+1}</td>
        <td style="padding:5px 6px;font-weight:700;color:#0369a1;white-space:nowrap;">${escText(o.document_no)}</td>
        <td style="padding:5px 6px;">${escText(o.outward_date||'—')}</td>
        <td style="padding:5px 6px;">${escText(o.party_name||'—')}</td>
        <td style="padding:5px 6px;color:#64748b;">${escText(r.itemNames.join(', ')||'—')}</td>
        <td style="padding:5px 6px;text-align:center;font-weight:700;">${r.sent}</td>
        <td style="padding:5px 6px;text-align:center;font-weight:700;color:#16a34a;">${r.received}</td>
        <td style="padding:5px 6px;text-align:center;font-weight:800;color:${r.balance>0?'#dc2626':'#64748b'};">${r.balance}</td>
        <td style="padding:5px 6px;">${escText(o.target_return_date||'—')}</td>
        <td style="padding:5px 6px;text-align:center;">${statusBadge(r.status)}</td>
        <td style="padding:5px 6px;">${inwardLinks}</td>
        <td style="padding:5px 6px;text-align:center;">${outPdf}</td>
      </tr>`;
  }).join('');
};

/* ================================================================
   PO RECEIPT STATUS — decided ITEM BY ITEM, never on PO totals.
   ────────────────────────────────────────────────────────────────
   A PO is "Received" only when EVERY ordered line has had its full
   quantity booked in. Both receipt paths used to add the PO's lines up and
   compare two totals, which let an over-receipt on one item pay for a
   shortfall on another: order 10 bolts + 10 nuts, take in 20 bolts and no
   nuts, and received (20) >= ordered (20) marked the whole PO Received with
   the nuts still outstanding. The same two totals also drove the Short Close
   button out of sight and dropped the PO off the Generated POs list.

   `lines` is every purchase_order_lines row of one PO; `currentStatus` is what
   the header holds now, which is what a PO with nothing received keeps (it is
   still Generated / GM-CEO Approved / MD Approved — receiving has not started,
   so there is nothing for this function to say about it).

   A line ordered as 0 has nothing outstanding and so cannot hold the PO open;
   if NO line carries an ordered qty there is nothing to receive against and the
   status is left alone rather than being called Received on an empty promise. */
function poReceiptStatus_(lines,currentStatus){
  const cur=currentStatus||'Generated';
  // A short-closed PO stays closed — a later or corrected receipt must not
  // reopen what an Admin deliberately shut.
  if(cur==='Closed (Short)')return cur;
  const rows=lines||[];
  if(!rows.length)return cur;
  let anyOrdered=false,anyReceived=false,allComplete=true;
  rows.forEach(l=>{
    const ord=pNum(l.ordered_qty),rec=pNum(l.received_qty);
    if(rec>0)anyReceived=true;
    if(ord>0){anyOrdered=true;if(rec<ord)allComplete=false;}
  });
  if(!anyOrdered)return cur;
  if(allComplete)return 'Received';
  return anyReceived?'Partially Received':cur;
}
// Per-line receipt state, for the item-wise breakdown under a PO row.
function poLineReceipt_(l){
  const ordered=pNum(l&&l.ordered_qty),received=pNum(l&&l.received_qty);
  const balance=ordered-received;
  return {ordered,received,balance,
    state:ordered<=0?'—':(received<=0?'PENDING':(balance>0?'PARTIAL':(balance<0?'EXCESS':'FULL')))};
}
// Rows carry their own PO (tr.dataset.poNo), so one Inward can post receipts
// back across several selected POs at once.
async function updatePoReceipt(poNos,rows){
  const wanted=(Array.isArray(poNos)?poNos:[poNos]).filter(Boolean);
  const selected=rows.filter(x=>x.poLineId&&x.qty>0);if(!selected.length)return;
  for(const row of selected){
    const ordered=pNum(row.poOrderedQty),old=pNum(row.poReceivedQty);
    // Over-receipt is allowed only behind the Edit Password gate, which the
    // save flow has already cleared before reaching here.
    const next=old+pNum(row.qty);
    const u=await SB.from('purchase_order_lines').update({received_qty:next}).eq('id',row.poLineId);if(u.error)throw u.error;
  }
  const touched=[...new Set(selected.map(r=>r.poNo).filter(Boolean))];
  for(const poNo of (touched.length?touched:wanted)){
    const po=sarvPoCatalog.find(x=>x.po_no===poNo);if(!po)continue;
    const q=await SB.from('purchase_order_lines').select('ordered_qty,received_qty').eq('purchase_order_id',po.id);if(q.error)throw q.error;
    const lines=q.data||[];
    // Status from the lines item by item (poReceiptStatus_); received_qty stays
    // the plain sum, because that column is a quantity, not a verdict.
    const received=lines.reduce((s,x)=>s+pNum(x.received_qty),0);
    const status=poReceiptStatus_(lines,po.status);
    const u=await SB.from('purchase_orders').update({received_qty:received,status,updated_at:new Date().toISOString()}).eq('id',po.id);if(u.error)throw u.error;
  }
  await loadOpenPoDropdown();await loadPrDropdown_();await refreshGeneratedPoList();
}
/* ================================================================
   EDIT PASSWORD GATE — backs over-receipt / rate-override on a PO.
   The password is the EDIT_PASSWORD entry in role_pins, set by an
   Admin from Settings > Change Passwords.
================================================================ */
/* In-page replacement for window.prompt(), which some hosts (embedded
   webviews, sandboxed iframes) refuse outright with "prompt() is not
   supported" — that is what made an Inward with an excess qty fail on submit
   instead of asking for the Edit Password. Wires up the #pwdGateModal that
   was already in the markup but never bound to anything.
   Resolves with the typed string, or null if cancelled. */
function askSecret({title,subtitle,recordInfo,label,confirmText}={}){
  return new Promise(resolve=>{
    const modal=byId('pwdGateModal'),input=byId('pwdGateInput');
    if(!modal||!input){
      // No modal in the DOM — try the native prompt, and if the host blocks
      // that too, fail loudly rather than throwing inside the save path.
      let v=null;
      try{v=window.prompt((subtitle||title||'Password')+':');}
      catch(e){showToast('Is browser me password prompt support nahi hai','error');}
      resolve(v);return;
    }
    const setTxt=(id,v)=>{const e=byId(id);if(e)e.textContent=v};
    setTxt('pwdGateTitle',title||'Authorization Required');
    setTxt('pwdGateSubtitle',subtitle||'Enter edit password to unlock this record');
    setTxt('pwdGateRecordInfo',recordInfo||'Record: —');
    const lbl=modal.querySelector('.form-group label');
    if(lbl)lbl.textContent=label||'Edit Password';
    const okBtn=byId('pwdGateVerifyBtn'),cancelBtn=byId('pwdGateCancelBtn'),err=byId('pwdGateError');
    if(okBtn)okBtn.innerHTML=confirmText||'&#128275; Verify &amp; Edit';
    if(err){err.style.display='none';err.textContent='';}
    input.value='';
    // Asked for from inside other popups too (Admin Panel → Add User sits at
    // z-index 40010), so it is raised above everything while it is open —
    // otherwise it opened BEHIND the popup that asked for it.
    const prevZ=modal.style.zIndex;
    modal.style.zIndex='40100';
    modal.style.display='flex';
    setTimeout(()=>input.focus(),50);
    const cleanup=()=>{
      modal.style.display='none';
      modal.style.zIndex=prevZ;
      okBtn&&okBtn.removeEventListener('click',onOk);
      cancelBtn&&cancelBtn.removeEventListener('click',onCancel);
      input.removeEventListener('keydown',onKey);
    };
    const onOk=()=>{const v=input.value;cleanup();resolve(v);};
    const onCancel=()=>{cleanup();resolve(null);};
    const onKey=e=>{
      if(e.key==='Enter'){e.preventDefault();onOk();}
      else if(e.key==='Escape'){e.preventDefault();onCancel();}
    };
    okBtn&&okBtn.addEventListener('click',onOk);
    cancelBtn&&cancelBtn.addEventListener('click',onCancel);
    input.addEventListener('keydown',onKey);
  });
}
async function verifyEditPassword(reason){
  if(!SB_READY){showToast('Supabase configure karein','warn');return false;}
  // Only whether a password EXISTS is asked here — the hash itself is never
  // fetched. The comparison happens server-side in verify_role_pin(); see the
  // ROLE PIN MANAGEMENT block for why.
  let exists=false;
  try{
    const q=await SB.rpc('role_pin_exists',{p_role:'EDIT_PASSWORD'});
    if(q.error)throw q.error;
    exists=!!q.data;
  }catch(e){
    showToast('Edit Password check nahi ho paaya: '+(e.message||e),'error');
    return false;
  }
  if(!exists){
    showToast('⚠️ Edit Password set nahi hai — Admin Settings > Change Passwords me set kare','warn');
    return false;
  }
  const entered=await askSecret({
    title:'Authorization Required',
    subtitle:'PO se alag values save karne ke liye Edit Password chahiye',
    recordInfo:reason||'Record: —',
  });
  if(entered==null)return false;
  if(!entered.trim()){showToast('Edit Password khali nahi ho sakta','warn');return false;}
  try{
    const v=await SB.rpc('verify_role_pin',{p_role:'EDIT_PASSWORD',p_pin:entered.trim()});
    if(v.error)throw v.error;
    if(!v.data){showToast('❌ Galat Edit Password','error');return false;}
  }catch(e){
    // A check that cannot run must not be read as a pass.
    showToast('Edit Password verify nahi ho paaya: '+(e.message||e),'error');
    return false;
  }
  return true;
}
/* ══ INWARD APPROVAL (MD) ══════════════════════════════════════
   Three things on a PO receipt cost money that nobody agreed to:
     • EXCESS QTY  — more than the PO / PR still has pending
     • RATE        — a price above what the PO settled on
     • EXTRA ITEM  — something the PO never ordered, typed in with + Add Row
   inwardDocOverrides() names them (it always has); what changed is who says
   yes. It used to be whoever knew the Edit Password, at this desk, with no
   record left behind. Now it is the MD — only the MD — from mobile.html's PO
   Receipts ▸ Inward Approval sub-tab (the sub-tab is shown to the MD login
   alone). Until the MD approves, Submit Inward does not save.

   The request lives in its own table, `inward_approvals`, keyed by a SIGNATURE
   of the exact submission it was asked for (header + every row's name / qty /
   weight / rate / PO line). Approve the receipt, then change a quantity, and
   the signature no longer matches — the approval does not carry over to the
   edited figures, which is the whole reason it is a signature and not a flag.

   On a database without the table the desk is not locked out: it falls back to
   the Edit Password exactly as before, and says which migration to run. */
const INWARD_APPROVAL_TABLE='inward_approvals';
function inwardApprovalTableMissing_(e){
  const m=String((e&&e.message)||'');
  return /inward_approvals/i.test(m)&&/does not exist|relation|schema cache|could not find/i.test(m);
}
/* The fingerprint of THIS submission. Everything an approval is given for has
   to be in here: change any of it and the Purchaser is asked again. Row
   strings are sorted so re-ordering the rows on screen — which changes nothing
   about what is being received — does not invalidate an approval. */
function inwardApprovalSignature_(rows,poNos,prNos){
  const head=[
    pVal('entryTypeSelect')||'INWARD',
    String(pVal('supplierName')||'').trim().toUpperCase(),
    String(pVal('invoiceNumber')||'').trim().toUpperCase(),
    String(pVal('invoiceDate')||''),
    (poNos||[]).join('+').toUpperCase(),
    (prNos||[]).join('+').toUpperCase()
  ].join('~');
  const body=(rows||[]).map(r=>[
    String(r.name||'').trim().toUpperCase(),
    pNum(r.qty),pNum(r.weight),pNum(r.rate),
    String(r.poLineId||''),String(r.prNo||'').toUpperCase()
  ].join('|')).sort().join(';');
  return head+'::'+body;
}
/* Which Purchaser this request belongs to, so it surfaces on THEIR phone
   rather than on every Purchaser's. Read off the requirements behind the
   receipt: the PR's own purchaser_name for a without-PO entry, and for a PO
   receipt the purchaser_name of the PRs the PO was raised from. Several (or
   none) is a legitimate answer — mobile.html shows an unattributed request to
   every Purchaser rather than to nobody. */
async function inwardApprovalPurchasers_(poNos,prNos){
  if(!SB_READY)return[];
  const reqNos=[...prNos];
  try{
    if(poNos.length){
      const pq=await SB.from('purchase_orders').select('po_no,linked_req_nos').in('po_no',poNos);
      if(!pq.error)(pq.data||[]).forEach(p=>String(p.linked_req_nos||'').split(',')
        .map(s=>s.trim()).filter(Boolean)
        .forEach(n=>{if(!reqNos.some(x=>x.toUpperCase()===n.toUpperCase()))reqNos.push(n)}));
    }
    if(!reqNos.length)return[];
    const rq=await SB.from('purchase_requirements').select('req_no,purchaser_name').in('req_no',reqNos);
    if(rq.error)throw rq.error;
    return [...new Set((rq.data||[]).map(r=>String(r.purchaser_name||'').trim()).filter(Boolean))];
  }catch(e){
    console.warn('[SARV] Inward approval purchaser lookup skipped:',e.message||e);
    return[];
  }
}
/* What the Purchaser actually reads on their phone. Deliberately a snapshot,
   not a set of ids: the receipt does not exist yet (that is the point), so
   there is nothing on the server to join back to. The per-row figures are the
   same ones docStripParts_ draws on screen and prints on the PDF, so what is
   approved is literally what was shown. */
function inwardApprovalPayload_(rows,overrides,poNos,prNos){
  return {
    entryType:pVal('entryTypeSelect')||'INWARD',
    supplier:pVal('supplierName')||'',
    invoiceNo:pVal('invoiceNumber')||'',
    invoiceDate:pVal('invoiceDate')||'',
    receivingDate:pVal('receivingDate')||'',
    natureOfInward:pVal('inwNatureOfInward')||'',
    remarks:pVal('inwRemarks')||'',
    poNos:poNos,prNos:prNos,
    reasons:overrides,
    items:(rows||[]).map(r=>{
      const p=docStripParts_(r)||null;
      return {
        name:r.name||'',uom:r.uom||'',
        qty:pNum(r.qty),weight:pNum(r.weight),rate:pNum(r.rate),
        amount:pNum(r.total),
        docKind:p?p.kind:'',docNo:p?String(p.no||''):'',
        ordered:p?pNum(p.ordered):0,
        already:p?pNum(p.already):0,
        pending:p?Math.max(0,pNum(p.ordered)-pNum(p.already)):0,
        excess:p?pNum(p.excess):0,
        /* The WEIGHT side of the same four figures. Sent because an over-weight
           receipt is now a reason on its own: without these the MD would read
           "excess 0" on the qty row and have nothing on screen explaining why
           the request was raised at all. hasWeight says whether the document
           carries an ordered weight to measure against — mobile.html prints the
           weight line only when it does. */
        hasWeight:!!(p&&p.hasWeight),
        orderedWt:p?pNum(p.ordWt):0,
        alreadyWt:p?pNum(p.alreadyWt):0,
        pendingWt:p?Math.max(0,pNum(p.ordWt)-pNum(p.alreadyWt)):0,
        excessWt:p?pNum(p.excWt):0,
        poRate:(p&&p.poRate!=null)?pNum(p.poRate):null,
        // An item the PO never ordered — no line to measure it against.
        extraItem:!!(poNos.length&&!r.poLineId&&!r.savedLine)
      };
    })
  };
}
/* The gate itself. Returns true only when this exact submission already
   carries the Purchaser's approval. */
async function ensureInwardApproval_(rows,overrides){
  const poNos=inwardPoRefList_(rows), prNos=inwardPrRefList_(rows);
  const sig=inwardApprovalSignature_(rows,poNos,prNos);
  const reasonText='PO / PR se alag values mili:\n• '+overrides.join('\n• ');
  let existing=null;
  try{
    const q=await SB.from(INWARD_APPROVAL_TABLE).select('*')
      .eq('signature',sig).order('id',{ascending:false}).limit(1);
    if(q.error)throw q.error;
    existing=(q.data||[])[0]||null;
  }catch(e){
    if(inwardApprovalTableMissing_(e)){
      // No table, no approval desk — fall back to the Edit Password rather
      // than making the receipt unsaveable, and say what to run.
      showToast('⚠️ <b>inward_approvals</b> table nahi hai — <code>INWARD_APPROVAL_MIGRATION.sql</code> chalayein.<br>Tab tak excess / rate / extra item sirf Edit Password se save hoga.','warn');
      return await verifyEditPassword(reasonText);
    }
    showToast('Inward Approval check nahi ho paaya: '+(e.message||e),'error');
    return false;
  }
  const status=String((existing&&existing.status)||'');
  if(status==='Approved'){
    showToast('✅ MD ne ye entry approve kar di hai ('+escText(existing.decided_by||'MD')+') — save ho rahi hai');
    return true;
  }
  if(status==='Pending'){
    showToast('⏳ Ye entry MD ke paas approval ke liye bheji ja chuki hai ('+escText(existing.request_no||'')+').<br>'
      +'Jab tak mobile app ke <b>PO Receipts ▸ Inward Approval</b> me approve nahi hoti, Submit Inward nahi hoga.','warn');
    return false;
  }
  const wasRejected=status==='Rejected';
  const ask=wasRejected
    ?('❌ MD ne ye entry REJECT kar di thi'
      +(existing.remarks?('\n\nWajah: '+existing.remarks):'')
      +'\n\nValues theek karke dobara approval ke liye bhejein?')
    :('Is entry me PO / PR se alag values hain:\n\n• '+overrides.join('\n• ')
      +'\n\nMD ki approval ke bina ye save nahi hogi.\nAbhi approval ke liye bhej dein?');
  if(!confirm(ask))return false;
  const purchasers=await inwardApprovalPurchasers_(poNos,prNos);
  const requestNo='IA-'+Date.now().toString(36).toUpperCase()+'-'+Math.floor(Math.random()*900+100);
  const payload={
    request_no:existing?existing.request_no:requestNo,
    signature:sig,
    status:'Pending',
    entry_type:pVal('entryTypeSelect')||'INWARD',
    po_numbers:poNos.join(', ')||null,
    req_numbers:prNos.join(', ')||null,
    supplier_name:pVal('supplierName')||null,
    invoice_no:pVal('invoiceNumber')||null,
    invoice_date:pVal('invoiceDate')||null,
    purchaser_names:purchasers.join(', ')||null,
    reasons:overrides,
    payload:inwardApprovalPayload_(rows,overrides,poNos,prNos),
    decided_by:null,decided_at:null,remarks:null
  };
  try{
    const w=existing
      ? await SB.from(INWARD_APPROVAL_TABLE).update(payload).eq('id',existing.id)
      : await SB.from(INWARD_APPROVAL_TABLE).insert(payload);
    if(w.error)throw w.error;
  }catch(e){
    showToast('Approval request bhej nahi paaye: '+(e.message||e),'error');
    return false;
  }
  showToast('📨 Approval request bhej di gayi ('+escText(payload.request_no)+')'
    +'.<br>MD ke mobile app me <b>PO Receipts ▸ Inward Approval</b> me approve hone ke baad yahi entry dobara Submit karein.','warn');
  return false;
}
// Flags any row that exceeds its PO pending qty or changes the PO's rate.
/* Everything this receipt does that goes BEYOND the document it is booked
   against. Each one needs the Purchaser's approval before it can be saved —
   see ensureInwardApproval_ above, which turns this list into the request
   they read on their phone. (On a database without inward_approvals it is
   still the Edit Password, as it was before.)

   Every reason is read through docStripParts_ — the same function that draws
   the Excess figures on the row's sub-row and prints them on the PDF. So the
   rule is exactly what the user can already see: if the strip shows Excess in
   red, the save asks the MD. Nothing to keep in step by hand.

   • EXCESS QTY — more than the PO's or the PR's pending quantity. A PR
     receipt is held to the same rule a PO receipt is; previously only POs
     were checked, so a "without PO" entry could over-receive silently.
   • EXCESS WEIGHT — more KGS than the PO / PR line still has pending. This
     costs money on its own, and on a WEIGHT-billed line it is the ONLY thing
     that does: the amount is Gross Wt x rate, so a receipt can sit exactly on
     the ordered Qty, at exactly the PO's rate, and still be billed for 200 kg
     nobody ordered. The qty check never saw it and the save went straight
     through. The red Excess Wt pill was already on screen and on the PDF —
     now it gates the save, like every other figure that goes past the order.
   • RATE — a PO line's agreed price changed on the way in. PR has no agreed
     price (the bill's rate is typed in), so this one is PO-only. */
function inwardDocOverrides(rows){
  const out=[];
  /* Is this receipt booked against a PO at all? Read the same three ways the
     printed PO Reference is (picker, its label on an edit, and each row's own
     PO number), so an Admin edit — where the picker is deliberately never
     re-ticked — is judged the same as a fresh entry. */
  const poBased=inwardPoRefList_(rows).length>0;
  (rows||[]).forEach(r=>{
    const p=docStripParts_(r);
    /* RETURN strips are deliberately NOT a reason to ask anybody. A repair
       return is the unit's own material coming back on a gate pass — there is
       no PO, no agreed price and no Purchaser who negotiated it, so routing an
       over-receipt to the Purchaser's Inward Approval queue would send it to
       someone with no basis to judge it. The excess is still shown in red on
       the row's strip and printed on the PDF; it just does not gate the save,
       which is exactly how it behaved before the strip existed. */
    if(p&&p.kind!=='RETURN'&&p.excess>0){
      const pending=Math.max(0,p.ordered-p.already);
      out.push(r.name+' — '+p.kind+' '+p.no+': qty '+pNum(r.qty)
        +', pending sirf '+pending+'  (excess '+p.excess+')');
    }
    /* WEIGHT, on exactly the same footing as qty. Only asked where the document
       actually carries an ordered weight (p.hasWeight) — a qty-only order has
       no weight to be over on, and measuring against a zero would flag every
       receipt that happens to record a weight. RETURN is excluded for the same
       reason it is above: a repair return is the unit's own material and there
       is no Purchaser who negotiated it. */
    if(p&&p.kind!=='RETURN'&&p.hasWeight&&p.excWt>0){
      const pendWt=Math.max(0,p.ordWt-p.alreadyWt);
      out.push(r.name+' — '+p.kind+' '+p.no+': received weight '+nWt_(r.weight)
        +' KGS, pending sirf '+nWt_(pendWt)+' KGS  (excess '+nWt_(p.excWt)+' KGS)');
    }
    // Both sides NET of discount: the row's List Price − Disc% against the PO
    // line's unit price − its Disc% (poUnitPrice, see loadPoIntoInward).
    if(r.poLineId&&r.poUnitPrice!=null&&r.poUnitPrice!==''&&Math.abs(pNum(r.rate)-pNum(r.poUnitPrice))>0.001)
      out.push(r.name+': rate (after disc) '+nNum_(r.rate)+' ≠ PO rate (after disc) '+nNum_(r.poUnitPrice));
    /* An ITEM THAT IS NOT ON THE PO. Rows loaded from the PO carry its line's
       id; a row typed in with + Add Row carries nothing. Receiving something
       the PO never ordered is a bigger decision than receiving too much of
       something it did — it has no agreed rate, no approval behind it, and
       nothing on the PO to reconcile against — so it is gated the same way.

       `savedLine` keeps this honest on an edit: a line restored from the saved
       record is not "just added", even when it has no PO link because it
       predates the po_line_id column. */
    if(poBased&&!r.poLineId&&!r.savedLine)
      out.push(r.name+': PO par ye item hai hi nahi — extra item add kiya gaya hai (qty '+pNum(r.qty)+')');
  });
  return out;
}
/* itemId: the exact Item Master row the user picked, captured on the entry row
   by applyItemAutofill. It has to be honoured here, because several rows may
   carry the SAME name — a name lookup alone would bind the saved line back to
   whichever duplicate comes first, which is the same wrong-row bug the Item
   Name dropdown had. Falls back to the name lookup (and then to creating the
   item) when no row was pinned, e.g. a bulk import or an older saved record. */
async function ensureItem(name, description='', make='', category='', uom='PCS', itemId=''){
  name=(name||'').trim(); if(!name)return null;
  if(itemId){
    // Deliberately NOT selecting gst_pct here: naming a column that does not
    // exist makes PostgREST reject the whole query, which would break every
    // save on a database that predates it. The Item Master cache reads `*`,
    // so itemGst_() still resolves the rate for auto-fill.
    const byId=await SB.from('items').select('id,item_code,name,uom').eq('id',itemId).maybeSingle();
    if(!byId.error&&byId.data)return byId.data;
  }
  let q=await SB.from('items').select('id,item_code,name,uom').ilike('name',name).limit(1).maybeSingle();
  if(q.error)throw q.error; if(q.data)return q.data;
  const code=(name.toUpperCase().replace(/[^A-Z0-9]+/g,'-').replace(/^-|-$/g,'').slice(0,32)||'ITEM')+'-'+String(Date.now()).slice(-4);
  const ins=await SB.from('items').insert({item_code:code,name,description:description||null,make:make||null,category:category||null,uom:uom||'PCS'}).select('id,item_code,name,uom').single();
  if(ins.error)throw ins.error; return ins.data;
}
function activatePanel(id){
  const storeRoot=byId('storeInterface');
  const fullPurchase=byId('fullPurchasePanel');
  const showingFull=id==='fullPurchasePanel';
  if(storeRoot) storeRoot.style.display=showingFull?'none':'';
  if(fullPurchase) fullPurchase.style.display=showingFull?'block':'none';
  document.querySelectorAll('#storeInterface .main-panel').forEach(x=>x.style.display='none');
  // 'block' here overrides .main-panel's own `display:flex`, which leaves the
  // panel a plain block box: .card's flex:1 goes inert, its height becomes
  // content-driven, and nothing inside can ever become a scroll region — the
  // overflow just gets clipped by .main-panel's height:100%/overflow:hidden.
  // Item Tracker needs that chain intact so its ledger scrolls, so it opens as
  // a flex column. The other panels keep their existing block behaviour.
  if(!showingFull){const el=byId(id);if(el)el.style.display=(id==='itemTrackerPanel')?'flex':'block'}
  document.querySelectorAll('#storeInterface .nav-link[data-target]').forEach(x=>x.classList.toggle('active',x.dataset.target===id));
  // ── Sidebar: Inward only (billing/freight not relevant to Outward) ──
  const sidebar=byId('sidebarPanel');
  const container=document.querySelector('#storeInterface .container');
  const showSidebar=id==='inwardPanel'&&!showingFull;
  if(sidebar){sidebar.style.display=showSidebar?'':'none';}
  if(container){container.style.gridTemplateColumns=showSidebar?'1fr 350px':'1fr';}
  // ── Serial No. auto-load on panel switch ──────────────────
  if(SB_READY){
    if(id==='inwardPanel'){
      nextNo('INWARD').then(no=>{const e=byId('regEntryNo');if(e)e.value=no;}).catch(()=>{});
      refreshSerialNo('INWARD').catch(()=>{});
    }
    if(id==='outwardPanel'){
      nextNo('OUTWARD').then(no=>{const e=byId('outRegEntryNo');if(e)e.value=no;}).catch(()=>{});
      refreshSerialNo('OUTWARD').catch(()=>{});
    }
    // Supplier / Party Name dropdowns: if the startup preload didn't land
    // (slow network, etc.), fill them now rather than waiting for someone to
    // refresh Supplier Master.
    if((id==='inwardPanel'||id==='outwardPanel')&&!(sarvSupplierCatalog||[]).length){
      fetchAllRows('suppliers',SARV_SUPPLIER_COLS,'supplier_name')
        .then(data=>{if(data&&data.length)refreshSupplierDatalist(data);})
        .catch(e=>console.warn('[SARV] Supplier list load failed:',e.message||e));
    }
  }
  // ── Auto-load master data when navigating to masterDataPanel ─
  /* Layout first, and outside the SB_READY gate: the Item Master tab is the one
     shown by default here, so its Add form and list height have to be set up
     even on a visit where no data loads. */
  if(id==='masterDataPanel'){initAddItemForm_();fitItemListHeight_();}
  if(id==='masterDataPanel'&&SB_READY){
    loadItemMaster().catch(()=>{});
    loadSupplierMaster().catch(()=>{});
    loadEmployeeMaster().catch(()=>{});
  }
  if(id==='reportsPanel'&&SB_READY) loadReports().catch(()=>{});
  if(id==='itemTrackerPanel'&&SB_READY) initItemTrackerFilters().catch(()=>{});
  if(id==='repairTrackerPanel'&&SB_READY) loadRepairTracker().catch(()=>{});
  /* Production › Design Master — designs aur unke matchings pehli baar yahan
     load hote hain (uske baad cache se, Refresh par dobara). */
  if(id==='productionPanel'&&SB_READY&&typeof dmEnsureLoaded==='function') dmEnsureLoaded().catch(()=>{});
}
function bindNavigation(){
  document.querySelectorAll('.nav-link[data-target]').forEach(link=>link.addEventListener('click',()=>activatePanel(link.dataset.target)));
  document.querySelectorAll('#fullPurchasePanel .nav-link[data-tab]').forEach(link=>link.addEventListener('click',event=>{
    event.preventDefault();
    document.querySelectorAll('#fullPurchasePanel .tab-content').forEach(x=>{x.classList.remove('active');x.style.display='none'});
    const target=byId('p_tab-'+link.dataset.tab);
    if(target){target.classList.add('active');target.style.display='block'}
    document.querySelectorAll('#fullPurchasePanel .nav-link[data-tab]').forEach(x=>x.classList.toggle('active',x===link));
  }));
  const initial=byId('p_tab-entry');
  if(initial){document.querySelectorAll('#fullPurchasePanel .tab-content').forEach(x=>x.style.display='none');initial.style.display='block';initial.classList.add('active')}
  const cs=byId('connectionStatus')||byId('syncStatus'); if(cs)cs.textContent=SB_READY?'Supabase online':'Supabase setup required';
}
/* afterTr — the row whose ＋ button was pressed. The new line then lands
   directly under it (and under its PO strip, when there is one) instead of at
   the end of the table; every other caller passes nothing and still appends. */
function addNewRow(afterTr){
 const tb=byId('itemTableBody');if(!tb)return;const tr=document.createElement('tr');tr.innerHTML=`
 <td><input type="text" class="table-input item-name" placeholder="Type item name..." list="dl-item-name" autocomplete="off"></td>
 <td><input type="text" class="table-input item-desc" placeholder="Auto from Master" disabled></td>
 <td><input type="text" class="table-input item-make" placeholder="Make" list="dl-item-make"></td>
 <td><input type="text" class="table-input item-cat" placeholder="Auto from Master" disabled></td>
 <td><input type="number" class="table-input qty-field" value="0" min="0"></td>
 <td><input type="text" class="table-input item-uom" value="" readonly style="background:#f1f5f9;cursor:not-allowed;" title="UOM Item Master se locked hai"></td>
 <td><input type="number" class="table-input weight-field" value="0" min="0"></td>
 <td><select class="table-input chip-select item-wunit"><option>KGS</option><option>LBS</option></select></td>
 <td><select class="table-input chip-select bill-basis-field"><option value="QTY">QTY</option><option value="WEIGHT">WEIGHT</option></select></td>
 <td><input type="number" class="table-input list-price-field" value="0" min="0"></td>
 <td><input type="number" class="table-input discount-field" value="0" min="0" max="100" step=".01"></td>
 <td><input type="number" class="table-input rate-field" value="0" disabled></td>
 <td><select class="table-input chip-select item-gst-field"><option>5</option><option>12</option><option>18</option><option>28</option><option>0</option></select></td>
 <td class="row-total-cell">₹0.00</td><td class="row-actions"><button type="button" class="add-row-btn" title="Iske neeche nayi row jodein">+</button><button type="button" class="delete-btn" title="Ye row hatayein">✕</button></td>`;
 let anchor=(afterTr&&afterTr.parentNode===tb)?afterTr:null;
 if(anchor){const nx=anchor.nextElementSibling;if(nx&&nx.classList.contains('po-info-row'))anchor=nx;}
 if(anchor)anchor.insertAdjacentElement('afterend',tr);else tb.appendChild(tr);
 tr.querySelector('.delete-btn').onclick=()=>{tr.remove();updateStoreTotals()};
 tr.querySelector('.add-row-btn').onclick=()=>{const nr=addNewRow(tr);nr?.querySelector('.item-name')?.focus();};
 tr.querySelectorAll('input,select').forEach(x=>x.oninput=()=>updateStoreTotals());
 // Auto-fill from Item Master when item name is selected
 const niName=tr.querySelector('.item-name');
 if(niName){
   // true = committed pick: resolve the "NAME [ITEM_CODE]" form a duplicated
   // name comes through as, and put the plain name back in the box.
   niName.addEventListener('change',function(){applyItemAutofill(this.value,tr,'inward',true);});
   niName.addEventListener('input',function(){if(lookupItem(this.value))applyItemAutofill(this.value,tr,'inward');});
   lockToMasterList(niName,itemNameMasterValues);
 }
 const niMake=tr.querySelector('.item-make');
 if(niMake)lockToMasterList(niMake,()=>[...new Set(sarvItemCatalog.map(it=>it.make).filter(Boolean))]);
 // A fresh row defaults to 5% GST — pin it back to 0 if this is an INWARD NB.
 applyInwardNbGstLock();
 updateStoreTotals();
 return tr;
}
function addOutwardItemRow(afterTr){
 const tb=byId('outwardItemTableBody');if(!tb)return;const tr=document.createElement('tr');tr.innerHTML=`
 <td class="out-sr-no">—</td><td><input class="table-input out-item-name" placeholder="Type item name..." list="dl-out-item-name"></td>
 <td><input class="table-input out-item-desc" placeholder="Auto from Master" disabled></td><td><input class="table-input out-item-make" placeholder="Brand / OEM"></td>
 <td><input class="table-input out-item-cat" placeholder="Auto from Master" disabled></td><td><input class="table-input out-machine-name" placeholder="Select machine..." title="Machine Master list se select karein — Machine No. apne-aap bhar jayega"></td><td><input class="table-input out-machine-no" placeholder="No." title="Machine Master list se select karein"></td>
 <td><input type="number" class="table-input out-qty" value="0" min="0" step=".01"></td><td><input class="table-input out-qty-uom" value="" readonly style="background:#f1f5f9;cursor:not-allowed;" title="UOM Item Master se locked hai"></td><td><input type="number" class="table-input out-weight" value="0" min="0" step=".001"></td><td><select class="table-input out-wunit"><option>KGS</option><option>GMS</option><option>LBS</option></select></td><td class="row-actions"><button type="button" class="add-row-btn" title="Iske neeche nayi row jodein">+</button><button type="button" class="delete-btn" title="Ye row hatayein">✕</button></td>`;
 let anchor=(afterTr&&afterTr.parentNode===tb)?afterTr:null;
 if(anchor){const nx=anchor.nextElementSibling;if(nx&&nx.classList.contains('po-info-row'))anchor=nx;}
 if(anchor)anchor.insertAdjacentElement('afterend',tr);else tb.appendChild(tr);
 tr.querySelector('.delete-btn').onclick=()=>{tr.remove();updateOutTotals()};
 tr.querySelector('.add-row-btn').onclick=()=>{const nr=addOutwardItemRow(tr);nr?.querySelector('.out-item-name')?.focus();};
 tr.querySelectorAll('input').forEach(x=>x.oninput=updateOutTotals);
 // Auto-fill from Item Master when out item name is selected
 const oiName=tr.querySelector('.out-item-name');
 if(oiName){
   oiName.addEventListener('change',function(){applyItemAutofill(this.value,tr,'outward',true);});
   oiName.addEventListener('input',function(){if(lookupItem(this.value))applyItemAutofill(this.value,tr,'outward');});
   lockToMasterList(oiName,itemNameMasterValues);
 }
 // Machine Name + No. — Machine Master list only; a pick fills both.
 attachMachinePair_(tr,'.out-machine-name','.out-machine-no');
 updateOutTotals();
 return tr;
}
/* Serial No. (Auto) — the running count of entries of this kind, i.e. the
   number THIS entry will be once saved. Distinct from the Inward/Outward No.,
   which is the formatted document number (SIHF-II/2025-26/001). Both the
   inward and outward Serial boxes were markup-only until now.
   A head+count query keeps this cheap — no rows come back. */
async function refreshSerialNo(panel){
  if(!SB_READY)return;
  const isOut=panel==='OUTWARD';
  const fieldId=isOut?'outSerialField':'serialNoField';
  const el=byId(fieldId);if(!el)return;
  const table=isOut?'outward_entries':'inward_entries';
  const entryType=isOut?(byId('outEntryTypeSelect')?.value||'OUTWARD'):(byId('entryTypeSelect')?.value||'INWARD');
  try{
    let q=SB.from(table).select('id',{count:'exact',head:true});
    if(entryType)q=q.eq('entry_type',entryType);
    const {count,error}=await q;
    if(error)throw error;
    el.value=String(pNum(count)+1);
  }catch(e){
    console.warn('[SARV] Serial No. lookup skipped:',e.message||e);
    el.value='';
  }
}

/* INWARD NB is a non-billable receipt — it never carries tax, so every item
   row's GST% is pinned to 0 and locked. Re-applied whenever the Entry Type
   changes and after each new row is added, since a fresh row defaults to 5%.
   A disabled <select> still reports .value, so the save path reads 0 as usual. */
function applyInwardNbGstLock(){
  const isNb=(byId('entryTypeSelect')?.value||'')==='INWARD NB';
  document.querySelectorAll('#itemTableBody .item-gst-field').forEach(sel=>{
    if(isNb)sel.value='0';
    sel.disabled=isNb;
    sel.style.background=isNb?'#f1f5f9':'';
    sel.style.cursor=isNb?'not-allowed':'';
    sel.title=isNb?'INWARD NB non-billable hai — GST hamesha 0 rehta hai':'';
  });
  if(isNb)updateStoreTotals();
}
function updateStoreTotals(){
  const rows=[...document.querySelectorAll('#itemTableBody tr:not(.po-info-row)')];
  let qty=0, base=0, weightedGst=0, totalGstWt=0, netWt=0;
  rows.forEach(r=>{
    const rowQty=+r.querySelector('.qty-field')?.value||0;
    const listP=+r.querySelector('.list-price-field')?.value||0;
    const disc=+r.querySelector('.discount-field')?.value||0;
    const gst=+r.querySelector('.item-gst-field')?.value||0;
    const netRate=listP-listP*disc/100;
    const rowWeight=+r.querySelector('.weight-field')?.value||0;
    // Bill Basis: WEIGHT bills the row on Gross Wt × net rate, QTY on Qty × net rate.
    const basis=r.querySelector('.bill-basis-field')?.value||'QTY';
    const rowTotal=netRate*(basis==='WEIGHT'?rowWeight:rowQty);
    qty+=rowQty; base+=rowTotal;
    weightedGst+=gst*rowTotal; totalGstWt+=rowTotal;
    netWt+=rowWeight;
    if(r.querySelector('.rate-field'))r.querySelector('.rate-field').value=netRate.toFixed(2);
    if(r.querySelector('.row-total-cell'))r.querySelector('.row-total-cell').textContent='₹'+rowTotal.toFixed(2);
  });
  const avgGst=totalGstWt>0?weightedGst/totalGstWt:0;
  const freight=+byId('freightExp')?.value||0;
  const roundOff=+byId('roundOffInput')?.value||0;
  const taxable=base+freight;
  const taxAmt=taxable*avgGst/100;
  const finalAmt=taxable+taxAmt+roundOff;
  const state=(byId('partyState')?.value||'').toUpperCase();
  const isLocal=!state||state.includes('HARYANA')||state.includes('LOCAL');
  const m=v=>'₹'+v.toFixed(2);
  // Sidebar updates
  if(byId('itemsBaseTotal'))byId('itemsBaseTotal').textContent=m(base);
  if(byId('taxableAmount'))byId('taxableAmount').textContent=m(taxable);
  if(byId('overallGstDisplay'))byId('overallGstDisplay').textContent=avgGst.toFixed(1)+'%';
  if(byId('appliedTaxLabel'))byId('appliedTaxLabel').textContent='Total Applied Tax ('+avgGst.toFixed(1)+'% GST)';
  if(byId('totalTaxAmount'))byId('totalTaxAmount').textContent=m(taxAmt);
  if(byId('finalAmount'))byId('finalAmount').textContent=m(finalAmt);
  // CGST/SGST vs IGST
  if(isLocal){
    const half=taxAmt/2;
    if(byId('cgstLabel'))byId('cgstLabel').textContent='CGST ('+(avgGst/2).toFixed(1)+'%)';
    if(byId('cgstAmount'))byId('cgstAmount').textContent=m(half);
    if(byId('sgstLabel'))byId('sgstLabel').textContent='SGST ('+(avgGst/2).toFixed(1)+'%)';
    if(byId('sgstAmount'))byId('sgstAmount').textContent=m(half);
    if(byId('igstLabel'))byId('igstLabel').textContent='';
    if(byId('igstAmount'))byId('igstAmount').textContent='';
  } else {
    if(byId('igstLabel'))byId('igstLabel').textContent='IGST ('+avgGst.toFixed(1)+'%)';
    if(byId('igstAmount'))byId('igstAmount').textContent=m(taxAmt);
    if(byId('cgstLabel'))byId('cgstLabel').textContent='';if(byId('cgstAmount'))byId('cgstAmount').textContent='';
    if(byId('sgstLabel'))byId('sgstLabel').textContent='';if(byId('sgstAmount'))byId('sgstAmount').textContent='';
  }
  // Freight calculator
  if(byId('calcNetWeight'))byId('calcNetWeight').value=netWt.toFixed(2);
  const grossWt=+byId('calcGrossWeight')?.value||0;
  const freightRate=+byId('calcFreightRate')?.value||0;
  const calcFrt=grossWt*freightRate;
  if(byId('calcFreightAmt'))byId('calcFreightAmt').value=m(calcFrt);
  // Cost on Yarn / Kg = Freight Amt / Net Weight (Items), per the store
  // team spec. Guarded so a zero net weight shows 0, not Infinity.
  const costOnYarn=netWt>0?calcFrt/netWt:0;
  if(byId('calcCostOnYarn'))byId('calcCostOnYarn').value=m(costOnYarn);
  // Inward totals strip. These used to be written to `totalItemCount` /
  // `totalQty`, ids that no longer exist in the markup, so the whole strip sat
  // frozen at its static zeros — and `outTotalCount` here was pushing the
  // INWARD row count into the OUTWARD panel's Items pill. The outward strip is
  // updateOutTotals()'s job alone.
  if(byId('inwTotalCount'))byId('inwTotalCount').textContent=rows.length;
  if(byId('inwTotalQty'))byId('inwTotalQty').textContent=qty;
  if(byId('inwTotalWeight'))byId('inwTotalWeight').textContent=netWt.toFixed(2);
  if(byId('inwTotalAmount'))byId('inwTotalAmount').textContent=m(base);
  // Header stat box — the landed value of this inward: items + freight + tax
  // + round-off, i.e. the same figure the sidebar shows as Final Amount.
  if(byId('netValuationText'))byId('netValuationText').textContent=m(finalAmt);
  // Per-item PO strips: Excess depends on the qty just typed, and this runs on
  // every item-row keystroke, so the strips stay in step for free.
  refreshPoInfoRows();
}
function updateOutTotals(){const rows=[...document.querySelectorAll('#outwardItemTableBody tr')];let q=0,w=0;rows.forEach((r,i)=>{q+=+r.querySelector('.out-qty')?.value||0;w+=+r.querySelector('.out-weight')?.value||0;r.querySelector('.out-sr-no').textContent=i+1});if(byId('outTotalCount'))byId('outTotalCount').textContent=rows.length;if(byId('outTotalQty'))byId('outTotalQty').textContent=q;if(byId('outTotalWeight'))byId('outTotalWeight').textContent=w.toFixed(2);
 // Any edit to the item rows invalidates the last stock-shortfall warning.
 showOutStockWarning(null);}
// Wording for the Outward Mode stat box at the top of the Outward panel.
// Anything not listed here falls back to the raw dropdown value.
const OUTWARD_MODE_LABELS={
  'Non-Returnable':'Non-Returnable Dispatch',
  'Repair':'Repair (Returnable)',
  'Transfer':'Stock Transfer',
  'Sample':'Sample Dispatch',
  'CONSUMABLE':'Consumable Issue',
};
// Mirrors the Nature of Dispatch selection into the Outward Mode stat box,
// which until now was a hard-coded "Non-Returnable Dispatch" that never moved.
function updateOutwardModeText(){
  const sel=byId('outNatureOfDispatch'),el=byId('outModeText');
  if(!el)return;
  const val=sel?.value||'';
  el.textContent=val?(OUTWARD_MODE_LABELS[val]||val):'—';
}
/* ── ISSUE: fixed header fields ───────────────────────────────────────
   An ISSUE is always this unit drawing its own consumables and carrying them
   by hand, so these header fields never vary from entry to entry. On ISSUE they
   are pre-filled and locked rather than left as free text, and Target Return
   Date is hidden outright — a consumable is never coming back. OUTWARD is
   untouched: the same fields stay fully editable there. */
const ISSUE_FIXED_FIELDS={
  outPartyName:'SARV INDIA HOME FURNISHING UNIT-II',
  outLocation:'UNIT-2',
  outTransport:'BY HAND'
};
const ISSUE_FIXED_NATURE='CONSUMABLE';
const ISSUE_FIXED_TITLE='ISSUE entry me yeh field fixed hai — change nahi ho sakta';
function applyIssueFixedFields(){
  const isIssue=(byId('outEntryTypeSelect')?.value||'')==='ISSUE';
  Object.keys(ISSUE_FIXED_FIELDS).forEach(id=>{
    const el=byId(id);if(!el)return;
    // The datalist and the field's own cursor are remembered once, so unlocking
    // can hand both back.
    if(el.dataset.issueCursor===undefined)el.dataset.issueCursor=el.style.cursor;
    if(!el.dataset.issueList&&el.getAttribute('list'))el.dataset.issueList=el.getAttribute('list');
    if(isIssue){
      el.value=ISSUE_FIXED_FIELDS[id];
      el.readOnly=true;
      el.removeAttribute('list');            // no dropdown to pick a different one
      el.style.background='#f1f5f9';el.style.cursor='not-allowed';el.title=ISSUE_FIXED_TITLE;
    }else{
      el.readOnly=false;
      if(el.dataset.issueList)el.setAttribute('list',el.dataset.issueList);
      el.style.background='';el.style.cursor=el.dataset.issueCursor||'';el.title='';
    }
  });
  // Nature of Dispatch is CONSUMABLE-only on ISSUE, the usual four on OUTWARD.
  populateNatureOfDispatch();
  // Target Return Date is meaningless for a consumable issue — hidden, and
  // blanked so a value left over from an OUTWARD draft can't be saved.
  const grp=byId('outTargetReturnDateGroup'),trd=byId('outTargetReturnDate');
  if(grp)grp.style.display=isIssue?'none':'';
  if(isIssue&&trd)trd.value='';
}
function populateNatureOfDispatch(){
  const sel=byId('outNatureOfDispatch');if(!sel)return;
  const isIssue=(byId('outEntryTypeSelect')?.value||'')==='ISSUE';
  const cur=sel.value;
  const opts=isIssue?[ISSUE_FIXED_NATURE]:['Non-Returnable','Repair','Transfer','Sample'];
  /* OUTWARD opens with nothing selected. The first option used to be picked by
     default, so "Non-Returnable" went out on every entry nobody touched this
     dropdown on — a Repair dispatch then never reached the Repair Tracker.
     An unselected placeholder forces a deliberate pick; saveOutwardWithPdf()
     refuses to submit while it is still empty. ISSUE is always CONSUMABLE, so
     it keeps its single locked option and needs no placeholder. */
  sel.innerHTML=(isIssue?'':'<option value="">-- Select Nature of Dispatch --</option>')
    +opts.map(o=>`<option value="${o}">${o}</option>`).join('');
  if(isIssue){
    sel.value=ISSUE_FIXED_NATURE;
    sel.disabled=true;sel.style.background='#f1f5f9';sel.style.cursor='not-allowed';sel.title=ISSUE_FIXED_TITLE;
  }else{
    sel.disabled=false;sel.style.background='';sel.style.cursor='pointer';
    sel.title='Compulsory — dispatch ki nature select karein';
    // Only an earlier real pick is carried over; otherwise it stays unselected.
    sel.value=(cur&&opts.includes(cur))?cur:'';
  }
  if(!sel.dataset.modeBound){
    sel.addEventListener('change',updateOutwardModeText);
    sel.dataset.modeBound='1';
  }
  // The options were just rebuilt and the select handed back — a Nature pinned
  // from the Home chooser is put back on top of that.
  if(!isIssue)applyHomeNatureLocks();
  updateOutwardModeText();
}
/* `afterTr`: insert the new row directly BELOW that one instead of at the end
   of the table — what the row's own + button does, so a part remembered
   halfway down the list lands where it belongs rather than at the bottom.
   Same signature and same behaviour as the Store Inward table's addNewRow. */
function addPurchaseMainRow(afterTr){
 const tb=byId('p_itemTableBody');if(!tb)return;
 const tr=document.createElement('tr');
 tr.innerHTML=`<td class="sr-cell"></td>
   <td><input class="table-input col-name" placeholder="Item Name" list="p_dl-item-names" autocomplete="off"></td>
   <td><input class="table-input col-desc" placeholder="Auto from Master" disabled></td>
   <td><input class="table-input col-make" placeholder="Make / Brand" list="p_dl-item-makes" autocomplete="off"></td>
   <td><input class="table-input col-cat" placeholder="Auto from Master" disabled></td>
   <td><input class="table-input col-machine" placeholder="Select machine..." list="dl-inw-machine-name" autocomplete="off" title="Machine Master list se select karein"></td>
   <td><input type="number" class="table-input col-qty" min="0" step="any"></td>
   <td><input class="table-input col-uom" placeholder="Auto from Master" readonly style="background:#f1f5f9;"></td>
   <td><input type="number" class="table-input col-grossweight" min="0" step="any"></td>
   <td><input class="table-input col-rem" placeholder="optional note"></td>
   <td class="row-actions"><button type="button" class="add-row-btn" title="Iske neeche nayi row jodein">+</button><button type="button" class="delete-row-btn" title="Ye row hatayein">×</button></td>`;
 const anchor=(afterTr&&afterTr.parentNode===tb)?afterTr:null;
 if(anchor)anchor.insertAdjacentElement('afterend',tr);else tb.appendChild(tr);
 tr.querySelector('.delete-row-btn').onclick=()=>{tr.remove();refreshPurchaseTotals()};
 tr.querySelector('.add-row-btn').onclick=()=>{const nr=addPurchaseMainRow(tr);nr?.querySelector('.col-name')?.focus();};
 tr.querySelectorAll('input,select').forEach(x=>x.oninput=refreshPurchaseTotals);
 // Auto-fill from Item Master
 const pcName=tr.querySelector('.col-name');
 if(pcName){
   // 'change' is the committed pick, so that is the only place the name gets
   // locked. 'input' still fills Description/Make/Category/UOM as you type or
   // move through the dropdown, but leaves the field editable so the option
   // you actually choose is the one that sticks.
   pcName.addEventListener('change',function(){applyItemAutofill(this.value,tr,'purchase',true);});
   pcName.addEventListener('input',function(){if(lookupItem(this.value))applyItemAutofill(this.value,tr,'purchase');});
   lockToMasterList(pcName,itemNameMasterValues);
 }
 lockMachineField_(tr.querySelector('.col-machine')); // Machine Master list only
 refreshPurchaseTotals();
 // Returned so the row's own + button can focus the line it just made, and so
 // the Add New Item popup can drop a fresh name straight into it.
 return tr;
}
