function bindOriginalControls(){
  const add=(id,fn)=>{const e=byId(id);if(e)e.addEventListener('click',fn)};
  // A row added from the button is scrolled into view with its Item Name
  // focused — with many items the new row lands below the visible area.
  const showNewRow=(bodyId,sel)=>{const rows=byId(bodyId)?.querySelectorAll('tr:not(.po-info-row)');const tr=rows&&rows[rows.length-1];if(!tr)return;tr.scrollIntoView({block:'nearest',behavior:'smooth'});tr.querySelector(sel)?.focus({preventScroll:true});};
  add('addNewItemBtn',()=>{addNewRow();showNewRow('itemTableBody','.item-name');});
  add('outAddNewItemBtn',()=>{addOutwardItemRow();showNewRow('outwardItemTableBody','.out-item-name');});
  add('p_addItemBtn',addPurchaseMainRow);
  // Enter on a filled Item Configurations row (Item Name + Qty > 0) jumps to
  // the next row's Item Name, pressing + Add New Item first when this is the
  // last row. An unfilled row ignores Enter — that is also what keeps an
  // Enter used to pick an Item Name from the datalist from jumping away.
  const inwBody=byId('itemTableBody');
  if(inwBody&&!inwBody.dataset.enterBound){
    inwBody.dataset.enterBound='1';
    inwBody.addEventListener('keydown',e=>{
      if(e.key!=='Enter'||e.shiftKey||e.ctrlKey||e.altKey||e.isComposing)return;
      const tr=e.target.closest('tr');
      if(!tr||tr.classList.contains('po-info-row'))return;
      if(!(tr.querySelector('.item-name')?.value||'').trim()||!(pNum(tr.querySelector('.qty-field')?.value)>0))return;
      e.preventDefault();
      const itemRows=()=>[...inwBody.querySelectorAll('tr:not(.po-info-row)')];
      let next=itemRows()[itemRows().indexOf(tr)+1];
      if(!next){byId('addNewItemBtn')?.click();const all=itemRows();next=all[all.length-1];}
      const first=next&&next!==tr?next.querySelector('.item-name'):null;
      if(first){first.focus();first.scrollIntoView({block:'nearest'});}
    });
  }
  // addItemBtn already has onclick="addMasterItem()" in HTML — do NOT re-bind here
  add('submitBtn',()=>saveInwardWithPdf().catch(dbError));add('outSubmitBtn',()=>saveOutwardWithPdf().catch(dbError));add('p_submitBtn',()=>saveRequirementWithPdf().catch(dbError));
  add('p_backToStoreBtn',()=>sarvGoHome());
  add('repairRefreshBtn',()=>loadRepairTracker().catch(dbError));
  const repairSearch=byId('repairSearchQuery');if(repairSearch&&!repairSearch.dataset.bound){repairSearch.addEventListener('input',renderRepairTrackerTable);repairSearch.dataset.bound='1'}
  const repairStatus=byId('repairStatusFilter');if(repairStatus&&!repairStatus.dataset.bound){repairStatus.addEventListener('change',renderRepairTrackerTable);repairStatus.dataset.bound='1'}
  // ── PO Number checkbox dropdown ──────────────────────────
  const poBtn=byId('poNumberBtn');
  if(poBtn&&!poBtn.dataset.poBound){
    poBtn.addEventListener('click',e=>{e.stopPropagation();togglePoNumberPanel()});
    // Clicking anywhere else closes it; clicks inside the panel must not.
    byId('poNumberPanel')?.addEventListener('click',e=>e.stopPropagation());
    document.addEventListener('click',()=>togglePoNumberPanel(false));
    poBtn.dataset.poBound='1';
  }
  // Supplier Name drives which POs are on offer, so re-filter as it is typed.
  const supEl=byId('supplierName');
  if(supEl&&!supEl.dataset.poFilterBound){
    const refilter=()=>{
      // Drop any ticked PO that the new supplier no longer covers.
      const allowed=poOptionsForSupplier().map(p=>p.po_no);
      const kept=sarvSelectedPoNos.filter(no=>allowed.includes(no));
      if(kept.length!==sarvSelectedPoNos.length){setSelectedPoNos(kept);loadPoIntoInward().catch(dbError);}
      else renderPoNumberPanel();
    };
    supEl.addEventListener('input',refilter);
    supEl.addEventListener('change',refilter);
    supEl.dataset.poFilterBound='1';
  }
  const natureSel=byId('inwNatureOfInward');
  if(natureSel&&!natureSel.dataset.natureBound){
    natureSel.addEventListener('change',()=>{
      const isRepair=natureSel.value==='Repaired';
      if(byId('repairOutwardGroup'))byId('repairOutwardGroup').style.display=isRepair?'block':'none';
      if(byId('gatePassFieldGroup'))byId('gatePassFieldGroup').style.display=isRepair?'':'none';
      if(byId('gatePassMandatoryBadge'))byId('gatePassMandatoryBadge').style.display=isRepair?'inline':'none';
      const gp=byId('gatePassNo');
      if(gp){
        if(isRepair){gp.readOnly=true;gp.style.background='#f1f5f9';gp.title='Auto-filled from the selected Repair Outward entry';}
        else{gp.readOnly=false;gp.style.background='';gp.title='';gp.value='';}
      }
      if(isRepair)loadRepairOutwardDropdown().catch(dbError);
      else setSelectedRepairOutNos([]);
      // PR Number is compulsory on a Purchase only, so its ★ follows the Nature.
      syncInwPrField();
    });
    natureSel.dataset.natureBound='1';
  }
  /* PR Number checkbox dropdown — only live while PO Number reads "Without PO".
     Nothing is typed, so there is no invalid value to validate: the list only
     ever offers FIELD BOY's own open requirements. */
  const prBtn=byId('prNumberBtn');
  if(prBtn&&!prBtn.dataset.prBound){
    prBtn.addEventListener('click',e=>{e.stopPropagation();togglePrNumberPanel()});
    // Clicking anywhere else closes it; clicks inside the panel must not.
    byId('prNumberPanel')?.addEventListener('click',e=>e.stopPropagation());
    document.addEventListener('click',()=>togglePrNumberPanel(false));
    prBtn.dataset.prBound='1';
  }
  // Repair Outward checkbox dropdown — same open/close pattern as the PO picker.
  const repairBtn=byId('repairOutwardBtn');
  if(repairBtn&&!repairBtn.dataset.repairBound){
    repairBtn.addEventListener('click',e=>{e.stopPropagation();toggleRepairOutwardPanel()});
    byId('repairOutwardPanel')?.addEventListener('click',e=>e.stopPropagation());
    document.addEventListener('click',()=>toggleRepairOutwardPanel(false));
    repairBtn.dataset.repairBound='1';
  }
  if(byId('itemTableBody')&&!byId('itemTableBody').children.length)addNewRow();if(byId('outwardItemTableBody')&&!byId('outwardItemTableBody').children.length)addOutwardItemRow();if(byId('p_itemTableBody')&&!byId('p_itemTableBody').children.length)addPurchaseMainRow();
}
