/* ================================================================
   ROLE PIN MANAGEMENT — backs both the Settings > Change Passwords
   panel here and mobile.html's GM/CEO -> MD -> Vendor Verified
   approval login gate. PINs are never stored in plaintext; only a
   SHA-256 hash is kept in the role_pins table (see
   APPROVAL_CHAIN_MIGRATION.sql).
================================================================ */
// Kept for reference only — no longer called. PIN hashing and comparison
// both happen server-side now (verify_role_pin / set_role_pin RPCs).
async function sha256Hex(text){
  const buf=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(String(text)));
  return [...new Uint8Array(buf)].map(b=>b.toString(16).padStart(2,'0')).join('');
}
window.onPwdTargetChange=async function(){
  const role=byId('pwdChangeTarget')?.value||'';
  const form=byId('pwdChangeForm');if(!form)return;
  form.style.display=role?'block':'none';
  ['pwdOld','pwdNew','pwdConfirm'].forEach(id=>{const e=byId(id);if(e)e.value='';});
  const err=byId('pwdChangeError'),ok=byId('pwdChangeSuccess');if(err)err.style.display='none';if(ok)ok.style.display='none';
  if(!role||!SB_READY)return;
  const oldGroup=byId('pwdOld')?.closest('.form-group');
  const grid=oldGroup?.parentElement;
  // An Admin is resetting SOMEONE ELSE'S password — being asked for that
  // person's current one would make the reset impossible, which is the whole
  // point of an admin reset. Reaching this card already requires an Admin
  // login, so the field is dropped entirely and New Password takes the full
  // width. The check below still stands for any other role, in case this panel
  // is ever opened up.
  if(isAdmin()){
    if(oldGroup)oldGroup.style.display='none';
    if(grid)grid.style.gridTemplateColumns='1fr';
    return;
  }
  if(grid)grid.style.gridTemplateColumns='1fr 1fr';
  try{
    const q=await SB.rpc('role_pin_exists',{p_role:role});
    if(q.error)throw q.error;
    if(oldGroup)oldGroup.style.display=q.data?'':'none';
  }catch(e){/* role_pins table may not exist yet — allow first-time set */}
};
window.submitPasswordChange=async function(){
  const role=byId('pwdChangeTarget')?.value||'';
  const err=byId('pwdChangeError'),ok=byId('pwdChangeSuccess');
  const show=(el,msg)=>{if(!el)return;el.textContent=msg;el.style.display='block';};
  if(err)err.style.display='none';if(ok)ok.style.display='none';
  if(!sarvCan('CHANGE_PASSWORDS'))return show(err,'⛔ Aapke role ko Change Passwords ka access nahi hai');
  if(!role)return show(err,'Pehle konsa password change karna hai select karo');
  if(!SB_READY)return show(err,'Supabase URL/key configure karein');
  const newPin=byId('pwdNew')?.value||'',confirmPin=byId('pwdConfirm')?.value||'';
  if(!newPin||newPin.length<4)return show(err,'New password kam se kam 4 characters ka ho');
  if(newPin!==confirmPin)return show(err,'New password aur Confirm password match nahi kar rahe');
  try{
    // The TARGET role's current password is still not asked for — an Admin
    // resetting someone's forgotten PIN has no way to produce it.
    //
    // What IS asked for is the Admin's OWN PIN, once, because the write now
    // happens inside set_role_pin() on the server and that is what authorises
    // it. A browser saying "I am the Admin" cannot authorise anything; the
    // table is no longer writable directly, which is the whole point.
    const adminPin=await askSecret({
      title:'Admin PIN Confirm Karein',
      subtitle:'Password reset server par Admin PIN se authorise hota hai',
      recordInfo:'Reset: '+((byId('pwdChangeTarget')?.selectedOptions[0]?.textContent||role).trim()),
      label:'Admin PIN',
      confirmText:'&#128272; Confirm &amp; Reset'
    });
    if(adminPin==null)return;                       // cancelled
    if(!adminPin.trim())return show(err,'Admin PIN khali nahi ho sakta');
    const u=await SB.rpc('set_role_pin',{p_role:role,p_new_pin:newPin,p_admin_pin:adminPin.trim()});
    if(u.error)throw u.error;
    if(!u.data)return show(err,'❌ Admin PIN galat hai — password change nahi hua');
    // The dropdown's own label covers every option, including the ones that
    // aren't login roles (View PIN, Edit Password) and so aren't in SARV_ROLE_LABEL.
    const sel=byId('pwdChangeTarget');
    const label=(sel&&sel.selectedOptions[0]&&sel.selectedOptions[0].textContent.trim())||role;
    show(ok,isAdmin()
      ? `✅ ${label} reset ho gaya — naya password us user ko de dein`
      : '✅ Password successfully update ho gaya');
    ['pwdOld','pwdNew','pwdConfirm'].forEach(id=>{const e=byId(id);if(e)e.value='';});
  }catch(e){
    if(/does not exist|relation/i.test(e.message||''))show(err,'⚠️ role_pins table missing — APPROVAL_CHAIN_MIGRATION.sql run karein');
    else show(err,e.message||String(e));
  }
};

/* ================================================================
   LOGIN GATE — identity only. Every role can still use every panel
   once logged in; sarvCurrentRole is checked only where a specific
   permission is needed (e.g. isAdmin() for cancelling a PO).
================================================================ */
const SARV_ROLE_LABEL={USER_IC_PIN:'Store In-Charge',USER_GM_PIN:'GM / CEO',USER_MD_PIN:'MD',USER_AC_PIN:'Accountant',USER_GT_PIN:'Gate Man',ADMIN_PIN:'Admin',VENDOR_VERIFY_PIN:'Vendor Verified',PO_SENDER_PIN:'PO Sender (Mobile)',PURCHASER:'Purchaser',VIEW_PIN:'View Only',EDIT_PASSWORD:'Edit User'};
const SARV_LOGIN_STORAGE_KEY='sarv_active_role';
const SARV_LOGIN_USER_KEY='sarv_active_user';
const SARV_LOGIN_SIG_KEY='sarv_active_user_sig';
let sarvCurrentRole=null;
// The named user behind this login ({id,name}), or null for a plain role-PIN login.
let sarvCurrentUser=null;
function isAdmin(){return sarvCurrentRole==='ADMIN_PIN';}
function sarvLoginLabel_(){
  return (SARV_ROLE_LABEL[sarvCurrentRole]||sarvCurrentRole||'—')+(sarvCurrentUser&&sarvCurrentUser.name?' — '+sarvCurrentUser.name:'');
}
/* Fills the User dropdown under Role from app_users. Purchaser always needs a
   name (each one has their own PIN); for the other roles a user is optional —
   "Role PIN" logs in with the role's shared PIN exactly as before. */
async function sarvFillLoginUsers_(){
  const role=byId('sarvLoginRole')?.value||'';
  const grp=byId('sarvLoginUserGroup'),sel=byId('sarvLoginUser');
  if(!grp||!sel)return;
  if(!role){grp.style.display='none';sel.innerHTML='';return;}
  await sarvLoadAppUsers_();
  const users=sarvAppUsers.filter(u=>u.is_active&&u.role===role);
  let opts='';
  if(role==='PURCHASER'){
    opts='<option value="">-- Select Purchaser --</option>';
    opts+=users.length
      ? users.map(u=>'<option value="id:'+escText(u.id)+'">'+escText(u.user_name)+'</option>').join('')
      // app_users not there yet (migration not run) — the old fixed names still work.
      : sarvPurchaserNames_().map(n=>'<option value="pname:'+escText(n)+'">'+escText(n)+'</option>').join('');
  }else{
    if(!users.length){grp.style.display='none';sel.innerHTML='';return;}
    opts='<option value="">Role PIN (shared)</option>'+users.map(u=>'<option value="id:'+escText(u.id)+'">'+escText(u.user_name)+'</option>').join('');
  }
  sel.innerHTML=opts;grp.style.display='';
}
async function sarvAttemptLogin(){
  const role=byId('sarvLoginRole')?.value||'';
  const pin=byId('sarvLoginPin')?.value||'';
  const userVal=byId('sarvLoginUserGroup')?.style.display!=='none'?(byId('sarvLoginUser')?.value||''):'';
  const err=byId('sarvLoginError');
  if(err)err.style.display='none';
  const show=msg=>{if(err){err.textContent=msg;err.style.display='block';}};
  if(!role)return show('Role select karo');
  if(role==='PURCHASER'&&!userVal)return show('Purchaser Name select karo');
  if(!pin)return show('PIN enter karo');
  if(!SB_READY)return show('Supabase URL/key configure karein');
  try{
    // The PIN is checked on the server — the stored hash is never sent here.
    let user=null;
    if(userVal.startsWith('id:')){
      const id=userVal.slice(3);
      const v=await SB.rpc('verify_app_user_pin',{p_user_id:id,p_pin:pin});
      if(v.error)throw v.error;
      if(!v.data)return show('Galat PIN');
      const u=sarvAppUsers.find(x=>x.id===id);
      user={id,name:u?u.user_name:''};
    }else{
      const key=userVal.startsWith('pname:')?('PURCHASER::'+userVal.slice(6)):role;
      const ex=await SB.rpc('role_pin_exists',{p_role:key});
      if(ex.error)throw ex.error;
      if(!ex.data)return show('Is role / user ke liye PIN set nahi hai — Admin se Settings me set karwayein');
      const v=await SB.rpc('verify_role_pin',{p_role:key,p_pin:pin});
      if(v.error)throw v.error;
      if(!v.data)return show('Galat PIN');
      if(userVal.startsWith('pname:'))user={id:null,name:userVal.slice(6)};
    }
    sarvCurrentRole=role;sarvCurrentUser=user;sarvPadForceDraw=false;
    try{
      localStorage.setItem(SARV_LOGIN_STORAGE_KEY,role);
      if(user)localStorage.setItem(SARV_LOGIN_USER_KEY,JSON.stringify(user));else localStorage.removeItem(SARV_LOGIN_USER_KEY);
      localStorage.removeItem(SARV_LOGIN_SIG_KEY);   // no signature is kept between submits any more
    }catch(e){}
    const badge=byId('sarvRoleBadge');if(badge)badge.textContent='👤 '+sarvLoginLabel_();
    const gate=byId('sarvLoginGate');if(gate)gate.style.display='none';
    if(byId('sarvLoginPin'))byId('sarvLoginPin').value='';
    if(byId('p_poListBody'))refreshGeneratedPoList().catch(()=>{});
    sarvApplyAccess();
    sarvGoHome();
  }catch(e){
    if(/verify_app_user_pin/i.test(e.message||''))show('⚠️ ADMIN_PANEL_MIGRATION.sql abhi run nahi hua — user login ke liye pehle wo chalayein');
    else if(/does not exist|relation/i.test(e.message||''))show('⚠️ role_pins table missing — APPROVAL_CHAIN_MIGRATION.sql run karein');
    else show(e.message||String(e));
  }
}
/* Asked here rather than on each caller, because both ways out — the Home page's
   Logout button and the role badge in the header — land on this one function.
   The badge in particular sits next to the nav links, so a mis-click used to
   drop the session and send the user back to the PIN screen with no warning. */
function sarvLogout(){
  if(!confirm('Do you want Log out ?\n\nDobara kaam karne ke liye PIN phir se daalna padega.'))return;
  sarvCurrentRole=null;sarvCurrentUser=null;
  try{localStorage.removeItem(SARV_LOGIN_STORAGE_KEY);localStorage.removeItem(SARV_LOGIN_USER_KEY);localStorage.removeItem(SARV_LOGIN_SIG_KEY);}catch(e){}
  const gate=byId('sarvLoginGate');if(gate)gate.style.display='flex';
}
function sarvUnlockNav(){
  // Only the sections this role may see (Admin Panel → Tab Visibility).
  document.querySelectorAll('#storeInterface .nav-tabs .nav-link[data-target]').forEach(el=>{
    el.style.display=sarvNavTargetVisible_(el.dataset.target)?'':'none';
  });
  document.querySelectorAll('#fullPurchasePanel .nav-tabs .nav-link[data-tab]').forEach(el=>{
    const k={entry:'HOME_PR',po:'HOME_PO'}[el.dataset.tab];
    el.style.display=(!k||sarvTabVisible(k))?'':'none';
  });
}
function sarvLockNavToSection(){
  document.querySelectorAll('#storeInterface .nav-tabs .nav-link[data-target]').forEach(el=>el.style.display='none');
}
function sarvGoHome(){
  const dash=byId('sarvHomeDashboard');if(dash)dash.style.display='block';
  const roleLabel=byId('sarvHomeRoleLabel');if(roleLabel)roleLabel.textContent='👤 '+sarvLoginLabel_();
  sarvApFullScreen_(false);   // a full-screen Admin Panel would sit over the Home page
  poFollowupFullScreen_(false);   // …and so would a full-screen Follow-Up Report
  sarvApplyHomeTiles_();
  // The Nature picked on the way in belongs to that visit only — coming back
  // Home means picking again (or not going through the chooser at all).
  releaseHomeNatureLocks();
  sarvUnlockNav();
}
function sarvNavigateFromHome(target){
  const dash=byId('sarvHomeDashboard');if(dash)dash.style.display='none';
  // Once jumped into a section from Home, the top nav no longer offers
  // other panels — switching sections means going back to Home first.
  const fireChange=(id,val,lock)=>{const e=byId(id);if(!e)return;e.disabled=false;e.value=val;e.dispatchEvent(new Event('change'));if(lock)e.disabled=true;};
  switch(target){
    case 'IN': activatePanel('inwardPanel'); fireChange('entryTypeSelect','INWARD',true); break;
    case 'IN_NB': activatePanel('inwardPanel'); fireChange('entryTypeSelect','INWARD NB',true); break;
    case 'OUT': activatePanel('outwardPanel'); fireChange('outEntryTypeSelect','OUTWARD',true); break;
    case 'ISSUE': activatePanel('outwardPanel'); fireChange('outEntryTypeSelect','ISSUE',true); break;
    case 'PR':
      activatePanel('fullPurchasePanel');
      document.querySelector('#fullPurchasePanel .nav-link[data-tab="entry"]')?.click();
      // Home-jumped into New Entry only — the PO Generation tab link
      // stays hidden until they go back to Home and pick it explicitly.
      { const poTab=document.querySelector('#fullPurchasePanel .nav-link[data-tab="po"]'); if(poTab)poTab.style.display='none'; }
      break;
    case 'PO':
      activatePanel('fullPurchasePanel');
      document.querySelector('#fullPurchasePanel .nav-link[data-tab="po"]')?.click();
      { const entryTab=document.querySelector('#fullPurchasePanel .nav-link[data-tab="entry"]'); if(entryTab)entryTab.style.display='none'; }
      break;
    case 'MASTER': activatePanel('masterDataPanel'); break;
    case 'REPAIR': activatePanel('repairTrackerPanel'); break;
    case 'PRODUCTION': activatePanel('productionPanel'); break;
    case 'REPORTS': activatePanel('reportsPanel'); break;
    case 'TRACKER': activatePanel('itemTrackerPanel'); break;
    case 'APPROVAL_APP': window.open('mobile.html','_blank'); sarvGoHome(); return;
    /* Both companion apps open in their own tab and leave the ERP on Home —
       they are separate screens with their own login, not an ERP panel.
       Flat sibling of mobile.html: one repo, one directory, every link
       relative, so it serves unchanged from user.github.io/repo/ or a
       custom domain root. */
    case 'COMPLAINT_APP': window.open('complaint.html','_blank'); sarvGoHome(); return;
  }
  // Whatever the chooser answered on the way in is applied — and locked — only
  // now, after the Entry Type change handler has rebuilt the form's dropdowns.
  applyHomeNatureLocks();
  sarvLockNavToSection();
  // A sub-tab hidden for this role must not be the one the section opens on.
  sarvEnsureVisibleSubTabs_();
}
