const SARV_MASTER_SUB_KEY={itemMasterSub:'MD_ITEM',supplierMasterSub:'MD_SUPPLIER',employeeMasterSub:'MD_EMPLOYEE',machineMasterSub:'MD_MACHINE',settingsSub:'MD_SETTINGS'};
const SARV_PO_SUB_KEY={p_poSubPendingBtn:'PO_SUB_PENDING',p_poSubListBtn:'PO_SUB_LIST',p_poSubReportBtn:'PO_SUB_REPORT'};
const SARV_PROD_SUB_KEY={designMasterProdSub:'PROD_SUB_DESIGN'};
const SARV_NAV_TARGET_KEYS={inwardPanel:['HOME_IN','HOME_IN_NB'],outwardPanel:['HOME_OUT','HOME_ISSUE'],reportsPanel:['HOME_REPORTS'],
  itemTrackerPanel:['HOME_TRACKER'],fullPurchasePanel:['HOME_PR','HOME_PO'],masterDataPanel:['HOME_MASTER'],repairTrackerPanel:['HOME_REPAIR'],
  productionPanel:['HOME_PRODUCTION']};
const SARV_PURCHASER_FALLBACK=['KHUSHBOO','SATINDER JI','ANKUR JI','PARKASH JI','DEEPAK VERMA','PRIYA VERMA','FIELD BOY'];

let sarvSettings={role_permissions:null,tab_visibility:null};
let sarvSettingsMissing=false;
let sarvAppUsers=[],sarvAppUsersLoaded=false,sarvAppUsersMissing=false;

function sarvDefOf_(d,role){
  if(d.def==='ALL')return true;
  if(d.def==='W')return role!=='VIEW_PIN';
  return Array.isArray(d.def)&&d.def.includes(role);
}
function sarvMatrixVal_(matrix,defs,key,role){
  const d=defs.find(f=>f.key===key);if(!d)return true;
  if(d.lock&&d.lock.includes(role))return true;
  const m=matrix&&matrix[key];
  if(m&&typeof m[role]==='boolean')return m[role];
  return sarvDefOf_(d,role);
}
function sarvCanRole(role,key){return sarvMatrixVal_(sarvSettings.role_permissions,SARV_FEATURES,key,role);}
function sarvCan(key){return !!sarvCurrentRole&&sarvCanRole(sarvCurrentRole,key);}
function sarvTabVisible(key){
  if(!sarvCurrentRole)return true;
  return sarvMatrixVal_(sarvSettings.tab_visibility,SARV_TABS,key,sarvCurrentRole);
}
function sarvNavTargetVisible_(target){
  const ks=SARV_NAV_TARGET_KEYS[target];
  return !ks||ks.some(sarvTabVisible);
}
function sarvFeatureLabel_(key){const d=SARV_FEATURES.find(f=>f.key===key);return d?d.label:key;}
function sarvDeny(key){
  showToast('⛔ "'+sarvFeatureLabel_(key)+'" — '+(SARV_ROLE_LABEL[sarvCurrentRole]||'is role')+' ko access nahi hai. Admin se Settings › Admin Panel me access lein.','warn');
}
function sarvGuard(key){if(sarvCan(key))return true;sarvDeny(key);return false;}

/* Buttons that are simply hidden when the role lacks the feature, and every
   control that is refused on click. The click check runs in the capture phase,
   so it fires before the button's own handler and covers rows that are
   rendered later as well. */
const SARV_FEATURE_HIDE={
  ADD_ITEM:['[onclick^="openNewItemMasterModal"]'],
  DOWNLOAD_CSV:['[onclick^="exportTableCSV"]','#excelDownloadBtn'],
  ADD_EMPLOYEE:['#p_reqAddEmpBtn','[onclick^="addMasterEmployee"]'],
  ADD_MACHINE:['[onclick^="addMasterMachine"]'],
  EXPORT_CSV:['#itLeCsvBtn','#p_exportCsvBtn','#p_poRepCsvBtn','#pod_csv'],
  PDF_VIEW:['#itLePdfBtn'],
};
const SARV_CLICK_GUARDS=[
  ['#submitBtn','SUBMIT_INWARD'],
  ['#outSubmitBtn',()=>(byId('outEntryTypeSelect')?.value==='ISSUE'?'SUBMIT_ISSUE':'SUBMIT_OUTWARD')],
  ['#itLeRunBtn','ITEM_LEDGER'],
  ['#itLeCsvBtn,#p_exportCsvBtn,#p_poRepCsvBtn,#pod_csv','EXPORT_CSV'],
  ['a[data-doc="PR"]','PR_PDF'],
  ['#itLePdfBtn,#searchResultsBody a[href],#p_poListBody a[href],a.fu-doc[href],#itLeResults a.it-doc','PDF_VIEW'],
  ['[onclick^="exportTableCSV"],#excelDownloadBtn','DOWNLOAD_CSV'],
  ['[onclick^="openNewItemMasterModal"]','ADD_ITEM'],
  ['#p_reqAddEmpBtn,[onclick^="addMasterEmployee"]','ADD_EMPLOYEE'],
  ['[onclick^="addMasterMachine"]','ADD_MACHINE'],
  ['.sarv-po-cancel','PO_CANCEL'],
  ['.sarv-po-shortclose','PO_CLOSE'],
];
document.addEventListener('click',e=>{
  if(!sarvCurrentRole||!e.target||!e.target.closest)return;
  for(const [sel,k] of SARV_CLICK_GUARDS){
    const el=e.target.closest(sel);if(!el)continue;
    const key=typeof k==='function'?k(el):k;
    if(key&&!sarvCan(key)){e.preventDefault();e.stopImmediatePropagation();sarvDeny(key);}
    return;
  }
},true);
function sarvApplyPermCss_(){
  let st=byId('sarvPermStyle');
  if(!st){st=document.createElement('style');st.id='sarvPermStyle';document.head.appendChild(st);}
  const hide=[];
  if(sarvCurrentRole)Object.keys(SARV_FEATURE_HIDE).forEach(k=>{if(!sarvCan(k))hide.push(...SARV_FEATURE_HIDE[k]);});
  st.textContent=hide.length?hide.join(',')+'{display:none !important;}':'';
}
function sarvApplyHomeTiles_(){
  document.querySelectorAll('#sarvHomeDashboard .sarv-home-row[data-go]').forEach(b=>{
    b.style.display=sarvTabVisible('HOME_'+b.dataset.go)?'':'none';
  });
}
function sarvApplySubTabs_(){
  document.querySelectorAll('#masterDataPanel .master-sub-tab[data-subtab]').forEach(b=>{
    const k=SARV_MASTER_SUB_KEY[b.dataset.subtab];
    b.style.display=(!k||sarvTabVisible(k))?'':'none';
  });
  Object.keys(SARV_PO_SUB_KEY).forEach(id=>{
    const b=byId(id);if(b)b.style.display=sarvTabVisible(SARV_PO_SUB_KEY[id])?'':'none';
  });
  document.querySelectorAll('#productionPanel .prod-sub-tab[data-prodsub]').forEach(b=>{
    const k=SARV_PROD_SUB_KEY[b.dataset.prodsub];
    b.style.display=(!k||sarvTabVisible(k))?'':'none';
  });
  const ap=byId('sarvAdminPanel');if(ap)ap.style.display=isAdmin()?'':'none';
  // Item Master › New PR Generation — column + button follow Tab Visibility.
  byId('itemMasterTable')?.classList.toggle('im-hide-newpr',!sarvTabVisible('MD_ITEM_NEWPR'));
  if(typeof sarvSyncItemPrSelUi_==='function')sarvSyncItemPrSelUi_();
}
// The section just opened must not sit on a sub-tab this role cannot see.
function sarvEnsureVisibleSubTabs_(){
  sarvApplySubTabs_();
  const mp=byId('masterDataPanel');
  if(mp&&mp.style.display!=='none'){
    const cur=[...mp.querySelectorAll('[id$="Sub"]')].find(x=>x.style.display!=='none');
    const curBtn=cur&&mp.querySelector('.master-sub-tab[data-subtab="'+cur.id+'"]');
    if(!curBtn||curBtn.style.display==='none'){
      const first=[...mp.querySelectorAll('.master-sub-tab[data-subtab]')].find(b=>b.style.display!=='none');
      if(first)switchMasterSubTab(first.dataset.subtab);
    }
  }
  const panels={p_poSubPendingBtn:'p_poPendingPanel',p_poSubListBtn:'p_poListPanel',p_poSubReportBtn:'p_poReportPanel'};
  const shown=Object.keys(panels).find(b=>byId(panels[b])&&byId(panels[b]).style.display!=='none');
  if(shown&&byId(shown)&&byId(shown).style.display==='none'){
    const first=Object.keys(panels).find(b=>byId(b)&&byId(b).style.display!=='none');
    if(first)byId(first).click();
    else Object.values(panels).forEach(p=>{if(byId(p))byId(p).style.display='none';});
  }
}
function sarvApplyAccess(){
  sarvApplyPadPinMode_();
  sarvApplyPermCss_();
  sarvApplyHomeTiles_();
  sarvApplySubTabs_();
  if(byId('sarvHomeDashboard')?.style.display==='none')sarvEnsureVisibleSubTabs_();
}

/* ── Loading ────────────────────────────────────────────────────── */
async function sarvLoadSettings_(){
  if(!SB_READY)return;
  try{
    const q=await SB.from('app_settings').select('key,value').in('key',['role_permissions','tab_visibility']);
    if(q.error)throw q.error;
    sarvSettings={role_permissions:null,tab_visibility:null};
    (q.data||[]).forEach(r=>{sarvSettings[r.key]=r.value||null;});
    sarvSettingsMissing=false;
  }catch(e){
    sarvSettingsMissing=true;
    console.warn('[SARV] app_settings not loaded (ADMIN_PANEL_MIGRATION.sql run hua?):',e.message||e);
  }
  sarvApplyAccess();
}
async function sarvLoadAppUsers_(force){
  if(sarvAppUsersLoaded&&!force)return sarvAppUsers;
  if(!SB_READY)return sarvAppUsers;
  try{
    // signature is deliberately not selectable — only get_user_signature() returns it.
    const q=await SB.from('app_users').select('id,user_name,role,emp_code,contact_no,has_signature,is_active,created_at,updated_at').order('user_name');
    if(q.error)throw q.error;
    sarvAppUsers=q.data||[];sarvAppUsersMissing=false;
  }catch(e){
    sarvAppUsers=[];sarvAppUsersMissing=true;
    console.warn('[SARV] app_users not loaded (ADMIN_PANEL_MIGRATION.sql run hua?):',e.message||e);
  }
  sarvAppUsersLoaded=true;
  sarvRefreshPurchaserLists_();
  sarvApplyPadPinMode_();
  return sarvAppUsers;
}
// Purchasers come from Users & Roles; the old fixed names only until the migration has run.
function sarvPurchaserNames_(){
  const p=sarvAppUsers.filter(u=>u.role==='PURCHASER'&&u.is_active).map(u=>u.user_name);
  return p.length?p:SARV_PURCHASER_FALLBACK.slice();
}
function sarvRefreshPurchaserLists_(){
  const names=sarvPurchaserNames_();
  const sel=byId('p_reqGeneratedBy');
  if(sel){
    const keep=sel.value;
    const list=keep&&!names.includes(keep)?names.concat([keep]):names;
    sel.innerHTML='<option value="">-- Select Purchaser --</option>'+list.map(n=>'<option value="'+escText(n)+'">'+escText(n)+'</option>').join('');
    sel.value=keep;
  }
  const og=document.querySelector('#pwdChangeTarget optgroup');
  if(og)og.innerHTML=names.map(n=>'<option value="PURCHASER::'+escText(n)+'">Purchaser &mdash; '+escText(n)+'</option>').join('');
}

/* ── Admin Panel UI ─────────────────────────────────────────────── */
let sarvApPane='users';
let sarvApDraft={perms:null,tabs:null};
function sarvFullMatrix_(matrix,defs){
  const out={};
  defs.forEach(d=>{if(!d.key)return;out[d.key]={};SARV_PERM_ROLES.forEach(r=>{out[d.key][r.code]=sarvMatrixVal_(matrix,defs,d.key,r.code);});});
  return out;
}
function sarvRenderAdminPanel(){
  sarvApplySubTabs_();
  if(!isAdmin())return;
  const note=byId('ap_migrationNote');
  Promise.all([sarvLoadSettings_(),sarvLoadAppUsers_(true)]).then(()=>{
    if(note){
      const miss=sarvSettingsMissing||sarvAppUsersMissing;
      note.style.display=miss?'block':'none';
      note.innerHTML=miss?'&#9888;&#65039; Supabase me <code>ADMIN_PANEL_MIGRATION.sql</code> abhi run nahi hua hai &mdash; tab tak defaults chal rahe hain aur Save nahi hoga.':'';
    }
    if(!sarvApDraft.perms)sarvApDraft.perms=sarvFullMatrix_(sarvSettings.role_permissions,SARV_FEATURES);
    if(!sarvApDraft.tabs)sarvApDraft.tabs=sarvFullMatrix_(sarvSettings.tab_visibility,SARV_TABS);
    sarvRenderUsers_();
    sarvRenderMatrix_('ap_permMatrix',SARV_FEATURES,'perms');
    sarvRenderMatrix_('ap_tabMatrix',SARV_TABS,'tabs');
  });
}
// Admin Panel over the whole window (its own page scroll), or back in Settings.
function sarvApFullScreen_(on){
  const ap=byId('sarvAdminPanel');if(!ap)return;
  ap.classList.toggle('ap-full',!!on);
  const b=byId('ap_fullScreenBtn');
  if(b){b.innerHTML=on?'&#10005; Exit Full Screen':'&#9974; Full Screen';b.title=on?'Wapas Settings me (Esc)':'Admin Panel ko poori screen par kholein (Esc se wapas)';}
  if(on)ap.scrollTop=0;
}
function sarvShowApPane_(p){
  sarvApPane=p;
  document.querySelectorAll('#sarvAdminPanel .ap-tab').forEach(b=>b.classList.toggle('active',b.dataset.ap===p));
  document.querySelectorAll('#sarvAdminPanel .ap-pane').forEach(x=>x.style.display=x.dataset.apPane===p?'':'none');
}
function sarvRoleLabelOf_(code){const r=SARV_PERM_ROLES.find(x=>x.code===code);return r?r.label:(SARV_ROLE_LABEL[code]||code);}
function sarvRenderUsers_(){
  const tb=byId('ap_usersBody');if(!tb)return;
  const rf=byId('ap_userRoleFilter');
  if(rf&&rf.options.length<=1)rf.innerHTML='<option value="">All Roles</option>'+SARV_PERM_ROLES.map(r=>'<option value="'+r.code+'">'+escText(r.label)+'</option>').join('');
  if(sarvAppUsersMissing){tb.innerHTML='<tr><td colspan="9" class="ap-empty">app_users table nahi mili — ADMIN_PANEL_MIGRATION.sql run karein.</td></tr>';return;}
  const role=rf?.value||'',q=(byId('ap_userSearch')?.value||'').trim().toLowerCase();
  const order=SARV_PERM_ROLES.map(r=>r.code);
  const rows=sarvAppUsers.filter(u=>(!role||u.role===role)&&(!q||[u.user_name,u.emp_code,u.contact_no,sarvRoleLabelOf_(u.role)].join(' ').toLowerCase().includes(q)))
    .sort((a,b)=>order.indexOf(a.role)-order.indexOf(b.role)||String(a.user_name).localeCompare(String(b.user_name)));
  if(!rows.length){tb.innerHTML='<tr><td colspan="9" class="ap-empty">Koi user nahi — ➕ Add User se banayein.</td></tr>';return;}
  tb.innerHTML=rows.map((u,i)=>'<tr>'
    +'<td style="color:#94a3b8;">'+(i+1)+'</td>'
    +'<td style="font-weight:800;">'+escText(u.user_name)+'</td>'
    +'<td><span class="ap-pill" style="background:#e0f2fe;color:#0369a1;">'+escText(sarvRoleLabelOf_(u.role))+'</span></td>'
    +'<td>'+escText(u.emp_code||'—')+'</td>'
    +'<td>'+escText(u.contact_no||'—')+'</td>'
    +'<td style="text-align:center;">'+(u.has_signature?'<span style="color:#15803d;font-weight:800;" title="Signature saved — PIN se sign kar sakte hain">&#9997;&#65039; &#10004;</span>':'<span style="color:#b45309;font-weight:700;" title="Signature abhi nahi bana">&mdash;</span>')+'</td>'
    +'<td style="text-align:center;"><span class="ap-pill" style="background:'+(u.is_active?'#dcfce7':'#fee2e2')+';color:'+(u.is_active?'#166534':'#dc2626')+';">'+(u.is_active?'Active':'Inactive')+'</span></td>'
    +'<td style="text-align:center;"><button type="button" class="ap-ibtn" data-ap-edit="'+escText(u.id)+'" style="background:#eff6ff;border:1px solid #93c5fd;color:#1d4ed8;">&#9999;&#65039;</button></td>'
    +'<td style="text-align:center;"><button type="button" class="ap-ibtn" data-ap-del="'+escText(u.id)+'" style="background:#fef2f2;border:1px solid #fca5a5;color:#dc2626;">&#10005;</button></td>'
    +'</tr>').join('');
}
function sarvRenderMatrix_(tableId,defs,which){
  const t=byId(tableId);if(!t)return;
  const m=sarvApDraft[which]||{};
  const saved=which==='perms'?sarvFullMatrix_(sarvSettings.role_permissions,SARV_FEATURES):sarvFullMatrix_(sarvSettings.tab_visibility,SARV_TABS);
  let h='<thead><tr><th>'+(which==='perms'?'FEATURES':'TABS / SUB TABS')+'</th>'
    +SARV_PERM_ROLES.map(r=>'<th data-ap-col="'+r.code+'" title="Click — poora column YES / NO">'+escText(r.label)+'</th>').join('')+'</tr></thead><tbody>';
  defs.forEach(d=>{
    if(d.group){h+='<tr class="ap-group"><td colspan="'+(SARV_PERM_ROLES.length+1)+'">'+escText(d.group)+'</td></tr>';return;}
    const dirty=SARV_PERM_ROLES.some(r=>!!(m[d.key]||{})[r.code]!==!!(saved[d.key]||{})[r.code]);
    h+='<tr data-ap-key="'+d.key+'"'+(dirty?' class="ap-dirty"':'')+'><th data-ap-row="'+d.key+'" title="Click — poori row YES / NO">'+escText(d.label)+(d.hint?'<small>'+escText(d.hint)+'</small>':'')+'</th>';
    SARV_PERM_ROLES.forEach(r=>{
      const locked=!!(d.lock&&d.lock.includes(r.code));
      const on=locked||!!(m[d.key]||{})[r.code];
      h+='<td class="ap-cell'+(on?' yes':'')+(locked?' locked':'')+'"><label title="'+escText(r.label+' — '+d.label)+(locked?' (hamesha YES)':'')+'">'
        +'<input type="checkbox" data-ap-k="'+d.key+'" data-ap-r="'+r.code+'"'+(on?' checked':'')+(locked?' disabled':'')+'></label></td>';
    });
    h+='</tr>';
  });
  t.innerHTML=h+'</tbody>';
  t.dataset.which=which;
}
function sarvMatrixClick_(e){
  const t=e.currentTarget,which=t.dataset.which,defs=which==='perms'?SARV_FEATURES:SARV_TABS,m=sarvApDraft[which];
  if(!m)return;
  const lockedFor=(k,r)=>{const d=defs.find(x=>x.key===k);return !!(d&&d.lock&&d.lock.includes(r));};
  const cb=e.target.closest('input[data-ap-k]');
  if(cb){m[cb.dataset.apK][cb.dataset.apR]=cb.checked;sarvRenderMatrix_(t.id,defs,which);return;}
  const col=e.target.closest('th[data-ap-col]');
  if(col){
    const r=col.dataset.apCol,keys=defs.filter(d=>d.key&&!lockedFor(d.key,r)).map(d=>d.key);
    const allOn=keys.every(k=>m[k][r]);keys.forEach(k=>m[k][r]=!allOn);
    sarvRenderMatrix_(t.id,defs,which);return;
  }
  const row=e.target.closest('th[data-ap-row]');
  if(row){
    const k=row.dataset.apRow,roles=SARV_PERM_ROLES.map(r=>r.code).filter(r=>!lockedFor(k,r));
    const allOn=roles.every(r=>m[k][r]);roles.forEach(r=>m[k][r]=!allOn);
    sarvRenderMatrix_(t.id,defs,which);
  }
}
async function sarvSaveMatrix_(which){
  if(!isAdmin())return showToast('⛔ Sirf Admin login','warn');
  const key=which==='perms'?'role_permissions':'tab_visibility';
  const adminPin=await askSecret({title:'Admin PIN Confirm Karein',subtitle:(which==='perms'?'Feature Access':'Tab Visibility')+' save karne ke liye',
    recordInfo:'Sabhi roles par turant lagu hoga (mobile app me bhi)',label:'Admin PIN',confirmText:'&#128190; Save'});
  if(adminPin==null)return;
  if(!adminPin.trim())return showToast('Admin PIN khali nahi ho sakta','warn');
  try{
    const r=await SB.rpc('admin_save_setting',{p_key:key,p_value:sarvApDraft[which],p_admin_pin:adminPin.trim()});
    if(r.error)throw r.error;
    if(!r.data)return showToast('❌ Admin PIN galat hai — save nahi hua','error');
    sarvSettings[key]=JSON.parse(JSON.stringify(sarvApDraft[which]));
    sarvApplyAccess();
    sarvRenderMatrix_(which==='perms'?'ap_permMatrix':'ap_tabMatrix',which==='perms'?SARV_FEATURES:SARV_TABS,which);
    showToast('✅ '+(which==='perms'?'Feature Access':'Tab Visibility')+' save ho gaya');
  }catch(e){
    if(/admin_save_setting|does not exist/i.test(e.message||''))showToast('⚠️ ADMIN_PANEL_MIGRATION.sql pehle run karein','warn');
    else dbError(e);
  }
}

/* ── Signature pad (shared by the user popup) ───────────────────── */
function sarvMakeSigPad_(canvas){
  const ctx=canvas.getContext('2d');
  ctx.strokeStyle='#0f172a';ctx.lineWidth=2.4;ctx.lineCap='round';ctx.lineJoin='round';
  let down=false,ink=0,lx=0,ly=0;
  const pos=e=>{const r=canvas.getBoundingClientRect(),s=e.touches?e.touches[0]:e;return{x:(s.clientX-r.left)*canvas.width/r.width,y:(s.clientY-r.top)*canvas.height/r.height};};
  const start=e=>{e.preventDefault();down=true;const p=pos(e);lx=p.x;ly=p.y;ctx.beginPath();ctx.moveTo(p.x,p.y);};
  const move=e=>{e.preventDefault();if(!down)return;const p=pos(e);ctx.lineTo(p.x,p.y);ctx.stroke();ink+=Math.hypot(p.x-lx,p.y-ly);lx=p.x;ly=p.y;};
  const stop=()=>{down=false;};
  canvas.addEventListener('mousedown',start);canvas.addEventListener('mousemove',move);
  canvas.addEventListener('mouseup',stop);canvas.addEventListener('mouseleave',stop);
  canvas.addEventListener('touchstart',start,{passive:false});canvas.addEventListener('touchmove',move,{passive:false});
  canvas.addEventListener('touchend',stop);
  return{
    clear(){ctx.clearRect(0,0,canvas.width,canvas.height);ink=0;},
    hasInk(){return ink>=30;},
    dataUrl(){return canvas.toDataURL('image/png');}
  };
}
// Draws a saved signature into any pad, scaled to fit and centred.
function sarvDrawSigInto_(canvas,dataUrl){
  return new Promise((res,rej)=>{
    const img=new Image();
    img.onload=()=>{
      const cx=canvas.getContext('2d');
      cx.clearRect(0,0,canvas.width,canvas.height);
      const s=Math.min(canvas.width/img.width,canvas.height/img.height);
      const w=img.width*s,h=img.height*s;
      cx.drawImage(img,(canvas.width-w)/2,(canvas.height-h)/2,w,h);
      res();
    };
    img.onerror=()=>rej(new Error('Signature image load nahi hui'));
    img.src=dataUrl;
  });
}

/* ── User add / edit popup ──────────────────────────────────────── */
function sarvOpenUserModal(id,presetRole){
  if(!isAdmin())return showToast('⛔ Sirf Admin login users bana sakta hai','warn');
  if(sarvAppUsersMissing)return showToast('⚠️ ADMIN_PANEL_MIGRATION.sql pehle run karein','warn');
  const u=id?sarvAppUsers.find(x=>x.id===id):null;
  const role=u?u.role:(presetRole||'');
  const ov=document.createElement('div');
  ov.className='sarv-ov';ov.id='sarvUserModal';
  ov.innerHTML='<div class="card"><div class="hd">'+(u?'&#9999;&#65039; Update User — '+escText(u.user_name):(presetRole==='PURCHASER'?'&#10133; Add New Purchaser':'&#10133; Add User'))+'</div><div class="bd">'
    +'<div class="err" data-f="err"></div>'
    +'<div class="g2">'
    +'<div class="fg"><label>Role <span class="req">*</span></label><select data-f="role"><option value="">-- Select Role --</option>'
      +SARV_PERM_ROLES.map(r=>'<option value="'+r.code+'"'+(r.code===role?' selected':'')+'>'+escText(r.label)+'</option>').join('')+'</select></div>'
    +'<div class="fg"><label>User Name <span class="req">*</span></label><input data-f="name" style="text-transform:uppercase;" autocomplete="off" value="'+escText(u?u.user_name:'')+'" placeholder="Full name"></div>'
    +'<div class="fg"><label>Employee Code</label><input data-f="emp" list="dl-emp-codes" style="text-transform:uppercase;" autocomplete="off" value="'+escText(u?u.emp_code||'':'')+'" placeholder="optional — auto-fill"></div>'
    +'<div class="fg"><label>Contact No.</label><input data-f="contact" type="tel" maxlength="15" value="'+escText(u?u.contact_no||'':'')+'" placeholder="optional"></div>'
    +'<div class="fg"><label>'+(u?'New PIN <small style="text-transform:none;font-weight:600;">(khali = purana PIN)</small>':'PIN <span class="req">*</span>')+'</label><input data-f="pin" type="password" inputmode="numeric" autocomplete="new-password" placeholder="4+ digits"></div>'
    +'<div class="fg"><label>Confirm PIN</label><input data-f="pin2" type="password" inputmode="numeric" autocomplete="new-password" placeholder="dobara"></div>'
    +'</div>'
    +'<div class="fg" style="display:flex;align-items:center;gap:8px;"><input data-f="active" type="checkbox" style="width:16px;height:16px;"'+(!u||u.is_active?' checked':'')+'><span style="font-size:12px;font-weight:700;color:#334155;">Active (login + PIN se sign kar sakta hai)</span></div>'
    +'<div class="fg"><label>&#9997;&#65039; Digital Signature '+(u&&u.has_signature?'<span style="color:#15803d;text-transform:none;">— saved &#10004; (naya banayein to replace hoga)</span>':'<span style="color:#b45309;text-transform:none;">— user yahan ek baar sign kare</span>')+'</label>'
    +'<div class="pad"><canvas width="900" height="220"></canvas><div class="padbar"><span>Mouse / touch / stylus se sign karein</span>'
    +'<span style="display:flex;gap:8px;align-items:center;">'
    +(u&&u.has_signature?'<label style="display:flex;align-items:center;gap:4px;margin:0;text-transform:none;font-size:11px;color:#b91c1c;font-weight:700;"><input data-f="sigdel" type="checkbox" style="width:14px;height:14px;"> Saved sign hatayein</label>':'')
    +'<button type="button" class="b no sm" data-f="sigclr">&#10006; Clear</button></span></div></div></div>'
    +'</div><div class="ft"><button type="button" class="b no" data-f="cancel">Cancel</button><button type="button" class="b ok" data-f="save">&#128190; Save User</button></div></div>';
  document.body.appendChild(ov);
  const f=k=>ov.querySelector('[data-f="'+k+'"]');
  const pad=sarvMakeSigPad_(ov.querySelector('canvas'));
  const close=()=>{document.removeEventListener('keydown',onKey,true);ov.remove();};
  // Esc inside the Admin PIN prompt belongs to that prompt, not to this form.
  const onKey=e=>{if(e.key==='Escape'&&byId('pwdGateModal')?.style.display!=='flex'){e.preventDefault();close();}};
  document.addEventListener('keydown',onKey,true);
  const err=msg=>{const el=f('err');el.textContent=msg;el.style.display=msg?'block':'none';if(msg)ov.querySelector('.card').scrollTop=0;};
  f('sigclr').addEventListener('click',()=>pad.clear());
  f('cancel').addEventListener('click',close);
  // Employee Code fills the name / contact from Employee Master.
  f('emp').addEventListener('input',()=>{
    const e=lookupEmployee(f('emp').value);if(!e)return;
    if(!f('name').value.trim())f('name').value=e.person_name||'';
    if(!f('contact').value.trim())f('contact').value=e.contact_no||'';
  });
  f('save').addEventListener('click',async()=>{
    err('');
    const roleV=f('role').value,name=f('name').value.trim().toUpperCase(),pin=f('pin').value,pin2=f('pin2').value;
    if(!roleV)return err('Role select karein');
    if(!name)return err('User Name zaroori hai');
    const dup=sarvAppUsers.find(x=>x.role===roleV&&String(x.user_name).toUpperCase()===name&&x.id!==(u&&u.id));
    if(dup)return err('Is role me "'+name+'" pehle se hai');
    if(!u&&!pin&&roleV!=='PURCHASER')return err('PIN zaroori hai');
    if(pin&&pin.length<4)return err('PIN kam se kam 4 digit ka ho');
    if(pin!==pin2)return err('PIN aur Confirm PIN match nahi kar rahe');
    let sig=null;
    if(pad.hasInk())sig=pad.dataUrl();
    else if(f('sigdel')&&f('sigdel').checked)sig='';
    const adminPin=await askSecret({title:'Admin PIN Confirm Karein',subtitle:(u?'User update':'Naya user')+' save karne ke liye',
      recordInfo:sarvRoleLabelOf_(roleV)+' — '+name,label:'Admin PIN',confirmText:'&#128190; Save User'});
    if(adminPin==null)return;
    if(!adminPin.trim())return err('Admin PIN khali nahi ho sakta');
    const btn=f('save');btn.disabled=true;btn.textContent='⏳ Saving...';
    try{
      const r=await SB.rpc('admin_save_user',{p_id:u?u.id:null,p_user_name:name,p_role:roleV,
        p_emp_code:f('emp').value.trim().toUpperCase()||null,p_contact_no:f('contact').value.trim()||null,
        p_is_active:f('active').checked,p_new_pin:pin||null,p_signature:sig,p_admin_pin:adminPin.trim()});
      if(r.error)throw r.error;
      await sarvLoadAppUsers_(true);
      sarvRenderUsers_();
      close();
      showToast('✅ '+name+' ('+sarvRoleLabelOf_(roleV)+') '+(u?'update':'add')+' ho gaya'+(roleV==='PURCHASER'?' — PR form aur mobile login me ab dikhega':''));
    }catch(e){
      const m=String(e.message||e);
      const map={ADMIN_PIN_INVALID:'❌ Admin PIN galat hai',PIN_REQUIRED:'Is user ka PIN abhi set nahi hai — PIN daalein',PIN_TOO_SHORT:'PIN kam se kam 4 digit ka ho',
        USER_EXISTS:'Is role me ye naam pehle se hai',ROLE_INVALID:'Role galat hai',NAME_ROLE_REQUIRED:'Role aur naam zaroori hain',USER_NOT_FOUND:'User nahi mila — Refresh karein'};
      const k=Object.keys(map).find(x=>m.includes(x));
      err(k?map[k]:(/admin_save_user|does not exist/i.test(m)?'⚠️ ADMIN_PANEL_MIGRATION.sql pehle run karein':m));
    }finally{btn.disabled=false;btn.innerHTML='&#128190; Save User';}
  });
  setTimeout(()=>(role?f('name'):f('role')).focus(),30);
}
async function sarvDeleteUser_(id){
  const u=sarvAppUsers.find(x=>x.id===id);if(!u)return;
  if(!confirm('"'+u.user_name+'" ('+sarvRoleLabelOf_(u.role)+') ko delete karein?\n\nUska PIN aur saved signature bhi hat jayega.'+(u.role==='PURCHASER'?'\nPurchaser mobile app me login nahi kar payega.':'')+'\n\n(Sirf rokna ho to Edit karke "Active" hata dein.)'))return;
  const adminPin=await askSecret({title:'Admin PIN Confirm Karein',subtitle:'User delete karne ke liye',recordInfo:u.user_name,label:'Admin PIN',confirmText:'&#128465; Delete'});
  if(adminPin==null)return;
  try{
    const r=await SB.rpc('admin_delete_user',{p_id:id,p_admin_pin:adminPin.trim()});
    if(r.error)throw r.error;
    if(!r.data)return showToast('❌ Admin PIN galat hai — delete nahi hua','error');
    await sarvLoadAppUsers_(true);sarvRenderUsers_();
    showToast('🗑️ '+u.user_name+' delete ho gaya');
  }catch(e){dbError(e);}
}

/* ── Sign with PIN ──────────────────────────────────────────────────
   The signature a user drew once (Users & Roles) is put on a pad by typing
   their PIN — get_user_signature() returns it only for the right PIN.
   Resolves {dataUrl,name} or null when cancelled. */
async function sarvPinSign(opts={}){
  await sarvLoadAppUsers_();
  if(sarvAppUsersMissing){if(!opts.quiet)showToast('⚠️ ADMIN_PANEL_MIGRATION.sql pehle run karein','warn');return null;}
  let users=sarvAppUsers.filter(u=>u.is_active&&u.has_signature);
  if(opts.roles&&opts.roles.length){const f=users.filter(u=>opts.roles.includes(u.role));if(f.length||opts.strictRoles)users=f;}
  if(!users.length){if(!opts.quiet)showToast('Kisi user ka signature saved nahi hai — Admin Panel › Users & Roles me sign banwayein','warn');return null;}
  const pre=(sarvCurrentUser&&users.find(u=>u.id===sarvCurrentUser.id))?sarvCurrentUser.id:(users.length===1?users[0].id:'');
  return new Promise(resolve=>{
    const ov=document.createElement('div');
    ov.className='sarv-ov';
    ov.innerHTML='<div class="card" style="max-width:400px;"><div class="hd">&#128273; PIN se Sign — '+escText(opts.title||'Digital Signature')+'</div><div class="bd">'
      +'<div class="err" data-f="err"></div>'
      +'<div class="fg"><label>User</label><select data-f="user"><option value="">-- Select --</option>'
      +users.map(u=>'<option value="'+escText(u.id)+'"'+(u.id===pre?' selected':'')+'>'+escText(u.user_name)+' ('+escText(sarvRoleLabelOf_(u.role))+')</option>').join('')+'</select></div>'
      +'<div class="fg"><label>Apna PIN</label><input data-f="pin" type="password" inputmode="numeric" autocomplete="off" placeholder="Enter PIN"></div>'
      +'<div style="font-size:11px;color:#64748b;">'+escText(opts.note||'Sahi PIN par aapka saved signature pad par lag jayega.')+'</div>'
      +'</div><div class="ft"><button type="button" class="b no" data-f="cancel">Cancel</button><button type="button" class="b ok" data-f="ok">&#9997;&#65039; Sign</button></div></div>';
    document.body.appendChild(ov);
    const f=k=>ov.querySelector('[data-f="'+k+'"]');
    const done=v=>{document.removeEventListener('keydown',onKey,true);ov.remove();resolve(v);};
    const submit=async()=>{
      const id=f('user').value,pin=f('pin').value,er=f('err');
      er.style.display='none';
      if(!id){er.textContent='User select karein';er.style.display='block';return;}
      if(!pin){er.textContent='PIN daalein';er.style.display='block';return;}
      f('ok').disabled=true;
      try{
        const r=await SB.rpc('get_user_signature',{p_user_id:id,p_pin:pin});
        if(r.error)throw r.error;
        if(!r.data){er.textContent='❌ Galat PIN';er.style.display='block';f('pin').select();return;}
        done({dataUrl:r.data,name:(users.find(u=>u.id===id)||{}).user_name||''});
      }catch(e){er.textContent=e.message||String(e);er.style.display='block';}
      finally{if(f('ok'))f('ok').disabled=false;}
    };
    const onKey=e=>{if(e.key==='Escape'){e.preventDefault();done(null);}else if(e.key==='Enter'){e.preventDefault();submit();}};
    document.addEventListener('keydown',onKey,true);
    f('cancel').addEventListener('click',()=>done(null));
    f('ok').addEventListener('click',submit);
    setTimeout(()=>(pre?f('pin'):f('user')).focus(),30);
  });
}
/* A "🔑 PIN se Sign" button beside the Clear button of each signature pad. */
function sarvAttachPinSign_(clearBtnId,canvasId,timeFieldId,title,roles,canUse){
  const clr=byId(clearBtnId);if(!clr||clr.dataset.pinSign)return;
  clr.dataset.pinSign='1';
  const b=document.createElement('button');
  b.type='button';b.className='sarv-pinsign-btn';b.innerHTML='&#128273; PIN se Sign';
  b.title='Draw karne ki jagah apna PIN daalein — saved signature lag jayega';
  b.style.marginRight='6px';
  clr.parentNode.insertBefore(b,clr);
  b.addEventListener('click',async()=>{
    const c=byId(canvasId);if(!c)return;
    if(canUse&&!canUse(c))return;
    const r=await sarvPinSign({title,roles});if(!r)return;
    try{
      await sarvDrawSigInto_(c,r.dataUrl);
      const tf=byId(timeFieldId);if(tf)tf.textContent=pStamp()+' — '+r.name;
      showToast('✍️ '+r.name+' ka signature lag gaya');
    }catch(e){showToast(e.message||String(e),'error');}
  });
}

/* ── PIN-only pads ───────────────────────────────────────────────────
   Once the logged-in user's sign is saved, the Store In-Charge draw pads
   (Build PO, Vendor Rate & Info) are not shown at all: the confirm button asks
   their PIN and lays the saved sign onto the (hidden) canvas, then carries on
   exactly as if it had been drawn. A user with no saved sign — or whose PIN
   brings none back — gets the pad as before. */
const SARV_PIN_PADS=[
  {canvas:'p_poStoreSignCanvas',time:'p_poStoreSignTimeField',confirm:'p_poBuildConfirmBtn',title:'Generate PO'},
  {canvas:'p_viSignCanvas',time:'p_viSignTimeField',confirm:'p_viSaveBtn',title:'Save Vendor Info',can:()=>sarvCan('VENDOR_INFO_DESK')}
];
let sarvPadForceDraw=false;   // set when a PIN brought back no sign — show the pad again
function sarvPadPinMode_(){
  const id=sarvCurrentUser&&sarvCurrentUser.id;
  return !sarvPadForceDraw&&!!(id&&sarvAppUsers.some(u=>u.id===id&&u.is_active&&u.has_signature));
}
function sarvApplyPadPinMode_(){
  const on=sarvPadPinMode_();
  SARV_PIN_PADS.forEach(p=>{
    const c=byId(p.canvas);if(!c||!c.parentElement)return;
    const pad=c.parentElement;
    pad.style.display=on?'none':'';
    let note=byId(p.canvas+'_pinNote');
    if(!note){
      note=document.createElement('div');
      note.id=p.canvas+'_pinNote';
      note.style.cssText='padding:10px 12px;border:1px solid #c4b5fd;background:#f5f3ff;border-radius:6px;font-size:12px;font-weight:700;color:#5b21b6;';
      note.innerHTML='&#128273; Aapka sign saved hai &mdash; <b>'+escText(p.title)+'</b> dabate hi apna PIN daalein, sign apne-aap lag jayega.';
      pad.parentNode.insertBefore(note,pad.nextSibling);
    }
    note.style.display=on?'':'none';
  });
}
function sarvBindPinPads_(){
  SARV_PIN_PADS.forEach(p=>{
    // Document capture: runs before the button's own handler in every browser;
    // that handler only sees the click again (pinPass) once the saved sign is
    // on the canvas.
    document.addEventListener('click',async e=>{
      const b=e.target&&e.target.closest&&e.target.closest('#'+p.confirm);
      if(!b||b.disabled)return;
      if(b.dataset.pinPass==='1'){delete b.dataset.pinPass;return;}
      if(!sarvPadPinMode_()||(p.can&&!p.can()))return;
      e.preventDefault();e.stopImmediatePropagation();
      const r=await sarvSubmitPinGate_(p.title);
      if(!r)return;
      const c=byId(p.canvas);
      if(!r.dataUrl||!c){
        sarvPadForceDraw=true;sarvApplyPadPinMode_();
        return showToast('Is user ka saved sign nahi mila — pad par sign karke dobara dabayein','warn');
      }
      try{await sarvDrawSigInto_(c,r.dataUrl);}
      catch(err){sarvPadForceDraw=true;sarvApplyPadPinMode_();return showToast('Saved sign load nahi hua — pad par sign karein','warn');}
      const tf=byId(p.time);if(tf)tf.textContent=pStamp()+' — '+r.name;
      b.dataset.pinPass='1';
      b.click();
    },true);
  });
}

document.addEventListener('DOMContentLoaded',()=>{
  sarvBindPinPads_();
  // Admin Panel controls
  document.querySelectorAll('#sarvAdminPanel .ap-tab').forEach(b=>b.addEventListener('click',()=>sarvShowApPane_(b.dataset.ap)));
  byId('ap_fullScreenBtn')?.addEventListener('click',()=>sarvApFullScreen_(!byId('sarvAdminPanel')?.classList.contains('ap-full')));
  // Esc leaves full screen — unless a popup on top of it (user form, PIN) owns the key.
  document.addEventListener('keydown',e=>{
    if(e.key!=='Escape'||!byId('sarvAdminPanel')?.classList.contains('ap-full'))return;
    if(document.querySelector('.sarv-ov')||byId('pwdGateModal')?.style.display==='flex')return;
    sarvApFullScreen_(false);
  });
  byId('ap_addUserBtn')?.addEventListener('click',()=>sarvOpenUserModal(null));
  byId('ap_addPurchaserBtn')?.addEventListener('click',()=>sarvOpenUserModal(null,'PURCHASER'));
  byId('ap_reloadUsersBtn')?.addEventListener('click',()=>sarvLoadAppUsers_(true).then(sarvRenderUsers_));
  byId('ap_userRoleFilter')?.addEventListener('change',sarvRenderUsers_);
  byId('ap_userSearch')?.addEventListener('input',sarvRenderUsers_);
  byId('ap_usersBody')?.addEventListener('click',e=>{
    const ed=e.target.closest('[data-ap-edit]');if(ed)return sarvOpenUserModal(ed.dataset.apEdit);
    const dl=e.target.closest('[data-ap-del]');if(dl)sarvDeleteUser_(dl.dataset.apDel);
  });
  ['ap_permMatrix','ap_tabMatrix'].forEach(id=>byId(id)?.addEventListener('click',sarvMatrixClick_));
  byId('ap_permSaveBtn')?.addEventListener('click',()=>sarvSaveMatrix_('perms'));
  byId('ap_tabSaveBtn')?.addEventListener('click',()=>sarvSaveMatrix_('tabs'));
  byId('ap_permResetBtn')?.addEventListener('click',()=>{sarvApDraft.perms=sarvFullMatrix_(null,SARV_FEATURES);sarvRenderMatrix_('ap_permMatrix',SARV_FEATURES,'perms');showToast('Default lag gaye — Save dabane par lagu honge');});
  byId('ap_tabResetBtn')?.addEventListener('click',()=>{sarvApDraft.tabs=sarvFullMatrix_(null,SARV_TABS);sarvRenderMatrix_('ap_tabMatrix',SARV_TABS,'tabs');showToast('Default lag gaye — Save dabane par lagu honge');});
  // PIN-sign on the two Store Incharge pads
  sarvAttachPinSign_('p_poStoreSignClearBtn','p_poStoreSignCanvas','p_poStoreSignTimeField','Store Incharge (PO)',['USER_IC_PIN','ADMIN_PIN']);
  sarvAttachPinSign_('p_viSignClearBtn','p_viSignCanvas','p_viSignTimeField','Store Incharge (Vendor Info)',['USER_IC_PIN','ADMIN_PIN'],
    c=>{if(c.style.pointerEvents==='none'){sarvDeny('VENDOR_INFO_DESK');return false;}return true;});
  sarvApplyAccess();
  sarvLoadSettings_();
  sarvLoadAppUsers_();
});

/* ================================================================
   SIGNATURE CANVAS ENGINE
================================================================ */
(function initSignatureEngine(){
  let drawing=false, ctx=null, canvas=null;
  function getCanvas(){ return canvas||(canvas=byId('signatureCanvas')); }
  function getCtx(){
    if(ctx) return ctx;
    const c=getCanvas(); if(!c) return null;
    ctx=c.getContext('2d');
    ctx.strokeStyle='#0f172a'; ctx.lineWidth=2.2;
    ctx.lineCap='round'; ctx.lineJoin='round';
    return ctx;
  }
  function pos(e,c){
    const r=c.getBoundingClientRect();
    const src=e.touches?e.touches[0]:e;
    return {x:src.clientX-r.left, y:src.clientY-r.top};
  }
  function onDown(e){
    e.preventDefault(); drawing=true;
    const c=getCanvas(); const cx=getCtx(); if(!c||!cx) return;
    const p=pos(e,c); cx.beginPath(); cx.moveTo(p.x,p.y);
  }
  function onMove(e){
    e.preventDefault(); if(!drawing) return;
    const c=getCanvas(); const cx=getCtx(); if(!c||!cx) return;
    const p=pos(e,c); cx.lineTo(p.x,p.y); cx.stroke();
  }
  function onUp(e){ drawing=false; }
  function bindCanvas(){
    const c=getCanvas(); if(!c||c.dataset.sigBound) return;
    c.addEventListener('mousedown',onDown); c.addEventListener('mousemove',onMove);
    c.addEventListener('mouseup',onUp); c.addEventListener('mouseleave',onUp);
    c.addEventListener('touchstart',onDown,{passive:false});
    c.addEventListener('touchmove',onMove,{passive:false});
    c.addEventListener('touchend',onUp);
    c.dataset.sigBound='1';
  }
  // Override stubs
  window.clearCanvas=function(){
    const c=getCanvas(); if(!c) return;
    bindCanvas();
    getCtx()?.clearRect(0,0,c.width,c.height);
  };
  window.getSignatureDataUrl=function(){
    const c=getCanvas(); if(!c) return '';
    return c.toDataURL('image/png');
  };
  window.isSignatureEmpty=function(){
    const c=getCanvas(); if(!c) return true;
    const data=c.getContext('2d').getImageData(0,0,c.width,c.height).data;
    return !data.some(v=>v!==0);
  };
  // Bind when modal opens
  const mo=new MutationObserver(()=>{ const c=getCanvas(); if(c) bindCanvas(); });
  document.addEventListener('DOMContentLoaded',()=>{
    const modal=byId('drawSignatureModal');
    if(modal) mo.observe(modal,{attributes:true,attributeFilter:['style']});
    const clrBtn=byId('clearCanvasBtn');
    if(clrBtn&&!clrBtn.dataset.sigBound){ clrBtn.addEventListener('click',window.clearCanvas); clrBtn.dataset.sigBound='1'; }
    bindCanvas();
  });
})();

/* ================================================================
   PHOTO PREVIEW ENGINE (Inward + Outward)
================================================================ */
(function initPhotoEngine(){
  const stores={inward:{camera:'inwPhotoCameraInput',gallery:'inwPhotoGalleryInput',preview:'inwPhotoPreview',count:'inwPhotoCount',files:[]},outward:{camera:'outPhotoCameraInput',gallery:'outPhotoGalleryInput',preview:'outPhotoPreview',count:'outPhotoCount',files:[]}};

  function renderPreviews(key){
    const s=stores[key];
    const box=byId(s.preview); const cnt=byId(s.count);
    if(!box) return;
    box.innerHTML=s.files.map((f,i)=>`
      <div style="position:relative;width:80px;height:80px;border-radius:6px;overflow:hidden;border:1.5px solid #cbd5e1;flex-shrink:0;">
        <img src="${f.dataUrl}" style="width:100%;height:100%;object-fit:cover;">
        <button onclick="removePhotoAt('${key}',${i})" style="position:absolute;top:2px;right:2px;background:rgba(0,0,0,0.6);color:#fff;border:none;border-radius:50%;width:18px;height:18px;font-size:10px;cursor:pointer;line-height:18px;text-align:center;padding:0;">✕</button>
        <div style="position:absolute;bottom:0;left:0;right:0;background:rgba(0,0,0,0.5);color:#fff;font-size:8px;padding:2px 4px;overflow:hidden;white-space:nowrap;text-overflow:ellipsis;">${f.name}</div>
      </div>`).join('');
    if(cnt) cnt.textContent=s.files.length?s.files.length+' photo'+(s.files.length>1?'s':''):'' ;
  }

  function addFiles(key, fileList){
    const s=stores[key];
    const newFiles=[...fileList].filter(f=>f.type.startsWith('image/'));
    const readers=newFiles.map(f=>new Promise(res=>{
      const r=new FileReader();
      r.onload=()=>res({name:f.name,type:f.type,dataUrl:r.result,file:f});
      r.onerror=()=>res(null);
      r.readAsDataURL(f);
    }));
    Promise.all(readers).then(results=>{
      s.files=[...s.files,...results.filter(Boolean)];
      renderPreviews(key);
    });
  }

  window.removePhotoAt=function(key,idx){
    if(!stores[key]) return;
    stores[key].files.splice(idx,1);
    renderPreviews(key);
  };

  window.getPhotos=function(key){ return stores[key]?.files||[]; };
  // Entry Type drafts (makeEntryDrafts_): hand the current photos over to a
  // draft and empty the preview, then give a draft's photos back.
  window.takePhotos=function(key){
    if(!stores[key])return [];
    const files=stores[key].files;stores[key].files=[];renderPreviews(key);return files;
  };
  window.putPhotos=function(key,files){
    if(!stores[key])return;
    stores[key].files=files||[];renderPreviews(key);
  };
  // Used by clearInwardForm / clearOutwardForm after a save — without this the
  // store kept the previous entry's photos and attached them to the next one.
  window.clearPhotos=function(key){
    if(!stores[key])return;
    stores[key].files=[];
    const cam=byId(stores[key].camera),gal=byId(stores[key].gallery);
    if(cam)cam.value=''; if(gal)gal.value='';
    renderPreviews(key);
  };

  document.addEventListener('DOMContentLoaded',()=>{
    Object.entries(stores).forEach(([key,s])=>{
      const cam=byId(s.camera); const gal=byId(s.gallery);
      if(cam&&!cam.dataset.photoBound){ cam.addEventListener('change',e=>addFiles(key,e.target.files)); cam.dataset.photoBound='1'; }
      if(gal&&!gal.dataset.photoBound){ gal.addEventListener('change',e=>addFiles(key,e.target.files)); gal.dataset.photoBound='1'; }
    });
    // Live billing recalc on freight + roundoff + party state change
    ['freightExp','roundOffInput','partyState'].forEach(id=>{
      const el=byId(id);
      if(el&&!el.dataset.billBound){ el.addEventListener('input',updateStoreTotals); el.addEventListener('change',updateStoreTotals); el.dataset.billBound='1'; }
    });
    ['calcGrossWeight','calcFreightRate'].forEach(id=>{
      const el=byId(id);
      if(el&&!el.dataset.frtBound){ el.addEventListener('input',updateStoreTotals); el.dataset.frtBound='1'; }
    });
  });
})();

/* ================================================================
   MASTER DATA — Item Master (Full Implementation)
================================================================ */
// Supabase/PostgREST caps a single request at ~1000 rows by default — with
// more items or ledger lines than that, a plain .select() would silently
// return only a partial dataset. This pages through .range() until a page
// comes back short, so callers always get every row.
async function fetchAllRows(table,selectCols,orderCol,filterFn){
  const PAGE=1000;
  let from=0,all=[];
  for(;;){
    let q=SB.from(table).select(selectCols);
    if(filterFn)q=filterFn(q);
    q=q.range(from,from+PAGE-1);
    if(orderCol)q=q.order(orderCol);
    const {data,error}=await q;
    if(error)throw error;
    all=all.concat(data||[]);
    if(!data||data.length<PAGE)break;
    from+=PAGE;
  }
  return all;
}

// Item Master table state — cached in full (see fetchAllRows) so the
// search box and Category filter both run instantly over the complete
// dataset instead of re-querying Supabase on every keystroke/click.
let sarvItemMasterRows=[];      // [{it, inQty, outQty, bal, catKey}]
// Last-loaded master rows, kept so each panel's search box can re-render from
// memory instead of refetching on every keystroke — same pattern as
// sarvItemMasterRows / renderItemMasterTable above.
let sarvSupplierMasterRows=[], sarvEmployeeMasterRows=[], sarvMachineMasterRows=[];

/* ================================================================
   ITEM MASTER — COLLAPSIBLE ADD FORM + FULL-HEIGHT LIST
   ----------------------------------------------------------------
   Two halves of the same idea: this tab is opened far more often to
   LOOK something up than to add a part, so the list gets the screen
   and the form gets out of the way until it is asked for.
================================================================ */
const IM_ADD_FORM_KEY='sarv_im_addform_open';
function isAddItemFormOpen_(){
  const b=byId('mi_formBody');
  return !!b&&b.style.display!=='none';
}
/* open===undefined flips it. remember===false opens it WITHOUT changing the
   saved preference — that is for the Edit button, which has to show the form
   whatever the user normally keeps it at, but should not quietly decide they
   now want it open every visit. The list is re-fitted afterwards, because the
   form opening or closing is exactly what changes how much room is left. */
window.setAddItemForm=function(open,remember){
  const body=byId('mi_formBody'),head=byId('mi_formToggle'),hint=byId('mi_formHint');
  if(!body)return;
  const want=(open===undefined)?!isAddItemFormOpen_():!!open;
  body.style.display=want?'block':'none';
  if(head)head.classList.toggle('open',want);
  if(hint)hint.textContent=want?'Click to close':'Click to open';
  if(remember!==false){try{localStorage.setItem(IM_ADD_FORM_KEY,want?'1':'0');}catch(e){}}
  fitItemListHeight_();
};
window.toggleAddItemForm=function(){setAddItemForm();};
/* Restores the remembered state. Default CLOSED on a browser that has never
   been told otherwise — the list is the reason people come here. */
function initAddItemForm_(){
  let open=false;
  try{open=localStorage.getItem(IM_ADD_FORM_KEY)==='1';}catch(e){}
  setAddItemForm(open);
}
/* Gives the item list every pixel left below it, measured rather than guessed.
   A fixed calc(100vh - 320px) could not know how tall the toolbar had wrapped
   on a narrow window, whether the filter chips were showing, or whether the Add
   form was open — so it was either too short (a letterbox in the middle of the
   page) or too tall (the last rows unreachable under the viewport).
   Called on load, on every toggle, on resize, and whenever the tab is shown. */
function fitItemListHeight_(){
  const box=byId('itemMasterBox');
  if(!box||!box.offsetParent)return;        // tab not visible — nothing to measure
  const top=box.getBoundingClientRect().top;
  // Breathing room under the table so the card's own border/padding is not
  // pressed against the bottom of the window.
  const h=Math.max(220,Math.round(window.innerHeight-top-24));
  /* maxHeight only, never a fixed height: a short list should shrink to its
     rows rather than leave a tall empty box under them. The scrollbar gutter
     is reserved regardless (overflow-y:scroll in the CSS), so the columns do
     not shift when the list crosses from fitting to not fitting. */
  box.style.maxHeight=h+'px';
}
window.addEventListener('resize',fitItemListHeight_);

/* ================================================================
   ITEM MASTER — PER-COLUMN FILTERS (Excel-style, and DEPENDENT)
   ----------------------------------------------------------------
   Every column header carries a ▾ button. It opens a list of the
   values actually present in that column, each tickable, plus a
   Min / Max pair on the numeric columns. Apply commits it; Remove
   Filter clears that one column; the chip bar under the toolbar
   clears any of them, or all at once.

   DEPENDENT is the point of it. The list a column offers is built
   from the rows that survive EVERY OTHER filter — the search box
   and the Stock (MSV) dropdown included — never from the full
   table. So picking Category = ELECTRICAL leaves the Make list
   showing only the makes that actually occur in ELECTRICAL items,
   and a combination that would return nothing is simply not
   offered. The one exception is a value that is already ticked:
   it stays listed, greyed, even when the other filters have taken
   every row carrying it, because a value you cannot see is a value
   you can never untick.

   This replaced the standalone Category dropdown that used to sit
   in the toolbar. Category is a column like any other now; two
   Category filters that both applied would have been a trap.
================================================================ */
/* How each filterable column is read. `get` returns the value used for
   matching and grouping — null meaning "not set", which is offered in the
   list as (Blank) so "show me the items with no Material" is askable.
   `numeric` adds the Min / Max row and sorts the value list by number. */
const SARV_IM_FILTER_COLS={
  code:{label:'Code',               numeric:false,get:r=>r.it.item_code},
  name:{label:'Item Name',          numeric:false,get:r=>r.it.name},
  desc:{label:'Description',        numeric:false,get:r=>r.it.description},
  cat: {label:'Category',           numeric:false,get:r=>r.catKey},
  size:{label:'Size',               numeric:false,get:r=>itemSize_(r.it)},
  mat: {label:'Material',           numeric:false,get:r=>itemMaterial_(r.it)},
  rate:{label:'Rate',               numeric:true, get:r=>Number(r.it.rate||0)},
  gst: {label:'GST %',              numeric:true, get:r=>itemGst_(r.it)},
  uom: {label:'UOM',                numeric:false,get:r=>r.it.uom||'PCS'},
  make:{label:'Make',               numeric:false,get:r=>r.it.make},
  msv: {label:'MIN STOCK QTY (MSV)',numeric:true, get:r=>itemMsv_(r.it)},
  soq: {label:'STD ORDER QTY',      numeric:true, get:r=>itemStdOrderQty_(r.it)},
  in:  {label:'IN Qty',             numeric:true, get:r=>r.inQty},
  out: {label:'OUT Qty',            numeric:true, get:r=>r.outQty},
  bal: {label:'Balance Qty',        numeric:true, get:r=>r.bal}
};
const IM_BLANK='(Blank)';
/* Applied filters, by column id: {values:Set<string>|null, min:number|null,
   max:number|null}. values===null means no value restriction — different from
   an empty Set, which means "nothing ticked", i.e. show nothing. */
let sarvImFilters={};
// Which column's panel is open, and the state being edited in it. Kept apart
// from sarvImFilters so Cancel really cancels.
let sarvImPanelCol=null, sarvImDraft=null;

// The display string a value is grouped and matched under. One function, used
// by the option list, the row test and the chip labels alike, so the three can
// never disagree about what "4" or "" means.
function imCellKey_(col,row){
  const v=SARV_IM_FILTER_COLS[col].get(row);
  if(v==null||String(v).trim()==='')return IM_BLANK;
  return String(v).trim();
}
// Numeric value for the Min / Max test. null = nothing to compare, which a
// range always rejects (an item with no MSV is neither above nor below one).
function imCellNum_(col,row){
  if(!SARV_IM_FILTER_COLS[col].numeric)return null;
  const v=SARV_IM_FILTER_COLS[col].get(row);
  if(v==null||String(v).trim()==='')return null;
  const n=Number(v);
  return isNaN(n)?null:n;
}
function imHasFilter_(col){
  const f=sarvImFilters[col];
  return !!f&&(f.values!=null||f.min!=null||f.max!=null);
}
function imActiveCols_(){return Object.keys(SARV_IM_FILTER_COLS).filter(imHasFilter_)}
function imColPass_(col,row){
  const f=sarvImFilters[col];
  if(!f)return true;
  if(f.values&&!f.values.has(imCellKey_(col,row)))return false;
  if(f.min!=null||f.max!=null){
    const n=imCellNum_(col,row);
    if(n==null)return false;
    if(f.min!=null&&n<f.min)return false;
    if(f.max!=null&&n>f.max)return false;
  }
  return true;
}
/* The non-column filters — the search box and the Stock/MSV dropdown. Pulled
   out so the dependent option lists apply them too; a value that only occurs
   in rows the search has already hidden is not a value worth offering. */
function imBasePass_(row){
  const q=(byId('itemMasterSearch')?.value||'').toLowerCase().trim();
  const msvFilter=byId('itemMasterMsvFilter')?.value||'ALL';
  if(msvFilter!=='ALL'){
    const msv=itemMsv_(row.it);
    // No MSV set — there is nothing to be below or above, so it shows in neither.
    if(msv==null||msv<=0)return false;
    if(msvFilter==='BELOW'&&!(row.bal<msv))return false;
    if(msvFilter==='ABOVE'&&!(row.bal>=msv))return false;
  }
  if(q){
    const hay=[row.it.item_code,row.it.name,row.it.description,row.it.category,row.it.sub_category,row.it.make,
      row.it.item_size,row.it.material_type].map(x=>String(x||'').toLowerCase()).join(' ');
    if(!hay.includes(q))return false;
  }
  return true;
}
// exceptCol is what makes the filters dependent: a column's own filter is left
// out when working out what that column should still be offering.
function imRowPass_(row,exceptCol){
  if(!imBasePass_(row))return false;
  return Object.keys(SARV_IM_FILTER_COLS).every(c=>c===exceptCol||imColPass_(c,row));
}
/* The value list for one column: what is left after every OTHER filter, with
   a count each. Sorted by number on numeric columns and alphabetically
   elsewhere; (Blank) always sinks to the bottom, where it reads as the
   leftover rather than as a value in its own right. */
function imOptionsFor_(col){
  const counts=new Map();
  sarvItemMasterRows.forEach(row=>{
    if(!imRowPass_(row,col))return;
    const k=imCellKey_(col,row);
    counts.set(k,(counts.get(k)||0)+1);
  });
  const numeric=SARV_IM_FILTER_COLS[col].numeric;
  const list=[...counts.entries()].map(([value,count])=>({value,count}));
  list.sort((a,b)=>{
    if(a.value===IM_BLANK)return 1;
    if(b.value===IM_BLANK)return -1;
    return numeric?(Number(a.value)-Number(b.value))
                  :String(a.value).localeCompare(String(b.value),undefined,{numeric:true,sensitivity:'base'});
  });
  return list;
}

window.imOpenFilter=function(ev,col){
  // Without this the click reaches the <th> and re-sorts the column underneath
  // the panel that just opened.
  if(ev){ev.stopPropagation();ev.preventDefault();}
  if(!SARV_IM_FILTER_COLS[col])return;
  if(sarvImPanelCol===col){imCloseFilterPanel();return;}   // same button closes it
  sarvImPanelCol=col;
  const cur=sarvImFilters[col];
  sarvImDraft={
    values:cur&&cur.values?new Set(cur.values):null,
    min:cur&&cur.min!=null?cur.min:null,
    max:cur&&cur.max!=null?cur.max:null,
    search:'',
    /* The option list is worked out once, here, not on every keystroke in the
       panel's search box. Nothing the panel does can change it: the draft is
       not applied until Apply, and a column's own filter is excluded from its
       own list anyway. On a master with thousands of items, recomputing it per
       keystroke was the one thing in here that would have felt slow. */
    options:imOptionsFor_(col),
    // The header button this panel hangs off. Kept so every re-render (search,
    // Select All, Clear) can re-anchor itself — the panel changes height as the
    // list narrows, and one that never re-positioned would grow off-screen.
    anchor:(ev&&ev.currentTarget)||byId('imF-'+col)
  };
  imRenderFilterPanel_();
};
function imEnsureFilterPanel_(){
  let p=byId('imFilterPanel');
  if(p)return p;
  p=document.createElement('div');
  p.id='imFilterPanel';
  // On <body> rather than inside the <th>: the table scrolls in a container
  // with its own overflow and a sticky header, which would clip it.
  document.body.appendChild(p);
  // A click inside the panel must never reach the document-level closer below.
  p.addEventListener('click',e=>e.stopPropagation());
  return p;
}
function imPositionFilterPanel_(anchor){
  const p=byId('imFilterPanel');if(!p)return;
  const btn=anchor||byId('imF-'+sarvImPanelCol);
  const r=btn?btn.getBoundingClientRect():{left:120,top:100,bottom:120};
  const w=p.offsetWidth||268,h=p.offsetHeight||320;
  // Kept inside the viewport: a filter on the last column would otherwise open
  // off the right edge, and one near the bottom would run off-screen.
  let left=Math.min(Math.max(8,r.left-10),Math.max(8,window.innerWidth-w-8));
  let top=r.bottom+4;
  if(top+h>window.innerHeight-8)top=Math.max(8,r.top-h-4);
  p.style.left=left+'px';p.style.top=top+'px';
  // Measured while hidden (see imRenderFilterPanel_), shown once it is parked
  // where it belongs — otherwise it flashes at the previous column's position.
  p.style.visibility='visible';
}
function imRenderFilterPanel_(){
  const col=sarvImPanelCol;if(!col)return;
  const p=imEnsureFilterPanel_(),meta=SARV_IM_FILTER_COLS[col];
  const opts=sarvImDraft.options||[];
  const present=new Set(opts.map(o=>o.value));
  // Ticked values the other filters have emptied out are appended, greyed, so
  // they can still be unticked. Without this the panel could strand a filter.
  const extra=sarvImDraft.values
    ? [...sarvImDraft.values].filter(v=>!present.has(v)).sort().map(v=>({value:v,count:0,gone:true}))
    : [];
  const all=opts.concat(extra);
  const term=(sarvImDraft.search||'').toLowerCase();
  const shown=term?all.filter(o=>o.value.toLowerCase().includes(term)):all;
  // values===null is "no restriction", which reads as everything ticked.
  const ticked=v=>sarvImDraft.values?sarvImDraft.values.has(v):true;
  const LIMIT=400;
  const clipped=shown.length>LIMIT?shown.slice(0,LIMIT):shown;
  const rowsHtml=clipped.length?clipped.map(o=>
      '<label class="imf-opt'+(o.gone?' gone':'')+'">'
      +'<input type="checkbox" data-v="'+escText(o.value)+'"'+(ticked(o.value)?' checked':'')+'>'
      +'<span class="t" title="'+escText(o.value)+'">'+escText(o.value)+'</span>'
      +'<span class="n">'+(o.gone?'0':o.count)+'</span></label>').join('')
    : '<div style="color:#94a3b8;padding:6px 2px;">'+(term?'Is search par koi value nahi mili.':'Baaki filters ke baad is column me koi value nahi bachi.')+'</div>';
  const clipNote=shown.length>LIMIT
    ? '<div style="color:#b45309;font-size:10px;padding:4px 2px 0;">Pehli '+LIMIT+' values dikh rahi hain ('+shown.length+' me se) — upar search karke chhota karein.</div>'
    : '';
  const rangeHtml=meta.numeric
    ? '<div class="imf-range">'
      +'<input type="number" id="imfMin" placeholder="Min" step="any" value="'+(sarvImDraft.min!=null?sarvImDraft.min:'')+'">'
      +'<input type="number" id="imfMax" placeholder="Max" step="any" value="'+(sarvImDraft.max!=null?sarvImDraft.max:'')+'">'
      +'</div>'
    : '';
  p.innerHTML=
     '<div class="imf-head">'+escText(meta.label)
    +'<div class="imf-sub">'+opts.length+' value(s) &middot; baaki filters ke hisaab se</div></div>'
    +'<div class="imf-body">'+rangeHtml
    +'<input type="text" id="imfSearch" placeholder="&#128269; Values me search..." value="'+escText(sarvImDraft.search||'')+'">'
    +'<div style="display:flex;justify-content:space-between;margin-top:6px;">'
    +'<button type="button" class="imf-mini" id="imfAll">&#9745; Select All</button>'
    +'<button type="button" class="imf-mini" id="imfNone" style="color:#b91c1c;">&#9744; Clear</button></div>'
    +'<div class="imf-list" id="imfList">'+rowsHtml+'</div>'+clipNote
    +'</div>'
    +'<div class="imf-foot">'
    +'<button type="button" class="imf-btn imf-apply" id="imfApply">&#10004; Apply</button>'
    +'<button type="button" class="imf-btn imf-remove" id="imfRemove">&#10006; Remove Filter</button>'
    +'<button type="button" class="imf-btn imf-cancel" id="imfCancel">Cancel</button>'
    +'</div>';
  // Laid out so it can be measured, but not yet visible — imPositionFilterPanel_
  // at the bottom of this function reveals it once it has somewhere to be.
  p.style.visibility='hidden';
  p.style.display='block';

  // Ticking a box only ever edits the draft — nothing filters until Apply.
  // Until the first tick values is null ("all"), so it is materialised from
  // what is currently shown as checked rather than starting empty, or the
  // first untick would wipe every other value too.
  const listEl=byId('imfList');
  listEl.addEventListener('change',e=>{
    const cb=e.target.closest('input[type=checkbox]');if(!cb)return;
    if(!sarvImDraft.values)sarvImDraft.values=new Set(all.map(o=>o.value));
    if(cb.checked)sarvImDraft.values.add(cb.dataset.v);else sarvImDraft.values.delete(cb.dataset.v);
  });
  const search=byId('imfSearch');
  search.addEventListener('input',()=>{
    sarvImDraft.search=search.value;
    const at=search.selectionStart;
    imRenderFilterPanel_();
    const s2=byId('imfSearch');if(s2){s2.focus();try{s2.setSelectionRange(at,at)}catch(e){}}
  });
  // Select All / Clear act on WHAT IS SHOWN, so a search narrows what they
  // touch — same as Excel, and the only reading that is useful on a long list.
  byId('imfAll').addEventListener('click',()=>{
    if(!sarvImDraft.values)sarvImDraft.values=new Set(all.map(o=>o.value));
    clipped.forEach(o=>sarvImDraft.values.add(o.value));
    if(!term&&sarvImDraft.values.size>=all.length)sarvImDraft.values=null;   // everything = no restriction
    imRenderFilterPanel_();
  });
  byId('imfNone').addEventListener('click',()=>{
    if(!sarvImDraft.values)sarvImDraft.values=new Set(all.map(o=>o.value));
    clipped.forEach(o=>sarvImDraft.values.delete(o.value));
    imRenderFilterPanel_();
  });
  if(meta.numeric){
    const rd=()=>{
      const mn=byId('imfMin').value.trim(),mx=byId('imfMax').value.trim();
      sarvImDraft.min=mn===''?null:Number(mn);
      sarvImDraft.max=mx===''?null:Number(mx);
    };
    byId('imfMin').addEventListener('input',rd);
    byId('imfMax').addEventListener('input',rd);
  }
  byId('imfApply').addEventListener('click',imApplyFilter);
  byId('imfRemove').addEventListener('click',()=>imRemoveFilter(col));
  byId('imfCancel').addEventListener('click',imCloseFilterPanel);
  imPositionFilterPanel_(sarvImDraft.anchor);
}
window.imApplyFilter=function(){
  const col=sarvImPanelCol;if(!col)return;
  const d=sarvImDraft||{};
  let {min,max}=d;
  if(min!=null&&isNaN(min))min=null;
  if(max!=null&&isNaN(max))max=null;
  // A reversed range is a slip, not a request for an empty table.
  if(min!=null&&max!=null&&min>max){const t=min;min=max;max=t;}
  /* Everything ticked is the same as no filter, so it is stored as none. That
     is what keeps the header badge and the chip bar honest — a green funnel
     that hides nothing is worse than no badge at all. */
  let values=d.values;
  if(values){
    const opts=(d.options||[]).map(o=>o.value);
    if(opts.length&&values.size===opts.length&&opts.every(v=>values.has(v)))values=null;
  }
  if(values==null&&min==null&&max==null){imRemoveFilter(col);return;}
  if(values&&values.size===0){
    showToast('⚠️ Is column me koi value tick nahi hai — aise filter karne par list khali rahegi','warn');
  }
  sarvImFilters[col]={values:values?new Set(values):null,min,max};
  imCloseFilterPanel();
  renderItemMasterTable();
};
window.imRemoveFilter=function(col){
  delete sarvImFilters[col];
  if(sarvImPanelCol===col)imCloseFilterPanel();
  renderItemMasterTable();
};
window.imClearAllFilters=function(){
  sarvImFilters={};
  imCloseFilterPanel();
  renderItemMasterTable();
};
function imCloseFilterPanel(){
  const p=byId('imFilterPanel');if(p)p.style.display='none';
  sarvImPanelCol=null;sarvImDraft=null;
}
// Click anywhere else, Escape, or a scroll/resize that would leave the panel
// floating away from its header — all close it.
document.addEventListener('click',e=>{
  if(!sarvImPanelCol)return;
  if(e.target.closest&&e.target.closest('.im-fbtn'))return;   // handled by imOpenFilter
  imCloseFilterPanel();
});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&sarvImPanelCol)imCloseFilterPanel()});
window.addEventListener('resize',()=>{if(sarvImPanelCol)imCloseFilterPanel()});
/* Capture phase, because a scroll inside the table container does not bubble.
   The panel's OWN value list is excluded — it scrolls, and closing the panel
   the moment someone scrolls its list would make a long list unusable. */
document.addEventListener('scroll',e=>{
  if(!sarvImPanelCol)return;
  const p=byId('imFilterPanel'),t=e.target;
  if(p&&t&&t.nodeType===1&&p.contains(t))return;
  imCloseFilterPanel();
},true);

/* What each applied filter looks like in a chip and in the header's tooltip. */
function imFilterSummary_(col){
  const f=sarvImFilters[col];if(!f)return '';
  const parts=[];
  if(f.min!=null||f.max!=null){
    parts.push(f.min!=null&&f.max!=null?(f.min+'–'+f.max):(f.min!=null?('≥ '+f.min):('≤ '+f.max)));
  }
  if(f.values){
    const v=[...f.values];
    parts.push(v.length===0?'none':v.length<=2?v.join(', '):(v.length+' selected'));
  }
  return parts.join(' · ');
}
// Header badges + the chip bar, rebuilt on every render so they can never drift
// from what is actually being applied.
function imRenderFilterIndicators_(){
  Object.keys(SARV_IM_FILTER_COLS).forEach(col=>{
    const btn=byId('imF-'+col);if(!btn)return;
    const on=imHasFilter_(col);
    btn.classList.toggle('on',on);
    btn.innerHTML=on?'&#9776;':'&#9662;';
    btn.title=on?(SARV_IM_FILTER_COLS[col].label+' filter: '+imFilterSummary_(col)+' — click karke badlein ya hatayein')
                 :('Filter '+SARV_IM_FILTER_COLS[col].label);
  });
  const bar=byId('imFilterChips');if(!bar)return;
  const cols=imActiveCols_();
  if(!cols.length){bar.style.display='none';bar.innerHTML='';return;}
  bar.style.display='flex';
  bar.innerHTML='<span style="font-size:10px;font-weight:800;color:#475569;">&#128269; FILTERS:</span>'
    +cols.map(c=>'<span class="imf-chip">'+escText(SARV_IM_FILTER_COLS[c].label)+': '+escText(imFilterSummary_(c))
      +'<button type="button" onclick="imRemoveFilter(\''+c+'\')" title="Is column ka filter hatayein">&#10006;</button></span>').join('')
    +'<button type="button" onclick="imClearAllFilters()" style="background:#fef2f2;border:1px solid #fecaca;color:#b91c1c;'
    +'border-radius:12px;padding:3px 10px;font-size:10px;font-weight:800;cursor:pointer;">&#10006; Clear All Filters ('+cols.length+')</button>';
}
/* Minimum Stock Value for an item row. Stored in items.sub_category, which is
   free text — blank or legacy non-numeric content means "no MSV set", and such
   an item is neither below nor above one. */
function itemMsv_(it){
  const raw=it&&it.sub_category;
  if(raw==null||String(raw).trim()==='')return null;
  const n=Number(raw);
  return isNaN(n)?null:n;
}
/* GST % held on the Item Master row. A part's GST rate is a property of the
   part, not of the day it was bought, so it is set once on the item and read
   back here by every entry form. 18 is the default for an item saved before
   the column existed — the same number those forms hard-coded previously, so
   nothing changes for existing data until someone sets a rate explicitly.
   SARV_DEFAULT_GST is the single place that default lives. */
const SARV_DEFAULT_GST=18;
/* Columns on `items` that a database may simply not have yet, with the DDL
   that adds each one. Every save drops whichever of these the server says it
   does not know about and retries, so the rest of the item still saves and the
   user is told exactly what to run. gst_pct was the first; Item Size, Material
   Type and Standard Order Qty arrived with ITEM_MASTER_FIELDS_MIGRATION.sql
   and are handled the same way rather than each growing its own special case. */
const SARV_ITEM_OPTIONAL_COLUMNS={
  gst_pct:      {label:'GST %',              ddl:'alter table items add column gst_pct numeric default 18;'},
  item_size:    {label:'Item Size',          ddl:'alter table items add column item_size text;'},
  material_type:{label:'Material Type',      ddl:'alter table items add column material_type text;'},
  std_order_qty:{label:'Standard Order Qty', ddl:'alter table items add column std_order_qty numeric;'}
};
/* Shown once per session PER COLUMN, with the exact migration, instead of the
   same vague line on every single item save. */
const sarvItemColumnWarned=new Set();
function warnItemColumnsMissing_(cols){
  const fresh=(cols||[]).filter(c=>SARV_ITEM_OPTIONAL_COLUMNS[c]&&!sarvItemColumnWarned.has(c));
  if(!fresh.length)return;
  fresh.forEach(c=>sarvItemColumnWarned.add(c));
  showToast('⚠️ '+fresh.map(c=>SARV_ITEM_OPTIONAL_COLUMNS[c].label).join(' / ')+' save nahi hua — items table me '
    +fresh.map(c=>'<b>'+c+'</b>').join(', ')+' column hi nahi hai.<br>'
    +'Supabase → SQL Editor me ek baar ye chalayein:<br>'
    +fresh.map(c=>'<code>'+SARV_ITEM_OPTIONAL_COLUMNS[c].ddl+'</code>').join('<br>')+'<br>'
    +"<code>notify pgrst, 'reload schema';</code><br>"
    +'Uske baad item dobara save karein — ye fields tab se save hone lagengi.','warn');
}
// Kept as a thin wrapper: older call sites still ask specifically about GST.
function warnGstColumnMissing_(){warnItemColumnsMissing_(['gst_pct'])}
/* Which optional column, if any, an error is complaining about. PostgREST
   reports a column it has not re-read yet exactly like a column that does not
   exist, so one test covers both "the column is missing" and "the column was
   just added and the schema cache is stale". */
function missingItemColumn_(e){
  const msg=(e&&e.message)||'';
  if(!/column|does not exist|schema cache/i.test(msg))return null;
  return Object.keys(SARV_ITEM_OPTIONAL_COLUMNS).find(c=>new RegExp('\\b'+c+'\\b','i').test(msg))||null;
}
async function saveItemRow_(payload,editingId){
  const run=p=>editingId
    ? SB.from('items').update(p).eq('id',editingId)
    : SB.from('items').insert(p);
  let body={...payload},dropped=[];
  let r=await run(body);
  /* The stale schema cache is by far the common case and a single retry clears
     it, so a column that really is there does get saved instead of being
     dropped on the spot. One retry for the whole payload, then the loop below
     peels off genuinely-absent columns one at a time — PostgREST only ever
     names the first one it trips over. */
  if(missingItemColumn_(r.error)){
    await new Promise(res=>setTimeout(res,700));
    r=await run(body);
  }
  // Bounded by the number of optional columns, so a server that keeps
  // complaining can never spin this forever.
  for(let i=0;i<Object.keys(SARV_ITEM_OPTIONAL_COLUMNS).length&&r.error;i++){
    const col=missingItemColumn_(r.error);
    if(!col||!(col in body))break;
    delete body[col];dropped.push(col);
    r=await run(body);
  }
  return {error:r.error,dropped:r.error?[]:dropped,droppedGst:!r.error&&dropped.includes('gst_pct')};
}
/* ── "Add New Item" popup (Item Configurations) ───────────────────
   The Item Name column only offers what the Item Master already holds, so a
   part that wasn't there yet meant leaving the half-typed entry, opening Item
   Master, adding it, and coming back. This popup writes the same items row —
   through saveItemRow_, so the gst_pct retry/fallback applies here too —
   refreshes the shared datalists and drops the new name straight into the
   entry that asked for it. */
// Which grid asked for the popup, so the saved name lands back in it:
// 'inward' | 'outward' | 'purchase' (the PR form's Items Required table).
const SARV_NEW_ITEM_TARGETS={
  inward:  {body:'itemTableBody',        nameSel:'.item-name',     add:()=>addNewRow(),           totals:()=>updateStoreTotals()},
  outward: {body:'outwardItemTableBody', nameSel:'.out-item-name', add:()=>addOutwardItemRow(),   totals:()=>updateOutTotals()},
  purchase:{body:'p_itemTableBody',      nameSel:'.col-name',      add:()=>addPurchaseMainRow(),  totals:()=>refreshPurchaseTotals()}
};
let sarvNewItemTarget='inward';
function openNewItemMasterModal(target){
  sarvNewItemTarget=SARV_NEW_ITEM_TARGETS[target]?target:'inward';
  let ov=byId('sarvNewItemModal');
  if(!ov){
    const FLD='class="form-control" style="height:30px;font-size:12px;"';
    const lbl=t=>'<label style="display:block;font-size:10px;font-weight:700;color:#475569;margin-bottom:2px;">'+t+'</label>';
    // One cell of the form grid. span=2 makes it run the full width.
    const cell=(t,inner,span)=>'<div'+(span===2?' style="grid-column:1 / -1;"':'')+'>'+lbl(t)+inner+'</div>';
    const txt=(id,ph,extra)=>'<input type="text" id="'+id+'" placeholder="'+ph+'" '+(extra||'')+' '+FLD+'>';
    const num=(id,ph,step)=>'<input type="number" id="'+id+'" placeholder="'+ph+'" min="0" step="'+step+'" '+FLD+'>';
    const sel=id=>'<select id="'+id+'" '+FLD+'></select>';
    ov=document.createElement('div');
    ov.id='sarvNewItemModal';
    ov.className='secure-modal-overlay';
    ov.style.cssText='display:none;align-items:center;justify-content:center;z-index:31000;';
    /* Laid out the way the Item Master form reads: identity first (name,
       description), then classification (category, make, size, material),
       then how it is counted (UOM, MSV, Standard Order Qty), then how it is
       priced (GST, rate).

       Item Size / Material Type / Standard Order Qty are here because this
       popup is the only way a PR or an entry row creates an item, and a part
       created without them comes out of the Item Master half-filled — then
       nobody goes back to finish it. Make / Brand, Item Size and Material Type
       all suggest what the master already holds, so the store's own vocabulary
       gets reused instead of five spellings of the same brand. */
    ov.innerHTML='<div class="secure-modal-box" style="max-width:520px;width:94vw;">'
      +'<h3 style="margin:0 0 2px;font-size:15px;color:#0f172a;">&#10133; Add New Item</h3>'
      +'<p style="margin:0 0 14px;font-size:11px;color:#64748b;">Item Master me save hoga aur Item Name list me turant dikhne lagega.</p>'
      +'<div style="display:grid;grid-template-columns:1fr 1fr;gap:10px 12px;">'
        +cell('Item Name <span style="color:#dc2626;">&#9733;</span>',
              txt('ni_name','Type karein — saved items suggest honge','list="dl-ni-item-name" autocomplete="off"')
              +'<datalist id="dl-ni-item-name"></datalist>'
              +'<div id="ni_nameHint" style="min-height:13px;margin-top:3px;font-size:10px;font-weight:700;"></div>',2)
        +cell('Item Description',txt('ni_desc','Type karein — saved descriptions suggest honge','list="dl-ni-item-desc" autocomplete="off"')+'<datalist id="dl-ni-item-desc"></datalist>',2)
        +cell('Category',sel('ni_cat'))
        +cell('Make / Brand',txt('ni_make','Type karein — saved makes suggest honge','list="dl-ni-item-make" autocomplete="off"')+'<datalist id="dl-ni-item-make"></datalist>')
        +cell('Item Size',txt('ni_itemSize','e.g. 1/2 INCH, M8 x 40, 24&quot;','list="dl-ni-itemSize" autocomplete="off"')+'<datalist id="dl-ni-itemSize"></datalist>')
        +cell('Material Type',txt('ni_materialType','e.g. SS 304, MS, BRASS','list="dl-ni-materialType" autocomplete="off"')+'<datalist id="dl-ni-materialType"></datalist>')
        +cell('UOM',sel('ni_uom'))
        +cell('Minimum Stock Qty (MSV)',num('ni_msv','optional','any'))
        +cell('Standard Order Qty',num('ni_stdOrderQty','e.g. 10','any'))
        +cell('GST %',sel('ni_gst'))
        +cell('Rate (&#8377;)',num('ni_rate','0','.01'))
      +'</div>'
      +'<div style="display:flex;gap:8px;justify-content:flex-end;margin-top:16px;">'
      +'<button type="button" id="ni_cancel" class="btn" style="background:#e2e8f0;color:#0f172a;">Cancel</button>'
      +'<button type="button" id="ni_save" class="btn btn-primary">&#128190; Save Item</button>'
      +'</div></div>';
    /* Mounted on <body>, NOT inside #storeInterface. That panel is set to
       display:none whenever the Purchase panel is open (see activatePanel), so
       a popup living inside it was invisible when opened from the PERSONNEL
       ITEM REQUIREMENT FORM — and then appeared, already open, the next time
       Material Inward was shown. .secure-modal-box / .btn / .form-control are
       scoped to that panel, so #sarvNewItemModal carries its own copy of those
       styles in the stylesheet above. Same fix, and same reason, as
       #pwdGateModal. */
    document.body.appendChild(ov);
    byId('ni_cancel').onclick=closeNewItemMasterModal;
    byId('ni_save').onclick=saveNewItemFromModal_;
    ov.addEventListener('click',e=>{if(e.target===ov)closeNewItemMasterModal();});
    const nameBox=byId('ni_name');
    nameBox.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();saveNewItemFromModal_();}});
    // The suggestion list is there to stop a second copy of an item being
    // created, so the moment what is typed matches one, say so — the save
    // refuses it anyway, and this says why before the button is pressed.
    nameBox.addEventListener('input',refreshNewItemNameHint_);
  }
  // The dropdown under Item Name is the live Item Master list, so a part that
  // already exists is offered rather than entered a second time.
  const dl=byId('dl-ni-item-name');
  if(dl)dl.innerHTML=(sarvItemCatalog||[]).map(it=>
    '<option value="'+escText(String(it.name||''))+'">'+escText([it.make,it.category].filter(Boolean).join(' — '))+'</option>').join('');
  /* Item Description draws on what is already in the master too, so the same
     spec is worded the same way every time instead of ten near-copies. One
     entry per distinct description, labelled with the item it came from. */
  const dd=byId('dl-ni-item-desc');
  if(dd){
    const seen=new Set(), opts=[];
    (sarvItemCatalog||[]).forEach(it=>{
      const d=String(it.description||'').trim(); if(!d) return;
      const key=d.toUpperCase(); if(seen.has(key)) return;
      seen.add(key);
      opts.push('<option value="'+escText(d)+'">'+escText(String(it.name||''))+'</option>');
    });
    dd.innerHTML=opts.join('');
  }
  // Category / UOM / GST choices are mirrored off the Item Master form, so both
  // screens always offer exactly the same lists without a second copy to keep.
  const mirror=(from,to,fallback)=>{const s=byId(from),d=byId(to);if(d)d.innerHTML=s?s.innerHTML:fallback;};
  mirror('mi_category','ni_cat','<option value="">— Select —</option>');
  mirror('mi_uom','ni_uom','<option>PCS</option>');
  mirror('mi_gst','ni_gst','<option>5</option><option>12</option><option>18</option><option>28</option><option>0</option>');
  /* Make / Brand, Item Size and Material Type are free text with a suggestion
     list built from what the master already holds — the same lists the Item
     Master form offers, so a brand that has been typed once is offered back
     instead of re-spelled. Built here rather than mirrored off the Item Master
     datalists, because those are only filled when that panel has been opened. */
  {
    const fillDl=(dlId,vals)=>{
      const dl=byId(dlId);if(!dl)return;
      dl.innerHTML=[...new Set(vals.filter(v=>String(v||'').trim()))]
        .sort((a,b)=>String(a).localeCompare(String(b),undefined,{numeric:true,sensitivity:'base'}))
        .map(v=>'<option value="'+escText(String(v))+'">').join('');
    };
    fillDl('dl-ni-item-make',(sarvItemCatalog||[]).map(it=>it.make));
    fillDl('dl-ni-itemSize',(sarvItemCatalog||[]).map(itemSize_));
    fillDl('dl-ni-materialType',(sarvItemCatalog||[]).map(itemMaterial_));
  }
  ['ni_name','ni_desc','ni_make','ni_msv','ni_itemSize','ni_materialType','ni_stdOrderQty']
    .forEach(id=>{const e=byId(id);if(e)e.value='';});
  if(byId('ni_rate'))byId('ni_rate').value='0';
  if(byId('ni_cat'))byId('ni_cat').value='';
  if(byId('ni_gst'))byId('ni_gst').value=String(SARV_DEFAULT_GST);
  refreshNewItemNameHint_();
  ov.style.display='flex';
  setTimeout(()=>byId('ni_name')?.focus(),60);
}
function newItemDuplicate_(name){
  const key=String(name||'').trim().toUpperCase();
  if(!key)return null;
  return (sarvItemCatalog||[]).find(it=>String(it.name||'').trim().toUpperCase()===key)||null;
}
function refreshNewItemNameHint_(){
  const hint=byId('ni_nameHint');if(!hint)return;
  const dup=newItemDuplicate_(byId('ni_name')?.value);
  hint.style.color='#b45309';
  hint.textContent=dup?('⚠️ Ye item pehle se master me hai ('+(dup.item_code||dup.uom||'')+') — list me se select karein'):'';
}
function closeNewItemMasterModal(){const ov=byId('sarvNewItemModal');if(ov)ov.style.display='none';}
async function saveNewItemFromModal_(){
  if(!SB_READY)return showToast('Supabase URL/key configure karein','warn');
  const name=(byId('ni_name')?.value||'').trim().toUpperCase();
  if(!name){showToast('❌ Item Name required!','error');byId('ni_name')?.focus();return;}
  // Same rule the Item Master screen applies: one name, one master row.
  if(newItemDuplicate_(name))
    return showToast('⚠️ "'+name+'" pehle se Item Master me hai — list me se select karein','warn');
  const btn=byId('ni_save');
  if(btn){btn.disabled=true;btn.textContent='⏳ Saving…';}
  try{
    const payload={
      name,
      description:(byId('ni_desc')?.value||'').trim()||null,
      category:byId('ni_cat')?.value||null,
      make:(byId('ni_make')?.value||'').trim()||null,
      // Minimum Stock Qty (MSV) rides in sub_category, exactly as the Item
      // Master form stores it — a column of its own would need a migration
      // and would orphan everything already saved there.
      sub_category:(byId('ni_msv')?.value||'').trim()||null,
      uom:(byId('ni_uom')?.value||'PCS').trim()||'PCS',
      rate:Number(byId('ni_rate')?.value||0),
      gst_pct:Number(byId('ni_gst')?.value||SARV_DEFAULT_GST),
      /* Three columns a database may not have yet — saveItemRow_ drops
         whichever the server rejects and warnItemColumnsMissing_ names the
         migration, so the rest of the item still saves. Blank stays null
         rather than an empty string, the same as the Item Master form. */
      item_size:(byId('ni_itemSize')?.value||'').trim()||null,
      material_type:(byId('ni_materialType')?.value||'').trim()||null,
      std_order_qty:(byId('ni_stdOrderQty')?.value||'').trim()===''?null:Number(byId('ni_stdOrderQty').value)
    };
    const code=(name.replace(/[^A-Z0-9]+/g,'-').replace(/^-|-$/g,'').slice(0,28)||'ITEM')+'-'+String(Date.now()).slice(-4);
    const {error,dropped}=await saveItemRow_({item_code:code,...payload},null);
    if(error)throw error;
    warnItemColumnsMissing_(dropped);
    // The shared catalog is refreshed first so the new name already resolves
    // when it lands in the row below; the heavier Item Master reload follows.
    const q=await SB.from('items').select('*').order('name');
    if(!q.error&&q.data)refreshItemDatalist(q.data);
    closeNewItemMasterModal();
    fillNewItemIntoEntryRow_(name);
    showToast('✅ "'+name+'" Item Master me add ho gaya');
    if(typeof loadItemMaster==='function')loadItemMaster().catch(()=>{});
  }catch(e){dbError(e);}
  finally{if(btn){btn.disabled=false;btn.innerHTML='&#128190; Save Item';}}
}
/* Drops the new name into the first empty Item Name box of the entry that
   asked for it, adding a row when every one is filled, and runs the normal
   autofill so Description / Category / UOM / GST arrive with it. */
function fillNewItemIntoEntryRow_(name){
  const t=SARV_NEW_ITEM_TARGETS[sarvNewItemTarget]||SARV_NEW_ITEM_TARGETS.inward;
  const tb=byId(t.body);
  if(!tb)return;
  // The PR grid's rows are plain <tr>; the two store grids interleave
  // .po-info-row sub-rows, which carry no name box — querySelectorAll on the
  // name class skips them either way.
  let box=[...tb.querySelectorAll(t.nameSel)].find(el=>!String(el.value||'').trim());
  if(!box){const tr=t.add();box=tr&&tr.querySelector(t.nameSel);}
  if(!box)return;
  box.value=name;
  applyItemAutofill(name,box.closest('tr'),sarvNewItemTarget,true);
  box.focus();
  t.totals();
}
window.openNewItemMasterModal=openNewItemMasterModal;
function itemGst_(it){
  const raw=it&&it.gst_pct;
  if(raw==null||String(raw).trim()==='')return SARV_DEFAULT_GST;
  const n=Number(raw);
  return isNaN(n)?SARV_DEFAULT_GST:n;
}
/* Item Size / Material Type / Standard Order Qty — three more properties that
   belong to the PART rather than to a particular purchase. Read through
   helpers for the same reason itemMsv_ exists: on a database where the
   migration has not been run yet the column simply is not on the row, and
   every caller has to treat that as "not set" rather than as undefined. */
/* Feeds the Item Size / Material Type suggestion lists from what the master
   already holds, so the store's own vocabulary gets offered back instead of a
   dropdown someone has to maintain. Both inputs stay free text — a suggestion
   list never rejects anything typed past it. */
function refreshItemAttributeDatalists_(items){
  const fill=(dlId,vals)=>{
    const dl=byId(dlId);if(!dl)return;
    dl.innerHTML=[...new Set(vals.filter(Boolean))]
      .sort((a,b)=>a.localeCompare(b,undefined,{numeric:true,sensitivity:'base'}))
      .map(v=>'<option value="'+escText(v)+'">').join('');
  };
  // Make / Brand gets the same treatment as Item Size and Material Type: the
  // Item Master form's own box offers back every brand already on file, so the
  // same make is not re-spelled three ways across the catalogue.
  fill('dl-mi-make',(items||[]).map(it=>{const v=it&&it.make;return String(v==null?'':v).trim()||null}));
  fill('dl-mi-itemSize',(items||[]).map(itemSize_));
  fill('dl-mi-materialType',(items||[]).map(itemMaterial_));
}
function itemSize_(it){const v=it&&it.item_size;return String(v==null?'':v).trim()||null}
function itemMaterial_(it){const v=it&&it.material_type;return String(v==null?'':v).trim()||null}
function itemStdOrderQty_(it){
  const raw=it&&it.std_order_qty;
  if(raw==null||String(raw).trim()==='')return null;
  const n=Number(raw);
  return isNaN(n)?null:n;
}
function isBelowMsv_(row){
  const msv=itemMsv_(row.it);
  return msv!=null&&msv>0&&row.bal<msv;
}
/* Sortable columns, and how each one's value is read off a row. The text
   columns sort alphabetically, the numeric ones by value — a Code like
   "ITEM-9" must sit next to "ITEM-10" by name, not by number. */
const SARV_ITEM_SORTERS={
  code:{text:true, get:r=>r.it.item_code},
  name:{text:true, get:r=>r.it.name},
  cat: {text:true, get:r=>r.it.category},
  size:{text:true, get:r=>itemSize_(r.it)},
  mat: {text:true, get:r=>itemMaterial_(r.it)},
  msv: {text:false,get:r=>itemMsv_(r.it)},
  soq: {text:false,get:r=>itemStdOrderQty_(r.it)},
  in:  {text:false,get:r=>r.inQty},
  out: {text:false,get:r=>r.outQty},
  bal: {text:false,get:r=>r.bal}
};
/* Sort state. key===null means the list keeps the name order it arrives in. */
let sarvItemMasterSort={key:null,dir:1};
window.sortItemMaster=function(key){
  // Same column again flips the direction; a different column starts ascending.
  if(sarvItemMasterSort.key===key)sarvItemMasterSort.dir=-sarvItemMasterSort.dir;
  else sarvItemMasterSort={key,dir:1};
  renderItemMasterTable();
};
function updateItemMasterSortIndicators_(){
  Object.keys(SARV_ITEM_SORTERS).forEach(k=>{
    const el=byId('imSort-'+k);if(!el)return;
    const on=sarvItemMasterSort.key===k;
    el.innerHTML=on?(sarvItemMasterSort.dir===1?'&#9650;':'&#9660;'):'&#8693;';
    el.style.opacity=on?'1':'0.35';
  });
}
window.renderItemMasterTable=function(){
  const tb=byId('itemMasterBody'),cnt=byId('itemMasterCount');
  if(!tb)return;
  const q=(byId('itemMasterSearch')?.value||'').toLowerCase().trim();
  const msvFilter=byId('itemMasterMsvFilter')?.value||'ALL';
  /* The search box and the Stock dropdown live in imBasePass_, the column
     filters in imColPass_, and imRowPass_ puts them together — the same three
     functions the dependent option lists use. One code path, so what a column
     filter OFFERS and what the table then SHOWS can never disagree. */
  const rows=sarvItemMasterRows.filter(row=>imRowPass_(row,null));
  const sorter=SARV_ITEM_SORTERS[sarvItemMasterSort.key];
  if(sorter){
    const dir=sarvItemMasterSort.dir;
    rows.sort((a,b)=>{
      let x=sorter.get(a),y=sorter.get(b);
      if(sorter.text){x=String(x==null?'':x).trim()||null;y=String(y==null?'':y).trim()||null;}
      // A missing value — no MSV, a blank Category — stays at the bottom in
      // BOTH directions. It isn't "smaller than zero" or "before A"; it simply
      // isn't part of the comparison, and flipping it to the top on a
      // descending sort would bury the rows that were actually asked for.
      if(x==null&&y==null)return 0;
      if(x==null)return 1;
      if(y==null)return -1;
      // localeCompare with numeric:true keeps ITEM-2 before ITEM-10.
      return (sorter.text?String(x).localeCompare(String(y),undefined,{numeric:true,sensitivity:'base'}):(x-y))*dir;
    });
  }
  updateItemMasterSortIndicators_();
  imRenderFilterIndicators_();
  // The chip bar appears and disappears with the filters, which moves the top
  // of the list — so the height is re-fitted on every render, not just on load.
  fitItemListHeight_();
  const activeCols=imActiveCols_();
  const filterActive=activeCols.length>0||!!q||msvFilter!=='ALL';
  if(cnt)cnt.textContent=filterActive?`${rows.length} of ${sarvItemMasterRows.length} items`:`${sarvItemMasterRows.length} items`;
  if(!sarvItemMasterRows.length){
    tb.innerHTML='<tr><td colspan="18" style="text-align:center;padding:20px;color:#94a3b8;">No items yet — Add your first item above ⬆️</td></tr>';
    return;
  }
  if(!rows.length){
    /* An empty list has to say WHICH filter emptied it, and give the way out
       in the same breath. "No items match" on its own is how someone decides
       their Item Master has lost its data. */
    const why=activeCols.length
      ? 'In column filters ke baad koi item nahi bacha: '
        +activeCols.map(c=>SARV_IM_FILTER_COLS[c].label+' ('+imFilterSummary_(c)+')').join(', ')
      : msvFilter==='BELOW'?'Koi item MSV se neeche nahi hai (jin items ka MSV set nahi hai wo is filter me nahi aate).'
      : msvFilter==='ABOVE'?'Koi item MSV se upar nahi hai (jin items ka MSV set nahi hai wo is filter me nahi aate).'
      : 'Is search par koi item nahi mila.';
    tb.innerHTML='<tr><td colspan="18" style="text-align:center;padding:20px;color:#94a3b8;">'+escText(why)
      +(activeCols.length?'<br><button type="button" onclick="imClearAllFilters()" style="margin-top:8px;background:#fef2f2;border:1px solid #fecaca;color:#b91c1c;border-radius:12px;padding:4px 14px;font-size:11px;font-weight:800;cursor:pointer;">&#10006; Clear All Filters</button>':'')
      +'</td></tr>';
    return;
  }
  let totalIn=0,totalOut=0,totalBal=0;
  /* Display only: a whole number stays as it is (12), a decimal one is
     rounded to two places (12.345 → 12.35, 0.1+0.2 → 0.30). The MSV check,
     sorting and filters still work on the exact figures. */
  const q2=v=>{const n=Number(v);if(v==null||v===''||!isFinite(n))return v;return Number.isInteger(n)?String(n):n.toFixed(2);};
  // Admin Panel › Tab Visibility › Item Master › New PR Generation (default: Admin only).
  const prAdmin=sarvTabVisible('MD_ITEM_NEWPR');
  byId('itemMasterTable')?.classList.toggle('im-hide-newpr',!prAdmin);
  const bodyRows=rows.map((row,i)=>{
    const{it,inQty,outQty,bal}=row;
    totalIn+=inQty;totalOut+=outQty;totalBal+=bal;
    const balColor=bal>0?'#166534':bal<0?'#dc2626':'#64748b';
    // Minimum Stock Value — read through the same helper the stock filter and
    // the sort use, so the red low-stock flag and the "Below the MSV" view can
    // never disagree about what counts as below.
    const msv=itemMsv_(it);
    const soq=itemStdOrderQty_(it);
    const below=isBelowMsv_(row);
    return `<tr style="border-bottom:1px solid #f1f5f9;font-size:11px;" data-id="${it.id}">
        <td style="padding:5px 6px;text-align:center;color:#94a3b8;">${i+1}</td>
        <td style="padding:5px 6px;font-weight:700;color:#0369a1;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;" title="${escText(it.item_code)}">${escText(it.item_code)}</td>
        <td style="padding:5px 6px;font-weight:700;">${escText(it.name)}</td>
        <td style="padding:5px 6px;color:#64748b;">${escText(it.description||'—')}</td>
        <td style="padding:5px 6px;">${escText(it.category||'—')}</td>
        <td style="padding:5px 6px;text-align:center;background:#ecfeff;font-weight:700;color:#0e7490;">${escText(itemSize_(it)||'—')}</td>
        <td style="padding:5px 6px;background:#ecfeff;color:#155e75;">${escText(itemMaterial_(it)||'—')}</td>
        <td style="padding:5px 6px;text-align:right;">₹${Number(it.rate||0).toFixed(2)}</td>
        <td style="padding:5px 6px;text-align:center;background:#f5f3ff;font-weight:700;color:#5b21b6;">${itemGst_(it)}%</td>
        <td style="padding:5px 6px;text-align:center;font-weight:700;">${escText(it.uom||'PCS')}</td>
        <td style="padding:5px 6px;color:#64748b;">${escText(it.make||'—')}</td>
        <td style="padding:5px 6px;text-align:center;background:#fffbeb;font-weight:700;color:#92400e;">${msv!=null?q2(msv):'—'}</td>
        <td style="padding:5px 6px;text-align:center;background:#fdf2f8;font-weight:700;color:#9d174d;">${soq!=null?q2(soq):'—'}</td>
        <td style="padding:5px 6px;text-align:center;background:#f0fdf4;font-weight:700;color:#166534;">${q2(inQty)}</td>
        <td style="padding:5px 6px;text-align:center;background:#fef2f2;font-weight:700;color:#dc2626;">${q2(outQty)}</td>
        <td style="padding:5px 6px;text-align:center;background:${below?'#fee2e2':'#eff6ff'};font-weight:800;color:${below?'#b91c1c':balColor};"${below?` title="Balance ${q2(bal)} is below the minimum stock qty of ${q2(msv)}"`:''}>${q2(bal)}${below?' &#9888;':''}</td>
        <td class="im-newpr-col" style="padding:5px 6px;text-align:center;background:#f0fdf4;"><input type="checkbox" class="im-pr-sel" data-id="${it.id}"${sarvItemPrSel.has(String(it.id))?' checked':''}${prAdmin?'':' disabled'} title="${prAdmin?(soq!=null?'New PR me qty '+soq+' (Std Order Qty)':'Std Order Qty set nahi — PR me qty khud bharni hogi'):'Sirf Admin tick kar sakta hai'}" style="width:14px;height:14px;cursor:${prAdmin?'pointer':'not-allowed'};"></td>
        <td style="padding:5px 6px;text-align:center;">
          ${(sarvCan('EDIT')||sarvCan('DELETE'))?`${sarvCan('EDIT')?`<button onclick="editMasterItem('${it.id}')" style="background:#eff6ff;border:1px solid #93c5fd;color:#1d4ed8;border-radius:4px;padding:2px 7px;font-size:10px;cursor:pointer;margin-right:4px;" title="Edit ${escText(it.item_code||'')} — item details badlein">&#9999;&#65039;</button>`:''}${sarvCan('DELETE')?`<button onclick="deleteMasterItem('${it.id}')" style="background:#fef2f2;border:1px solid #fca5a5;color:#dc2626;border-radius:4px;padding:2px 7px;font-size:10px;cursor:pointer;" title="Delete">✕</button>`:''}`:'<span style="color:#cbd5e1;">—</span>'}
        </td>
      </tr>`;
  }).join('');
  // Subtotal row pinned at the top of the item list, above all rows,
  // reflecting whatever the current search/category filter is showing.
  // colspan is 11: the label runs from # through Make. MSV and Standard Order
  // Qty then sit between Make and IN Qty, both unsummed — a minimum stock
  // level and a standard order size are per-item settings, and adding them up
  // across the list would be a number that means nothing.
  const totalsRow=`<tr style="background:#1e293b;color:#fff;font-weight:800;">
      <td colspan="11" style="padding:6px 8px;text-align:right;">SUBTOTAL (${rows.length} shown)</td>
      <td style="padding:6px;text-align:center;background:#78350f;">—</td>
      <td style="padding:6px;text-align:center;background:#831843;">—</td>
      <td style="padding:6px;text-align:center;background:#0c4a3e;">${q2(totalIn)}</td>
      <td style="padding:6px;text-align:center;background:#7c2d12;">${q2(totalOut)}</td>
      <td style="padding:6px;text-align:center;background:#1e3a5f;color:${totalBal<0?'#fca5a5':'#fff'};">${q2(totalBal)}</td>
      <td class="im-newpr-col" style="padding:6px;text-align:center;background:#14532d;" title="Ticked for New PR">${sarvItemPrSel.size||'—'}</td>
      <td></td>
    </tr>`;
  tb.innerHTML=totalsRow+bodyRows;
  sarvSyncItemPrSelUi_();
};
/* ── Item Master → New PR ────────────────────────────────────────────
   The Admin ticks items in the NEW PR column (kept across search / filter /
   re-render) and presses Generate New PR: the PR form opens with one row per
   item, qty = its STD ORDER QTY, and Purchaser Name picked from the item's
   Category (category_purchasers) — the same auto-pick a hand-typed row gets.
   Requested By, Required By and the rest are filled in on the form as usual,
   and nothing is saved until Submit. */
const sarvItemPrSel=new Set();
function sarvSyncItemPrSelUi_(){
  const admin=sarvTabVisible('MD_ITEM_NEWPR'),n=sarvItemPrSel.size;
  const btn=byId('imGenPrBtn'),clr=byId('imPrSelClearBtn'),cnt=byId('imPrSelCount');
  if(btn){btn.style.display=admin?'':'none';btn.disabled=!n;btn.style.opacity=n?'1':'.55';}
  if(clr)clr.style.display=(admin&&n)?'':'none';
  if(cnt)cnt.textContent=n;
  const all=byId('imPrSelAll');
  if(all){
    const boxes=[...document.querySelectorAll('#itemMasterBody .im-pr-sel')];
    all.disabled=!admin;all.style.cursor=admin?'pointer':'not-allowed';
    all.checked=boxes.length>0&&boxes.every(b=>b.checked);
    all.indeterminate=!all.checked&&boxes.some(b=>b.checked);
  }
}
window.sarvClearItemPrSel=function(){sarvItemPrSel.clear();renderItemMasterTable();};
// Defaults for a PR generated from Item Master.
const SARV_GEN_PR_EMP_CODE='1439';   // Requested By
const SARV_GEN_PR_DUE_DAYS=7;        // Required By = today + 7 days
window.sarvGenerateNewPrFromItems=async function(){
  if(!sarvTabVisible('MD_ITEM_NEWPR'))return showToast('⛔ Aapke role ko Item Master se New PR banane ka access nahi hai','warn');
  const picked=sarvItemMasterRows.map(r=>r.it).filter(it=>sarvItemPrSel.has(String(it.id)));
  if(!picked.length)return showToast('Pehle NEW PR column me items tick karein','warn');
  const noSoq=picked.filter(it=>itemStdOrderQty_(it)==null);
  // Open New Entry the way the Home page does, on a clean form.
  sarvNavigateFromHome('PR');
  clearPrForm();
  const tb=byId('p_itemTableBody');if(!tb)return;
  tb.innerHTML='';
  picked.forEach(it=>{
    const tr=addPurchaseMainRow();if(!tr)return;
    const set=(s,v)=>{const e=tr.querySelector(s);if(e)e.value=v??'';};
    // Pinned to this exact Item Master row, so a same-named duplicate can't be bound on save.
    tr.dataset.itemId=it.id;
    set('.col-name',it.name||'');set('.col-desc',it.description||'');set('.col-make',it.make||'');
    set('.col-cat',it.category||'');set('.col-uom',it.uom||'');
    const soq=itemStdOrderQty_(it);set('.col-qty',soq!=null?soq:'');
    const nameEl=tr.querySelector('.col-name');
    if(nameEl){nameEl.readOnly=true;nameEl.style.background='#f1f5f9';nameEl.style.cursor='not-allowed';nameEl.title='Item Master se aaya — badalna ho to row hata kar nayi jodein';}
    // Purchaser by Category — first row fills it, a disagreeing row warns (applyCategoryPurchaser).
    applyCategoryPurchaser(it.category);
  });
  refreshPurchaseTotals();
  sarvItemPrSel.clear();
  // Required By: one week from today (local date, not UTC).
  {
    const d=new Date();d.setDate(d.getDate()+SARV_GEN_PR_DUE_DAYS);
    const z=n=>String(n).padStart(2,'0');
    const due=d.getFullYear()+'-'+z(d.getMonth()+1)+'-'+z(d.getDate());
    const rb=byId('p_requiredByDate');if(rb){rb.value=due;rb.dispatchEvent(new Event('change'));}
  }
  // Requested By: the default Employee Code, filled through the same lookup as typing it.
  {
    const ec=byId('p_reqEmpCode');
    if(ec){
      if(!lookupEmployee(SARV_GEN_PR_EMP_CODE)&&SB_READY){try{await loadEmployeeMaster();}catch(e){}}
      ec.value=SARV_GEN_PR_EMP_CODE;
      onEmpCodeInput(SARV_GEN_PR_EMP_CODE);
      if(!lookupEmployee(SARV_GEN_PR_EMP_CODE))showToast('⚠️ Employee Code '+SARV_GEN_PR_EMP_CODE+' Employee Master me nahi mila — Requested By khud bharein','warn');
    }
  }
  /* Machine: picking it on the FIRST row puts the same machine on every other
     row. A row whose machine was changed by hand (no longer blank / no longer
     the first row's previous pick) is left alone. */
  const genRows=[...tb.querySelectorAll('tr')];
  const firstMc=genRows[0]&&genRows[0].querySelector('.col-machine');
  if(firstMc&&genRows.length>1){
    let prev=firstMc.value||'';
    const copy=()=>{
      const v=String(firstMc.value||'').trim();
      // Only a real Machine Master value is copied — an invalid one is cleared on blur anyway.
      if(v&&sarvMachineCatalog.length&&!machineValidValues_().some(x=>x.toLowerCase()===v.toLowerCase()))return;
      genRows.slice(1).forEach(tr=>{
        const mc=tr.querySelector('.col-machine');if(!mc||!tr.isConnected)return;
        if(!mc.value||mc.value===prev)mc.value=v;
      });
      prev=v;
    };
    firstMc.addEventListener('change',copy);
    firstMc.title='Yahan machine chunte hi neeche ki saari rows me wahi machine lag jayegi';
  }
  showToast('📝 New PR form me '+picked.length+' item(s) bhar diye — qty = Std Order Qty, Purchaser = Category se, Requested By = '+SARV_GEN_PR_EMP_CODE+', Required By = 7 din baad. Pehli row me Machine chunein — sab rows me lag jayegi.');
  if(noSoq.length)showToast('⚠️ In items ka Std Order Qty set nahi tha — qty khud bharein: '+noSoq.map(it=>it.name).slice(0,5).join(', ')+(noSoq.length>5?' …':''),'warn');
};
document.addEventListener('DOMContentLoaded',()=>{
  byId('itemMasterBody')?.addEventListener('change',e=>{
    const cb=e.target.closest('.im-pr-sel');if(!cb)return;
    if(!sarvTabVisible('MD_ITEM_NEWPR')){cb.checked=false;return showToast('⛔ Aapke role ko New PR Generation ka access nahi hai','warn');}
    if(cb.checked)sarvItemPrSel.add(String(cb.dataset.id));else sarvItemPrSel.delete(String(cb.dataset.id));
    // Subtotal cell + button count, without re-rendering (keeps scroll position).
    const sub=byId('itemMasterBody').querySelector('tr td[title="Ticked for New PR"]');if(sub)sub.textContent=sarvItemPrSel.size||'—';
    sarvSyncItemPrSelUi_();
  });
  byId('imPrSelAll')?.addEventListener('click',e=>e.stopPropagation());
  byId('imPrSelAll')?.addEventListener('change',e=>{
    if(!sarvTabVisible('MD_ITEM_NEWPR')){e.target.checked=false;return;}
    // Every item the current search / filters are showing.
    document.querySelectorAll('#itemMasterBody .im-pr-sel').forEach(cb=>{
      cb.checked=e.target.checked;
      if(cb.checked)sarvItemPrSel.add(String(cb.dataset.id));else sarvItemPrSel.delete(String(cb.dataset.id));
    });
    const sub=byId('itemMasterBody').querySelector('tr td[title="Ticked for New PR"]');if(sub)sub.textContent=sarvItemPrSel.size||'—';
    sarvSyncItemPrSelUi_();
  });
});
/* Item Master column resize — Code / Item Name / Description. Drag a header's
   right edge; double-click the edge to go back to the default width. Widths
   are remembered per browser. The table is table-layout:fixed, so a width set
   on the <th> is exactly what the column gets. A drag must not also count as
   a click on the header, or Code / Item Name would re-sort on every resize. */
(function initItemMasterColResize(){
  const KEY='sarv_im_colw', MIN=40;
  let saved={};
  try{saved=JSON.parse(localStorage.getItem(KEY)||'{}')||{};}catch(e){}
  const save=()=>{try{localStorage.setItem(KEY,JSON.stringify(saved));}catch(e){}};
  function init(){
    const table=byId('itemMasterTable');
    if(!table)return;
    let justResized=false;
    // Capture phase runs before the <th>'s own onclick, so the sort is skipped.
    table.addEventListener('click',e=>{if(justResized){e.stopPropagation();e.preventDefault();}},true);
    table.querySelectorAll('th.im-resizable').forEach(th=>{
      const col=th.dataset.col, grip=th.querySelector('.im-col-resizer');
      const defaultW=th.style.width;
      if(saved[col])th.style.width=saved[col]+'px';
      if(!grip)return;
      grip.addEventListener('pointerdown',e=>{
        e.preventDefault(); e.stopPropagation();
        justResized=true;
        const startX=e.clientX, startW=th.getBoundingClientRect().width;
        grip.classList.add('active');
        grip.setPointerCapture(e.pointerId);
        const move=ev=>{th.style.width=Math.max(MIN,Math.round(startW+ev.clientX-startX))+'px';};
        const up=()=>{
          grip.classList.remove('active');
          grip.removeEventListener('pointermove',move);
          grip.removeEventListener('pointerup',up);
          grip.removeEventListener('pointercancel',up);
          saved[col]=parseInt(th.style.width,10); save();
          setTimeout(()=>{justResized=false;},0);
        };
        grip.addEventListener('pointermove',move);
        grip.addEventListener('pointerup',up);
        grip.addEventListener('pointercancel',up);
      });
      grip.addEventListener('dblclick',e=>{
        e.stopPropagation();
        th.style.width=defaultW; delete saved[col]; save();
      });
    });
  }
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init);else init();
})();
/* Several Item Master rows are allowed to carry the SAME name (same part,
   different spec / make / description). A native <datalist> reports which
   option the user picked ONLY through that option's value, so same-named
   options must not share one value — otherwise every pick resolved to
   whichever row happened to come first and filled that row's Description /
   Spec / Category / UOM, no matter which line was chosen in the popup.

   Duplicated names therefore carry their item_code — "BEARING 6204 [BRG-6204-1]"
   — which is the unique handle for an Item Master row. A name that appears
   once stays exactly as it was, so nothing changes for the common case.
   lookupItem() understands both forms, and applyItemAutofill() puts the clean
   name back in the field once the pick has been resolved. */
function itemDropdownValue(it,dupNames){
  const name=String(it&&it.name||'').trim();
  const code=String(it&&it.item_code||'').trim();
  if(!code||!dupNames||!dupNames.has(name.toLowerCase()))return name;
  return name+' ['+code+']';
}
/* Everything an Item Name box is allowed to hold: every master name, plus the
   "NAME [ITEM_CODE]" form the dropdown uses for duplicated names. Without the
   tagged forms the Master Data check on blur would wipe a freshly picked
   duplicate before applyItemAutofill had put the plain name back. */
function itemNameMasterValues(){
  const dup=itemDuplicateNames(sarvItemCatalog),out=[];
  (sarvItemCatalog||[]).forEach(it=>{
    const name=String(it&&it.name||'').trim();
    if(name)out.push(name);
    const tagged=itemDropdownValue(it,dup);
    if(tagged&&tagged!==name)out.push(tagged);
  });
  return out;
}
// Lowercased names that occur more than once in the given item list.
function itemDuplicateNames(items){
  const seen=new Map();
  (items||[]).forEach(it=>{
    const k=String(it&&it.name||'').trim().toLowerCase();
    if(k)seen.set(k,(seen.get(k)||0)+1);
  });
  return new Set([...seen.entries()].filter(([,n])=>n>1).map(([k])=>k));
}
function refreshItemDatalist(items){
  sarvItemCatalog=items; // Keep global cache in sync
  // Inward + Outward + PR item name datalists
  const dupNames=itemDuplicateNames(items);
  ['dl-item-name','dl-out-item-name','p_dl-item-names'].forEach(dlId=>{
    const dl=byId(dlId);if(!dl)return;
    dl.innerHTML=items.map(it=>`<option value="${escText(itemDropdownValue(it,dupNames))}">${escText(it.category||'')} — ${escText(it.description||'')}</option>`).join('');
  });
  /* Make / Brand suggestions, everywhere the field appears. p_dl-item-makes
     is the PR form's list — the datalist has been in the markup all along but
     nothing ever filled it, so the PR's MAKE column was the one place a brand
     had to be typed from memory. */
  const makeSet=[...new Set(items.map(x=>x.make).filter(Boolean))]
    .sort((a,b)=>String(a).localeCompare(String(b),undefined,{numeric:true,sensitivity:'base'}));
  // dl-mi-make is the Item Master form's own box. refreshItemAttributeDatalists_
  // fills it too, but only when that panel loads — doing it here as well means
  // the suggestions are already there the first time the panel is opened.
  ['dl-item-make','dl-out-item-make','p_dl-item-makes','dl-mi-make'].forEach(dlId=>{const dl=byId(dlId);if(!dl)return;dl.innerHTML=makeSet.map(m=>`<option value="${escText(m)}">`).join('');});
}

function refreshSupplierDatalist(suppliers){
  sarvSupplierCatalog=suppliers; // Keep global cache in sync
  // Material Inward "Supplier Name", Material Outward "Party Name", and
  // Build PO "Vendor (M/s)" all draw from the same Supplier Master list.
  ['dl-supplierName','dl-outPartyName','p_vendorDatalist'].forEach(dlId=>{
    const dl=byId(dlId);if(!dl)return;
    dl.innerHTML=suppliers.map(s=>`<option value="${escText(s.supplier_name)}">`).join('');
  });
}

window.loadItemMaster=async function(){
  const tb=byId('itemMasterBody');
  if(!tb)return;
  if(!SB_READY){tb.innerHTML='<tr><td colspan="18" style="text-align:center;padding:20px;color:#f59e0b;">⚠️ Supabase not configured</td></tr>';return;}
  tb.innerHTML='<tr><td colspan="18" style="text-align:center;padding:20px;color:#94a3b8;">⏳ Loading...</td></tr>';
  try{
    const [items,inLines,outLines]=await Promise.all([
      fetchAllRows('items','*','name'),
      fetchAllRows('inward_lines','item_id,qty'),
      fetchAllRows('outward_lines','item_id,qty')
    ]);
    const inMap={},outMap={};
    inLines.forEach(r=>{inMap[r.item_id]=(inMap[r.item_id]||0)+Number(r.qty||0);});
    outLines.forEach(r=>{outMap[r.item_id]=(outMap[r.item_id]||0)+Number(r.qty||0);});
    sarvItemMasterRows=items.map(it=>{
      const inQty=inMap[it.id]||0,outQty=outMap[it.id]||0;
      return {it,inQty,outQty,bal:inQty-outQty,catKey:(it.category&&it.category.trim())?it.category.trim():'(No Category)'};
    });
    /* Column filters deliberately SURVIVE a Refresh. Someone narrowing down to
       one vendor's electricals and then hitting Refresh wants the same view
       back with fresh numbers, not a reset. The chip bar above the table keeps
       saying what is applied, so a filter can never go on quietly hiding rows
       after a reload. A value that no longer exists simply matches nothing —
       the chip is still there to clear. */
    renderItemMasterTable();
    refreshItemDatalist(items);
    refreshItemAttributeDatalists_(items);
  }catch(e){dbError(e);tb.innerHTML='<tr><td colspan="18" style="text-align:center;padding:16px;color:#ef4444;">❌ Error loading items</td></tr>';}
};

/* ── Item Master edit (Admin only) ────────────────────────────────
   Loads an existing item back into the Add New Item form. The Item Code is
   NOT editable: it is the stable handle this item is known by, and nothing
   would be gained by churning it.

   A rename has to reach the records already generated against the item. Two
   different mechanisms carry it:
     • inward_lines, outward_lines and purchase_requirement_lines hold only
       item_id and read the name back through a join, so IN / OUT / PR
       entries — and every report and PDF built from them — pick up the new
       name the moment items.name changes. Nothing to copy.
     • purchase_order_lines is the one table that keeps its own item_name
       copy, so that copy is rewritten explicitly by syncItemNameOnPoLines_.
       That is not cosmetic: the Pending Requirements screen matches PR lines
       to PO lines on req_no + item name, and a stale copy would make an
       already-ordered quantity look available again. */
let sarvEditingItemId=null;
window.editMasterItem=function(id){
  if(!sarvCan('EDIT'))return sarvDeny('EDIT');
  const row=sarvItemMasterRows.find(x=>x.it.id===id);
  const it=row&&row.it;
  if(!it)return showToast('Item data nahi mila — list refresh karein','warn');
  sarvEditingItemId=id;
  const set=(fid,v)=>{const e=byId(fid);if(e)e.value=v==null?'':v;};
  set('mi_itemName',it.name);
  set('mi_itemDesc',it.description);
  set('mi_minStockQty',it.sub_category);
  set('mi_rate',it.rate!=null?it.rate:0);
  set('mi_make',it.make);
  // Read through the helpers, so an item saved before these columns existed
  // loads as blank instead of as the string "undefined".
  set('mi_itemSize',itemSize_(it));
  set('mi_materialType',itemMaterial_(it));
  set('mi_stdOrderQty',itemStdOrderQty_(it));
  // A category or UOM that isn't one of the listed options would silently land
  // on the first option, so anything unknown is added to the dropdown first.
  ensureSelectOption_('mi_category',it.category);
  ensureSelectOption_('mi_uom',it.uom||'PCS');
  ensureSelectOption_('mi_gst',String(itemGst_(it)));
  set('mi_category',it.category||'');
  set('mi_uom',it.uom||'PCS');
  set('mi_gst',String(itemGst_(it)));
  const head=byId('mi_formHeading');
  if(head)head.innerHTML='&#9999;&#65039; Editing Item — <span style="color:#b45309;">'+escText(it.item_code||'')+'</span>';
  const btn=byId('addItemBtn');if(btn)btn.innerHTML='&#128190; Update Item';
  const cancel=byId('mi_cancelEditBtn');if(cancel)cancel.style.display='';
  // The form may be collapsed — an edit that filled fields nobody could see
  // would look like the Edit button did nothing. Opened without remembering,
  // so the user's normal preference survives the edit (cancelItemEdit puts it
  // back).
  setAddItemForm(true,false);
  byId('mi_itemName')?.scrollIntoView({behavior:'smooth',block:'center'});
  showToast('✏️ '+(it.item_code||it.name)+' edit ke liye khula — badlaav karke Update Item dabayein');
};
// Keeps a value that isn't in a <select>'s option list from being silently
// dropped when an existing record is loaded into the form.
function ensureSelectOption_(selId,val){
  const sel=byId(selId),v=String(val||'').trim();
  if(!sel||!v)return;
  if([...sel.options].some(o=>o.value===v))return;
  const opt=document.createElement('option');
  opt.value=v;opt.textContent=v;
  sel.appendChild(opt);
}
window.cancelItemEdit=function(){
  sarvEditingItemId=null;
  ['mi_itemName','mi_itemDesc','mi_minStockQty','mi_make','mi_itemSize','mi_materialType','mi_stdOrderQty']
    .forEach(id=>{const e=byId(id);if(e)e.value='';});
  if(byId('mi_rate'))byId('mi_rate').value='0';
  if(byId('mi_uom'))byId('mi_uom').value='PCS';
  if(byId('mi_category'))byId('mi_category').value='';
  const head=byId('mi_formHeading');if(head)head.innerHTML='&#10133; Add New Item';
  const btn=byId('addItemBtn');if(btn)btn.innerHTML='&#10133; Add Item';
  const cancel=byId('mi_cancelEditBtn');if(cancel)cancel.style.display='none';
  // Back to however the user normally keeps the form — editMasterItem opened it
  // without remembering, so this is what undoes that.
  initAddItemForm_();
};

/* Rewrites the item_name copy that purchase_order_lines keeps. Rows are matched
   by item_id, plus — for PO lines typed in by hand, which carry no item_id —
   by the old name. Returns how many rows were rewritten. */
async function syncItemNameOnPoLines_(itemId,oldName,newName){
  let touched=0;
  const byItemId=await SB.from('purchase_order_lines').update({item_name:newName}).eq('item_id',itemId).select('id');
  if(byItemId.error)throw byItemId.error;
  touched+=(byItemId.data||[]).length;
  if(oldName){
    const byName=await SB.from('purchase_order_lines').update({item_name:newName}).is('item_id',null).eq('item_name',oldName).select('id');
    if(byName.error)throw byName.error;
    touched+=(byName.data||[]).length;
  }
  return touched;
}

window.addMasterItem=async function(){
  const name=(byId('mi_itemName')?.value||'').trim().toUpperCase();
  if(!name){showToast('❌ Item Name required!','error');byId('mi_itemName')?.focus();return;}
  if(!SB_READY){showToast('Supabase configure karein','warn');return;}
  const editingId=sarvEditingItemId;
  if(editingId&&!sarvCan('EDIT'))return sarvDeny('EDIT');
  if(!editingId&&!sarvGuard('ADD_ITEM'))return;
  const before=editingId?sarvItemMasterRows.find(x=>x.it.id===editingId):null;
  const oldName=before?.it?.name||'';
  const code=before?.it?.item_code||'';
  const btn=byId('addItemBtn');
  if(btn){btn.disabled=true;btn.textContent=editingId?'⏳ Updating...':'⏳ Saving...';}
  try{
    // The name has to stay unique: the entry forms match typed item names back
    // to the master, and the Item Master pools balances by name, so two rows
    // sharing a name would merge two different items' stock.
    //
    // The check guards a NAME CHANGE, not a save. Editing only the description
    // or the MSV leaves the name alone, and an item must always be able to
    // re-save under the name it already carries — including where the database
    // still holds older duplicates of that name, which would otherwise make the
    // item permanently uneditable.
    const nameChanged=!editingId||oldName.trim().toUpperCase()!==name;
    if(nameChanged){
      // limit(1) rather than maybeSingle(): with pre-existing duplicates
      // maybeSingle() fails with a row-count error instead of this clear message.
      let chkQ=SB.from('items').select('id,name').ilike('name',name).limit(1);
      if(editingId)chkQ=chkQ.neq('id',editingId);
      const chk=await chkQ;
      if(chk.error)throw chk.error;
      if((chk.data||[]).length){showToast(`⚠️ "${name}" already exists in Item Master!`,'warn');return;}
    }
    const payload={
      name:name,
      description:(byId('mi_itemDesc')?.value||'').trim()||null,
      category:byId('mi_category')?.value||null,
      // Minimum Stock Value. Kept in the legacy sub_category column because
      // that is where every existing item's MSV already lives — renaming the
      // column would need a migration and would orphan that data.
      sub_category:(byId('mi_minStockQty')?.value||'').trim()||null,
      rate:Number(byId('mi_rate')?.value||0),
      uom:(byId('mi_uom')?.value||'PCS').trim()||'PCS',
      make:(byId('mi_make')?.value||'').trim()||null,
      // Per-item GST. Dropped and retried without it if the column is not in
      // the database yet (see the catch below), so this save never fails on a
      // schema that predates it.
      gst_pct:Number(byId('mi_gst')?.value||SARV_DEFAULT_GST),
      /* Size / Material / Standard Order Qty — columns of their OWN, unlike
         MSV, which still rides in the legacy sub_category. These are new, so
         there is no existing data to orphan and no reason to overload a
         column. Each is dropped-and-retried by saveItemRow_ on a database
         where ITEM_MASTER_FIELDS_MIGRATION.sql has not been run yet.
         Blank saves as NULL, not as '' or 0 — "not recorded" and "zero" are
         different answers, and only NULL reads back as the first one. */
      item_size:(byId('mi_itemSize')?.value||'').trim()||null,
      material_type:(byId('mi_materialType')?.value||'').trim()||null,
      std_order_qty:(byId('mi_stdOrderQty')?.value||'').trim()===''?null:Number(byId('mi_stdOrderQty').value)
    };
    if(editingId){
      // item_code is deliberately left out of the payload — it is the handle
      // this item is known by and does not follow a rename.
      const {error,dropped}=await saveItemRow_(payload,editingId);
      if(error)throw error;
      warnItemColumnsMissing_(dropped);
      const renamed=!!oldName&&oldName.trim().toUpperCase()!==name;
      // IN / OUT / PR lines point at item_id and read the name back through a
      // join, so they already show the new name — nothing to copy there. Only
      // purchase_order_lines keeps its own item_name, and that copy is
      // rewritten on EVERY save, not just a rename: writing the current name
      // over the current name costs nothing, makes re-saving the item a real
      // repair step if this ever fails, and heals any older drift.
      //
      // It runs after the rename is already committed and the client has no
      // transaction spanning the two, so a failure is reported as what it is —
      // a half-applied rename with a named next step — never swallowed.
      let poCount=0, poFailed=null;
      try{ poCount=await syncItemNameOnPoLines_(editingId,oldName,name); }
      catch(poErr){ console.error('[SARV] PO line name sync failed:',poErr); poFailed=poErr; }
      if(poFailed){
        showToast(`⚠️ ${code||name} save ho gaya${renamed?` ("${oldName}" → "${name}")`:''}, lekin purane PO lines ka naam update nahi hua`
          +` (${poFailed.message||poFailed}). Isi item ko dobara Update Item karein — wo PO lines ko phir se sync karega.`,'warn');
      }else if(renamed){
        showToast(`✅ "${oldName}" → "${name}" — IN / OUT / PR entries automatic naye naam se dikhengi`
          +(poCount?`, ${poCount} PO line(s) bhi update ki gayin`:''));
      }else{
        showToast(`✅ ${code||name} updated`);
      }
      cancelItemEdit();
    }else{
      const newCode=(name.replace(/[^A-Z0-9]+/g,'-').replace(/^-|-$/g,'').slice(0,28)||'ITEM')+'-'+String(Date.now()).slice(-4);
      const {error,dropped}=await saveItemRow_({item_code:newCode,...payload},null);
      if(error)throw error;
      warnItemColumnsMissing_(dropped);
      showToast(`✅ "${name}" added to Item Master!`);
      cancelItemEdit();   // same field reset the add path always did
    }
    await loadItemMaster();
  }catch(e){dbError(e);}
  finally{
    if(btn){
      btn.disabled=false;
      // cancelItemEdit() has already restored the label on the success path;
      // on a failure the form must still read "Update Item".
      btn.innerHTML=sarvEditingItemId?'&#128190; Update Item':'&#10133; Add Item';
    }
  }
};

window.deleteMasterItem=async function(id){
  if(!sarvCan('DELETE'))return sarvDeny('DELETE');
  if(!confirm('Ye item delete karein?\n\n⚠️ Agar kisi Inward/Outward entry se linked hai toh error aayega.'))return;
  if(!SB_READY)return;
  const{error}=await SB.from('items').delete().eq('id',id);
  if(error){
    if(error.code==='23503')showToast('❌ Delete nahi ho sakta — Inward/Outward entries se linked hai','error');
    else dbError(error);
    return;
  }
  showToast('🗑️ Item deleted');
  await loadItemMaster();
};

/* ================================================================
   MASTER DATA — Supplier Master (Full Implementation)
================================================================ */
/* Every suppliers column except pin_hash, which the anon key may not read.
   Used anywhere the old code said select('*'). */
const SARV_SUPPLIER_COLS='id,supplier_code,supplier_name,contact_person,phone,email,gst_no,state,city,created_at';
window.loadSupplierMaster=async function(){
  const tb=byId('supplierMasterBody'),cnt=byId('supplierMasterCount');
  if(!tb)return;
  if(!SB_READY){tb.innerHTML='<tr><td colspan="11" style="text-align:center;padding:20px;color:#f59e0b;">⚠️ Supabase not configured</td></tr>';return;}
  tb.innerHTML='<tr><td colspan="11" style="text-align:center;padding:20px;color:#94a3b8;">⏳ Loading...</td></tr>';
  try{
    // Columns are listed explicitly rather than '*' because pin_hash is no
    // longer readable by this key — selecting it would fail the whole query.
    // Whether a vendor HAS a PIN comes from an RPC instead, which answers the
    // question without handing over the hash.
    const{data,error}=await SB.from('suppliers').select(SARV_SUPPLIER_COLS).order('supplier_name');
    if(error)throw error;
    sarvSupplierMasterRows=data||[];
    try{
      const p=await SB.rpc('suppliers_with_pin');
      if(!p.error){
        const hasPin=new Map((p.data||[]).map(r=>[r.id,!!r.has_pin]));
        sarvSupplierMasterRows.forEach(s=>{s.has_pin=hasPin.get(s.id)===true;});
      }
    }catch(e){console.warn('[SARV] supplier PIN flags skipped:',e.message||e);}
    // Refresh supplier datalists everywhere a supplier/vendor name is picked.
    // Driven by the full set, never by what the search box is showing.
    refreshSupplierDatalist(sarvSupplierMasterRows);
    renderSupplierMasterTable();
  }catch(e){
    if(e?.message?.includes('does not exist')||e?.code==='42P01'){
      tb.innerHTML='<tr><td colspan="11" style="text-align:center;padding:20px;color:#f59e0b;">⚠️ Suppliers table missing — SQL patch run karein</td></tr>';
    }else{dbError(e);tb.innerHTML='<tr><td colspan="11" style="text-align:center;padding:16px;color:#ef4444;">❌ Error loading suppliers</td></tr>';}
  }
};
window.renderSupplierMasterTable=function(){
  const tb=byId('supplierMasterBody'),cnt=byId('supplierMasterCount');
  if(!tb)return;
  const q=(byId('supplierMasterSearch')?.value||'').toLowerCase().trim();
  const rows=!q?sarvSupplierMasterRows:sarvSupplierMasterRows.filter(s=>
    [s.supplier_code,s.supplier_name,s.contact_person,s.phone,s.gst_no,s.state,s.city]
      .map(x=>String(x||'').toLowerCase()).join(' ').includes(q));
  if(cnt)cnt.textContent=q?rows.length+' of '+sarvSupplierMasterRows.length+' suppliers':rows.length+' suppliers';
  if(!sarvSupplierMasterRows.length){tb.innerHTML='<tr><td colspan="11" style="text-align:center;padding:20px;color:#94a3b8;">No suppliers yet — Add your first supplier above ⬆️</td></tr>';return;}
  if(!rows.length){tb.innerHTML='<tr><td colspan="11" style="text-align:center;padding:20px;color:#94a3b8;">No supplier matches this search.</td></tr>';return;}
  tb.innerHTML=rows.map((s,i)=>`<tr style="border-bottom:1px solid #f1f5f9;font-size:11px;">
      <td style="padding:5px 6px;text-align:center;color:#94a3b8;">${i+1}</td>
      <td style="padding:5px 6px;font-weight:700;color:#0369a1;">${escText(s.supplier_code||'—')}</td>
      <td style="padding:5px 6px;font-weight:700;">${escText(s.supplier_name)}</td>
      <td style="padding:5px 6px;color:#64748b;">${escText(s.contact_person||'—')}</td>
      <td style="padding:5px 6px;">${escText(s.phone||'—')}</td>
      <td style="padding:5px 6px;font-size:10px;">${escText(s.gst_no||'—')}</td>
      <td style="padding:5px 6px;">${escText(s.state||'—')}</td>
      <td style="padding:5px 6px;">${escText(s.city||'—')}</td>
      <td style="padding:5px 6px;text-align:center;">${isAdmin()?`<button onclick="setSupplierPin('${s.id}','${escText(s.supplier_name).replace(/'/g,"\\'")}')" style="background:${s.has_pin?'#eff6ff':'#fef9c3'};border:1px solid ${s.has_pin?'#93c5fd':'#fde68a'};color:${s.has_pin?'#1d4ed8':'#92400e'};border-radius:4px;padding:2px 7px;font-size:10px;cursor:pointer;" title="${s.has_pin?'Change vendor login PIN':'Set vendor login PIN'}">${s.has_pin?'🔑 Change':'🔑 Set'}</button>`:(s.has_pin?'<span style="color:#16a34a;" title="PIN set">✓ Set</span>':'<span style="color:#cbd5e1;">—</span>')}</td>
      <td style="padding:5px 6px;text-align:center;">${sarvCan('EDIT')?`<button onclick="editMasterSupplier('${s.id}')" style="background:#eff6ff;border:1px solid #93c5fd;color:#1d4ed8;border-radius:4px;padding:2px 7px;font-size:10px;cursor:pointer;" title="Edit supplier details">&#9999;&#65039;</button>`:'<span style="color:#cbd5e1;">—</span>'}</td>
      <td style="padding:5px 6px;text-align:center;">${sarvCan('DELETE')?`<button onclick="deleteMasterSupplier('${s.id}')" style="background:#fef2f2;border:1px solid #fca5a5;color:#dc2626;border-radius:4px;padding:2px 7px;font-size:10px;cursor:pointer;" title="Delete">✕</button>`:'<span style="color:#cbd5e1;">—</span>'}</td>
    </tr>`).join('');
};

let sarvEditingSupplierId=null;
window.editMasterSupplier=function(id){
  if(!sarvCan('EDIT'))return sarvDeny('EDIT');
  const s=sarvSupplierCatalog.find(x=>x.id===id);
  if(!s)return showToast('Supplier data nahi mila — list refresh karein','warn');
  sarvEditingSupplierId=id;
  const set=(fid,v)=>{const e=byId(fid);if(e)e.value=v||'';};
  set('ms_supplierName',s.supplier_name);set('ms_contactPerson',s.contact_person);set('ms_phone',s.phone);
  set('ms_email',s.email);set('ms_gstNo',s.gst_no);set('ms_city',s.city);
  if(byId('ms_state'))byId('ms_state').value=s.state||'HARYANA (LOCAL)';
  const pinEl=byId('ms_vendorPin');if(pinEl){pinEl.value='';pinEl.placeholder=s.has_pin?'leave blank to keep existing PIN':'optional — 4+ digits';}
  const saveBtn=byId('ms_saveBtn');if(saveBtn)saveBtn.innerHTML='💾 Update Supplier';
  if(byId('ms_cancelEditBtn'))byId('ms_cancelEditBtn').style.display='';
  byId('ms_supplierName')?.scrollIntoView({behavior:'smooth',block:'center'});
  showToast('Editing "'+s.supplier_name+'" — badlaav karke Update Supplier dabayein');
};
window.cancelSupplierEdit=function(){
  sarvEditingSupplierId=null;
  ['ms_supplierName','ms_contactPerson','ms_phone','ms_email','ms_gstNo','ms_city','ms_vendorPin'].forEach(id=>{const e=byId(id);if(e)e.value='';});
  if(byId('ms_state'))byId('ms_state').value='HARYANA (LOCAL)';
  const pinEl=byId('ms_vendorPin');if(pinEl)pinEl.placeholder='optional — 4+ digits';
  const saveBtn=byId('ms_saveBtn');if(saveBtn)saveBtn.innerHTML='&#10133; Add Supplier';
  if(byId('ms_cancelEditBtn'))byId('ms_cancelEditBtn').style.display='none';
};
window.addMasterSupplier=async function(){
  const name=(byId('ms_supplierName')?.value||'').trim().toUpperCase();
  if(!name){showToast('❌ Supplier Name required!','error');byId('ms_supplierName')?.focus();return;}
  if(!SB_READY){showToast('Supabase configure karein','warn');return;}
  const editingId=sarvEditingSupplierId;
  if(editingId&&!sarvCan('EDIT'))return sarvDeny('EDIT');
  if(!editingId&&!sarvGuard('ADD_SUPPLIER'))return;
  try{
    const pin=(byId('ms_vendorPin')?.value||'').trim();
    const payload={
      supplier_name:name,
      contact_person:(byId('ms_contactPerson')?.value||'').trim()||null,
      phone:(byId('ms_phone')?.value||'').trim()||null,
      email:(byId('ms_email')?.value||'').trim()||null,
      gst_no:(byId('ms_gstNo')?.value||'').trim().toUpperCase()||null,
      state:byId('ms_state')?.value||'HARYANA (LOCAL)',
      city:(byId('ms_city')?.value||'').trim().toUpperCase()||null
    };
    // pin_hash is deliberately NOT part of the payload — that column is not
    // writable with this key. A typed PIN goes through set_supplier_pin()
    // below, which authorises the write with the Admin PIN on the server.
    let supplierId=editingId;
    if(editingId){
      const{error}=await SB.from('suppliers').update(payload).eq('id',editingId);
      if(error)throw error;
      showToast(`✅ "${name}" updated in Supplier Master!`);
      cancelSupplierEdit();
    }else{
      const code='SUP-'+name.replace(/[^A-Z0-9]+/g,'-').replace(/^-|-$/g,'').slice(0,20)+'-'+String(Date.now()).slice(-4);
      payload.supplier_code=code;
      const{data,error}=await SB.from('suppliers').insert(payload).select('id').single();
      if(error)throw error;
      supplierId=data?.id||null;
      showToast(`✅ "${name}" added to Supplier Master!`);
      ['ms_supplierName','ms_contactPerson','ms_phone','ms_email','ms_gstNo','ms_city','ms_vendorPin'].forEach(id=>{const e=byId(id);if(e)e.value='';});
    }
    if(pin&&supplierId)await applySupplierPin_(supplierId,pin,name);
    await loadSupplierMaster();
  }catch(e){
    if(e?.message?.includes('does not exist')||e?.code==='42P01')showToast('❌ Suppliers table missing — SQL patch run karein','error');
    else dbError(e);
  }
};
window.setSupplierPin=async function(id,name){
  if(!isAdmin())return showToast('⛔ Sirf Admin login vendor PIN set kar sakta hai','warn');
  if(!SB_READY)return;
  // Same reason as verifyEditPassword: window.prompt() is blocked in embedded
  // hosts, so this went through askSecret's modal too.
  const pin=await askSecret({
    title:'Vendor Login PIN',
    subtitle:'Set / change the mobile approval PIN (4+ digits)',
    recordInfo:'Vendor: '+name,
    label:'New PIN',
    confirmText:'&#128273; Save PIN',
  });
  if(pin==null)return;
  if(!pin.trim())return showToast('PIN khali nahi ho sakta','warn');
  try{
    if(await applySupplierPin_(id,pin.trim(),name))await loadSupplierMaster();
  }catch(e){dbError(e);}
};

/* Writes a vendor's login PIN through set_supplier_pin(), which hashes it and
   authorises the write with the Admin PIN server-side. The hash is never
   computed in, or sent from, this page. Returns true on success. */
async function applySupplierPin_(supplierId,pin,name){
  const adminPin=await askSecret({
    title:'Admin PIN Confirm Karein',
    subtitle:'Vendor PIN set karna server par Admin PIN se authorise hota hai',
    recordInfo:'Vendor: '+(name||'—'),
    label:'Admin PIN',
    confirmText:'&#128273; Confirm &amp; Save PIN'
  });
  if(adminPin==null)return false;                  // cancelled
  if(!adminPin.trim()){showToast('Admin PIN khali nahi ho sakta','warn');return false;}
  const r=await SB.rpc('set_supplier_pin',{p_supplier_id:supplierId,p_new_pin:pin,p_admin_pin:adminPin.trim()});
  if(r.error){dbError(r.error);return false;}
  if(!r.data){showToast('❌ Admin PIN galat hai — vendor PIN save nahi hua','error');return false;}
  showToast('✅ PIN updated for '+(name||'vendor'));
  return true;
}

