/* ================================================================
   MASTER DATA — Machine Master (Full Implementation)
================================================================ */
let sarvMachineCatalog=[]; // Global machine cache — feeds the Machine Name datalist

/* A machine is Machine Name + Machine No. (the pair is unique; one name can
   have several numbers), so every pick-list shows "NAME | NO." and a pick
   fills both halves. Only active Machine Master rows are offered, and no
   machine field anywhere accepts anything that is not on that list. */
const machineCombo_=m=>{const n=String(m.machine_name||'').trim(),no=String(m.machine_no||'').trim();return no?n+' | '+no:n;};
const machineKey_=v=>String(v||'').trim().toLowerCase();
function findMachine_(val){const v=machineKey_(val);return v?sarvMachineCatalog.find(m=>machineKey_(machineCombo_(m))===v)||null:null;}
function machinesByName_(name){const v=machineKey_(name);return v?sarvMachineCatalog.filter(m=>machineKey_(m.machine_name)===v):[];}
function machinesByNo_(no){const v=machineKey_(no);return v?sarvMachineCatalog.filter(m=>machineKey_(m.machine_no)===v):[];}
// Valid text for a single "Machine" box: the "NAME | NO." pick, or a bare name.
function machineValidValues_(){return [...new Set(sarvMachineCatalog.flatMap(m=>[machineCombo_(m),String(m.machine_name||'').trim()]))];}
function refreshMachineDatalist(machines){
  sarvMachineCatalog=(machines||[]).filter(m=>m&&m.is_active!==false&&String(m.machine_name||'').trim());
  const dl=byId('dl-inw-machine-name');
  if(dl)dl.innerHTML=sarvMachineCatalog.map(m=>`<option value="${escText(machineCombo_(m))}"></option>`).join('');
}
// A single "Machine" box (PR rows, Inward) — list only. Until the Machine
// Master has loaded there is nothing to check against, so it is not blanked.
function lockMachineField_(el){
  if(!el)return;
  el.setAttribute('list','dl-inw-machine-name');el.autocomplete='off';
  lockToMasterList(el,()=>sarvMachineCatalog.length?machineValidValues_():[el.value]);
}
/* Machine Name + Machine No. pair on an Issue row. Picking "NAME | NO." in
   either box fills both; typing a name that has only one machine, or a number
   that belongs to only one, fills the other box too. On leaving a box the
   pair must exist in Machine Master — otherwise it is cleared. */
function attachMachinePair_(tr,nameSel,noSel){
  const nameEl=tr.querySelector(nameSel),noEl=tr.querySelector(noSel);
  if(!nameEl||!noEl||nameEl.dataset.machinePair)return;
  nameEl.dataset.machinePair='1';
  [nameEl,noEl].forEach(el=>{el.setAttribute('list','dl-inw-machine-name');el.autocomplete='off';});
  const put=m=>{nameEl.value=String(m.machine_name||'').trim();noEl.value=String(m.machine_no||'').trim();};
  const resolve=el=>{
    const m=findMachine_(el.value);if(m){put(m);return true;}
    const list=el===nameEl?machinesByName_(el.value):machinesByNo_(el.value);
    if(list.length===1){put(list[0]);return true;}
    return false;
  };
  [nameEl,noEl].forEach(el=>{
    el.addEventListener('input',()=>{if(findMachine_(el.value))resolve(el);});
    el.addEventListener('change',()=>resolve(el));
  });
  nameEl.addEventListener('blur',()=>{
    if(!sarvMachineCatalog.length)return;
    const v=nameEl.value.trim();
    if(!v){noEl.value='';return;}
    if(findMachine_(v)){resolve(nameEl);return;}
    if(!machinesByName_(v).length){
      nameEl.value='';noEl.value='';
      showToast('❌ Machine "'+escText(v)+'" Machine Master me nahi hai — list se hi select karein','warn');
    }
  });
  noEl.addEventListener('blur',()=>{
    if(!sarvMachineCatalog.length)return;
    const no=noEl.value.trim();if(!no)return;
    if(findMachine_(no)){resolve(noEl);return;}
    const n=nameEl.value.trim();
    if(!n){if(!resolve(noEl)){noEl.value='';showToast('❌ Machine No. "'+escText(no)+'" Machine Master me nahi hai — list se hi select karein','warn');}return;}
    if(!sarvMachineCatalog.some(m=>machineKey_(m.machine_name)===machineKey_(n)&&machineKey_(m.machine_no)===machineKey_(no))){
      noEl.value='';
      showToast('❌ "'+escText(n)+'" ki Machine No. "'+escText(no)+'" Machine Master me nahi hai — list se hi select karein','warn');
    }
  });
}

