   const artifact=await uploadPdfArtifact(blob,'REQUIREMENT',d.reqNo,'REQUIREMENT');artifact.html=html;await indexPdfArtifact('REQUIREMENT',recordId,d.reqNo,'REQUIREMENT',artifact);sarvPdfState.current={kind:'REQUIREMENT',data:d,items:d.items,result:{REQUIREMENT:artifact}};
