 async function saveOutwardWithPdf_(){
   if(!SB_READY)return showToast('Supabase URL/key configure karein','warn');
   // Target Return Date is hidden on an ISSUE (consumables don't come back),
   // so it is only a required field while the form is an OUTWARD.
   const outReq=[{id:'outPartyName',label:'Party Name'},{id:'outLocation',label:'Location'}];
   if(pVal('outEntryTypeSelect')!=='ISSUE'){
     outReq.push({id:'outTargetReturnDate',label:'Target Return Date'});
     // The dropdown opens unselected on OUTWARD, so the pick has to be checked
     // here — nothing else stops a blank Nature of Dispatch from being saved.
     outReq.push({id:'outNatureOfDispatch',label:'Nature of Dispatch'});
   }
   if(!validateRequiredFields(outReq))return;
   /* Receiver Name / Department carry a ★ but were never actually checked. They
      are read-only now, so an empty one means no employee was picked — and the
      field itself can't be fixed, the Emp Code box can. That is what gets
      highlighted and focused. */
   {
     const missing=[{id:'outReceiverName',label:'Receiver Name'},{id:'outDepartment',label:'Department'}]
       .filter(f=>!pVal(f.id).trim());
     if(missing.length){
       missing.forEach(f=>highlightRequiredField(f.id));
       const code=byId('outReceiverEmpCode');
       if(code){highlightRequiredField('outReceiverEmpCode');code.scrollIntoView({behavior:'smooth',block:'center'});code.focus();}
       return showToast('⚠️ Receiver '+missing.map(f=>f.label).join(' / ')
         +' khaali hai — Emp Code box me employee ka code daalein, teeno field khud bhar jayenge','warn');
     }
   }
   const rows=rowDataOutward();if(!rows.length)return showToast('At least one outward item required','warn');
   // Same bill-already-in-the-system check the Inward save runs, keyed on party
   // + date + gate pass instead of supplier + invoice.
   if(!await guardStoreDuplicate_('OUTWARD',rows,sarvEditingOutwardId))return;
   // ISSUE: every item row must name the machine it is issued to — Machine
   // Name AND Machine No., as a pair that exists in Machine Master. Missing /
   // unknown ones are outlined red and nothing is saved until they're picked.
   if(pVal('outEntryTypeSelect')==='ISSUE'){
     const bad=[];
     pRows('#outwardItemTableBody tr').forEach(tr=>{
       const nm=(tr.querySelector('.out-item-name')?.value||'').trim(),qty=pNum(tr.querySelector('.out-qty')?.value);
       if(!nm||!(qty>0))return;
       const mn=tr.querySelector('.out-machine-name'),mo=tr.querySelector('.out-machine-no');
       const n=(mn?.value||'').trim(),no=(mo?.value||'').trim();
       const known=!sarvMachineCatalog.length||sarvMachineCatalog.some(m=>machineKey_(m.machine_name)===machineKey_(n)&&machineKey_(m.machine_no)===machineKey_(no));
       [mn,mo].forEach(el=>{if(el){el.style.border='';el.style.background='';}});
       if(!n||!no||!known){
         if(mn&&(!n||!known)){mn.style.border='2px solid #dc2626';mn.style.background='#fef2f2';}
         if(mo&&(!no||!known)){mo.style.border='2px solid #dc2626';mo.style.background='#fef2f2';}
         [mn,mo].forEach(el=>el&&el.addEventListener('input',function(){mn.style.border='';mn.style.background='';mo.style.border='';mo.style.background='';},{once:true}));
         bad.push({tr,nm,why:(!n||!no)?'Machine Name / No. khaali':'Machine Master me nahi'});
       }
     });
     if(bad.length){
       const f=bad[0].tr.querySelector((bad[0].tr.querySelector('.out-machine-name')?.value||'').trim()?'.out-machine-no':'.out-machine-name');
       f?.scrollIntoView({block:'nearest',behavior:'smooth'});f?.focus();
       return showToast('⚠️ ISSUE ke liye har item par Machine Name & Machine No. (Machine Master list se) zaroori hai:<br>'+bad.map(b=>'• '+escText(b.nm)+' — '+b.why).join('<br>'),'warn');
     }
   }
   // Stock guard runs before ANY write — a blocked entry must leave no
   // outward_entries header behind.
   showOutStockWarning(null);
   // Editing an existing record? Its own lines are still in outward_lines, so
   // they are excluded from the stock check — otherwise the entry would be
   // counted against itself and every re-save would look short.
   const outEditId=sarvEditingOutwardId, outEditNo=sarvEditingOutwardNo;
   // Entry Type OUTWARD is allowed to go out whatever the balance — even if it
   // takes the item's Bal Qty negative. Only ISSUE is held to stock on hand.
   if(pVal('outEntryTypeSelect')!=='OUTWARD')try{
     const short=await outwardStockShortfalls(rows,outEditId);
     if(short.length){
       showOutStockWarning(short);
       showToast('⛔ '+short.map(s=>escText(s.name)+': STOCK QTY '+nNum_(s.stock)+' &lt; OUT QTY '+nNum_(s.want)).join('<br>')+'<br><b>PLEASE INWARD FIRST</b>','error');
       return;
     }
   }catch(e){
     // A stock lookup that can't run must not silently allow the dispatch.
     console.error('[SARV] Stock check failed:',e);
     showToast('Stock check nahi ho paaya — entry rok di gayi: '+(e.message||e),'error');
     return;
   }
   const overlay=byId('syncOverlay'),msgEl=byId('syncOverlayText'),btn=byId('outSubmitBtn');
   if(btn&&btn.disabled)return; // already processing — ignore double-click
   if(btn)btn.disabled=true; // no second submit while the preview is open
   const okToSave=await confirmStoreEntryPreview('OUTWARD',collectOutwardData(outEditId?outEditNo:'(Auto on Submit)'),rows);
   if(btn)btn.disabled=false;
   if(!okToSave)return;
   // The submitter's own PIN, every time — it is also what signs the PDF. Cancel = nothing saved.
   const outSign=await sarvSubmitPinGate_(outEditId?('Update '+outEditNo):('Submit '+(pVal('outEntryTypeSelect')||'Outward')));
   if(!outSign)return;
   sarvPendingStoreSign=outSign;
   if(btn){btn.disabled=true;btn.dataset.origLabel=btn.textContent;btn.textContent=outEditId?'⏳ Updating...':'⏳ Saving...';}
   if(overlay){if(msgEl)msgEl.textContent=outEditId?('Updating '+outEditNo+'…'):'Saving Outward entry…';overlay.classList.add('active');}
   try{
     // On an edit the record keeps the number it already has — nextNo() would
     // hand out a fresh one and leave the original orphaned.
     const no=outEditId?outEditNo:await nextNo(pVal('outEntryTypeSelect')==='ISSUE'?'ISSUE':'OUTWARD');
     const outBase={document_no:no,entry_type:pVal('outEntryTypeSelect')||'OUTWARD',outward_date:pVal('outDate')||today(),party_name:pVal('outPartyName')||'Unknown',location:pVal('outLocation')||null,receiver_name:pVal('outReceiverName')||null,target_return_date:pVal('outTargetReturnDate')||null,gate_pass_no:pVal('outGatePassNo')||null,transport:pVal('outTransport')||null,notes:pVal('outRemarks')||null};
     /* Receiver Designation / Department / Emp Code used to live only inside the
        PDF, so reopening an entry for edit brought back a bare Receiver Name and
        the other two printed blank on the regenerated copy. They are stored on
        the header now. A database still missing the columns falls back to
        outBase below, exactly as nature_of_dispatch / lot_no already do. */
     const outFull={...outBase,nature_of_dispatch:pVal('outNatureOfDispatch')||null,lot_no:pVal('outLotNo')||null,
       receiver_designation:pVal('outDesignation')||null,receiver_department:pVal('outDepartment')||null,
       receiver_emp_code:pVal('outReceiverEmpCode')||null};
     /* Shapes to try, widest first. The middle one matters: a database that has
        nature_of_dispatch / lot_no but not the new receiver columns must not be
        dropped all the way to outBase, or Nature of Dispatch would silently stop
        being saved and Repair dispatches would vanish from the Repair Tracker. */
     const outNoReceiver={...outFull};
     ['receiver_designation','receiver_department','receiver_emp_code'].forEach(k=>delete outNoReceiver[k]);
     const outShapes=[outFull,outNoReceiver,outBase];
     const isColErr=e=>/nature_of_dispatch|lot_no|receiver_designation|receiver_department|receiver_emp_code|column/i.test(e?.message||'');
     // Walks the shapes until one is accepted; a non-column error stops at once.
     let outShapeUsed=0;
     async function writeOutHeader(run){
       let r;
       for(let i=0;i<outShapes.length;i++){
         outShapeUsed=i;
         r=await run(outShapes[i]);
         if(!r.error||!isColErr(r.error))return r;
       }
       return r;
     }
     let h;
     if(outEditId){
       // Primary-key update — a second header for the same Record No. is
       // impossible, and the old lines go before the new ones land.
       h=await writeOutHeader(p=>SB.from('outward_entries').update(p).eq('id',outEditId).select().maybeSingle());
       if(h.error)throw h.error;
       if(!h.data)throw new Error(outEditNo+' database me nahi mila — ho sakta hai kisi ne delete kar diya ho. Kuch save nahi hua.');
       const del=await SB.from('outward_lines').delete().eq('outward_id',outEditId);
       if(del.error)throw del.error;
     }else{
       h=await writeOutHeader(p=>SB.from('outward_entries').insert(p).select().single());
       if(h.error)throw h.error;
     }
     // The receiver columns aren't there yet, so Designation / Department print
     // on this PDF but won't come back when the entry is reopened for edit.
     // Said plainly rather than left to be discovered on the next edit.
     if(outShapeUsed>0)showToast('⚠️ Is database me Receiver Designation / Department save nahi hote — edit me dobara Emp Code daalna padega (receiver_designation, receiver_department, receiver_emp_code columns add karein)','warn');
     const ls=[];for(const r of rows){const it=await ensureItem(r.itemName,r.itemDesc,r.make,r.category,r.qtyUom,r.itemId);ls.push({outward_id:h.data.id,item_id:it.id,qty:r.qty,uom:r.qtyUom||it.uom,weight:r.weight})}const ins=await SB.from('outward_lines').insert(ls);if(ins.error)throw ins.error;
     if(msgEl)msgEl.textContent='Generating PDF…';
     const d=collectOutwardData(no),pdfs=await generateStorePdfs('OUTWARD',d,rows,h.data.id,'outPhotoGalleryInput');
     {const b=pdfs.SINGLE?.blob||pdfs.TWO_PAGE?.blob;showSarvPdfPreview(b,pdfs.SINGLE?.name||storePdfFilename_('OUTWARD',d,'SINGLE'),b?'':(pdfs.SINGLE?.html||pdfs.TWO_PAGE?.html||''),
       {docNo:no,party:d.partyName,receiver:d.receiverName,pdfUrl:pdfs.SINGLE?.url||pdfs.TWO_PAGE?.url||'',
        text:(d.entryType==='ISSUE'?'ISSUE ':'OUTWARD ')+no+' — '+(d.partyName||'-')+(d.receiverName?(' | Receiver '+d.receiverName):'')+(d.gatePass?(' | Gate Pass '+d.gatePass):'')});}
     showToast(outEditId?('✅ '+no+' updated — usi Record No. par save hua'):('✅ Outward saved: '+no));
     // Repair-nature outward — refresh the Repair Items Tracker so this
     // entry (and its sent/balance figures) show up immediately, not only
     // after manually opening that tab and clicking Refresh.
     if(pVal('outNatureOfDispatch')==='Repair')loadRepairTracker().catch(()=>{});
     // Entry Type is settled for this panel now — pinned before the clear so
     // the cleared form stays on the type that was just saved.
     sarvOutwardTypePinned=true;
     // ── Clear form after save ──────────────────────────────────
     clearOutwardForm();
     return h.data;
   } finally {
     if(overlay)overlay.classList.remove('active');
     // Label follows the edit state, not the saved original — see the Inward
     // save for the same reasoning.
     if(btn)btn.disabled=false;
     refreshStoreEditUi();
   }
 }
