   // one helper covers a whole filter bar.
   const onFilter=(id,fn)=>{const e=byId(id);if(!e||e.dataset.filterBound)return;
     e.addEventListener('input',fn);e.addEventListener('change',fn);e.dataset.filterBound='1'};

   // ── PO build popup ─────────────────────────────────────────
